local config = {
  ui_story_5083_50830100_1_dialog_content = "Apa alasan di balik mimpi buruk? Sejujurnya... Aku juga tidak benar-benar tahu.",
  ui_story_5083_50830100_2_dialog_content = "Tetapi mereka pasti terhubung dengan ingatan Anda.",
  ui_story_5083_50830100_3_dialog_content = "Mungkin itu masa lalu yang tidak bisa kamu terima, atau penyesalan yang tidak bisa kamu lepaskan—",
  ui_story_5083_50830100_4_dialog_content = "Ini tidak masuk akal bagi saya, jadi berhentilah. Saya percaya kamu, jadi lakukan saja apa yang harus kamu lakukan.",
  ui_story_5083_50830100_5_dialog_content = "Baiklah, lalu berbaring dan rileks saja... Sementara aku mencoba untuk beresonansi dengan pikiranmu...",
  ui_story_5083_50830100_6_dialog_content = "Pria, aku mulai merasa cukup mengantuk... Apakah ini berarti aku akan memiliki mimpi yang sama lagi...?",
  ui_story_5083_50830100_7_dialog_content = "Ah, lupakan saja... Aku yakin aku akan baik-baik saja denganmu di sekitar...",
  ui_story_5083_50830100_8_dialog_content = "Tidurlah... Dan bersiaplah untuk menghadapinya...",
  ui_story_5083_50830100_9_dialog_content = "<color=#e8d9bb>Suara peluit tajam menembus udara.</color>",
  ui_story_5083_50830100_10_dialog_content = "\"Saya tidak tahu apa yang telah saya dengar!\"",
  ui_story_5083_50830100_11_dialog_content = "\"Membunuh Eclipsite tidak pernah membosankan!\"",
  ui_story_5083_50830100_12_dialog_content = "Apa ini…?",
  ui_story_5083_50830100_13_dialog_content = "\"Maju!\"",
  ui_story_5083_50830100_14_dialog_content = "\"March!\"",
  ui_story_5083_50830100_15_dialog_content = "Lapangan latihan, huh? Itu juga lagu latihan lama...",
  ui_story_5083_50830100_16_dialog_content = "Apa yang terjadi, Barton?! Jangan berhenti di tengah trek saja!",
  ui_story_5083_50830100_17_dialog_content = "Anjing... apakah itu kamu...?",
  ui_story_5083_50830100_18_dialog_content = "Masih setengah tertidur? Itu masalahmu, teman.",
  ui_story_5083_50830100_19_dialog_content = "Dogg sebenarnya berhasil melewati Barton?!",
  ui_story_5083_50830100_20_dialog_content = "Nah, ini karena Barton tiba-tiba berhenti... Ini akan menjadi sesuatu yang baik.",
  ui_story_5083_50830100_21_dialog_content = "Barton, kamu idiot! Ini adalah tempat latihan, bukan tempat bermimpi di siang hari!",
  ui_story_5083_50830100_22_dialog_content = "Apa yang terjadi hingga menjadi prajurit teladan terbaik legiun? Jika kamu ingin mempermalukan legiunku dengan malas-malasan, maka keluar saja dari sini!",
  ui_story_5083_50830100_23_dialog_content = "Yang lainnya, terus berlari!",
  ui_story_5083_50830100_24_dialog_content = "Komandan Pango, hmph... Siapa bilang aku bermalas-malasan?!",
  ui_story_5083_50830100_25_dialog_content = "Coba saja untuk mengikutiku!",
  ui_story_5083_50830100_26_dialog_content = "\"Berikan senjata!\"",
  ui_story_5083_50830100_27_dialog_content = "Ambil ini—Arghhh!",
  ui_story_5083_50830100_28_dialog_content = "Jangan biarkan dia mengacaukan irama kalian, prajurit! Ulangi setelah saya—\"Cinta senjataku, ya aku lakukan!\"",
  ui_story_5083_50830100_29_dialog_content = "\"Cinta senjataku, ya aku memang begitu!\"",
  ui_story_5083_50830100_30_dialog_content = "\"Ada banyak amunisi siap untukmu—\"",
  ui_story_5083_50830100_31_dialog_content = "<size=45>Ooooooh!</size>",
  ui_story_5083_50830100_32_dialog_content = "Heh, akhirnya kamu mengejar, Barton.",
  ui_story_5083_50830100_33_dialog_content = "Huff—Huff—Itu bukan apa-apa!",
  ui_story_5083_50830100_34_dialog_content = "Yakin dengan itu? Melihat wajahmu yang terengah-engah, aku cukup yakin aku akan memenangkan lap terakhir ini.",
  ui_story_5083_50830100_35_dialog_content = "Heh... Kita... lihat saja hasilnya!",
  ui_story_5083_50830100_36_dialog_content = "Dua orang idiot itu...",
  ui_story_5083_50830100_37_dialog_content = "<color=#e8d9bb>Dua prajurit berjuang keras untuk memimpin, meninggalkan sisa dari 2nd Legion jauh di belakang.</color>",
  ui_story_5083_50830100_38_dialog_content = "<color=#e8d9bb>Tak mau mengakui kekalahan, mereka menumpahkan seluruh hati dan kekuatan mereka untuk meraih tempat pertama.</color>",
  ui_story_5083_50830100_39_dialog_content = "<color=#e8d9bb>Lebih cepat dan lebih cepat, mereka mendorong diri mereka sendiri sampai—</color>",
  ui_story_5083_50830100_40_dialog_content = "<size=45>Hraaaaahhhh!!!</size>",
  ui_story_5083_50830100_41_dialog_content = "<color=#e8d9bb>Menggunakan sisa energi mereka, kedua orang itu melompat melewati garis finish dan jatuh tersungkur di wajah mereka.</color>",
  ui_story_5083_50830100_42_dialog_content = "*terengah* Y-Yah? Kamu yakin sekarang?",
  ui_story_5083_50830100_43_dialog_content = "Meski telah memberimu keunggulan, aku masih bisa mengejarmu.",
  ui_story_5083_50830100_44_dialog_content = "Hmph... Aku hanya sedang menyimpan energiku tadi... Lagipula, kamu tidak benar-benar menang, 'kan?",
  ui_story_5083_50830100_45_dialog_content = "<color=#e8d9bb>Saat sisanya dari para prajurit melintasi garis finish satu per satu, suara peluit kembali terdengar—</color>",
  ui_story_5083_50830100_46_dialog_content = "Latihan hari ini sudah selesai, jadi kenapa kalian masih saja berbaring? Biasanya, kalian sudah sibuk makan di ruang makan!",
  ui_story_5083_50830100_47_dialog_content = "Apa masalahnya? Tidak bisa berdiri, bukan?",
  ui_story_5083_50830100_48_dialog_content = "Kamu berharap. Ayo pergi!",
  ui_story_5083_50830100_49_dialog_content = "Aku penasaran makan siang apa hari ini...",
  ui_story_5083_50830100_50_dialog_content = "Apa pun selain batang energi lainnya dalam oatmeal saya! Saya sudah cukup dengan itu.",
  ui_story_5083_50830100_51_dialog_content = "Lihat, Barton... Periksa jam 9 Anda.",
  ui_story_5083_50830100_52_dialog_content = "Kantinnya ramai hari ini... Tidak, tunggu, ada apa di sana?",
  ui_story_5083_50830100_53_dialog_content = "Letnan Reinhardt! Kamu sangat kuat! Bagaimana saya bisa berlatih untuk menjadi sekuat kamu?",
  ui_story_5083_50830100_54_dialog_content = "Berlatih keras, kurasa.",
  ui_story_5083_50830100_55_dialog_content = "Apakah tidak masalah jika saya berlatih dengan Anda waktu berikutnya, Letnan?",
  ui_story_5083_50830100_56_dialog_content = "Tentu, selama kamu bisa mengikutinya. Latihan saya bisa sedikit keras kadang-kadang.",
  ui_story_5083_50830100_57_dialog_content = "Bisakah Anda melihat ke sini, Letnan? Tersenyum ke kamera—",
  ui_story_5083_50830100_58_dialog_content = "Hahaha, keju!",
  ui_story_5083_50830100_59_dialog_content = "Tentang apa ini?",
  ui_story_5083_50830100_60_dialog_content = "Aku dengar dia lulus dua tahun lebih awal, sama seperti kamu. Rupanya kita punya <color=#FFB400>super kadet</color> lain di tangan kita.",
  ui_story_5083_50830100_61_dialog_content = "Tapi berbeda dengan kamu, dia selalu dikelilingi oleh kerumunan. Mungkin ini berarti kepribadianmu perlu sedikit diperbaiki, ya, Barton?",
  ui_story_5083_50830100_62_dialog_content = "... Meski begitu, sulit membayangkan bahwa seseorang seperti dia berada di level yang sama dengan kamu.",
  ui_story_5083_50830100_63_dialog_content = "Seorang lawan yang layak...",
  ui_story_5083_50830100_64_dialog_content = "Oh? Seseorang yang menarik baru saja muncul...",
  ui_story_5083_50830100_65_dialog_content = "Maaf...?",
  ui_story_5083_50830100_66_dialog_content = "Tak apa. Nah, sekarang, bisa tolong minggir? Aku cukup lapar.",
  ui_story_5083_50830100_67_dialog_content = "T-Tolong izinkan aku duduk bersamamu—",
  ui_story_5083_50830100_68_dialog_content = "Dia jelas hanya anggota baru tanpa prestasi nyata untuk dibicarakan. Dari yang saya dengar, dia hanya mendapatkan perhatian jenis ini karena komite mendukungnya.",
  ui_story_5083_50830100_69_dialog_content = "Huh, hanya hiasan lain untuk orang-orang penting. Dia bukan tandinganmu... Dan bahkan lebih tidak layak menjadi tandinganku!",
  ui_story_5083_50830100_70_dialog_content = "Cahaya itu...",
  ui_story_5083_50830100_71_dialog_content = "Apa?",
  ui_story_5083_50830100_72_dialog_content = "Menarik... Dia memancarkan cahaya yang tak terbantahkan, yang membuatku sulit untuk berpaling.",
  ui_story_5083_50830100_73_dialog_content = "Sesuatu memberitahuku bahwa salah satu dari kita akan menjadi Grand Marshal di masa depan.",
  ui_story_5083_50830100_74_dialog_content = "Butuh lebih banyak untuk memutuskan Grand Marshal baru... Tunggu, jangan bilang kamu juga terbutakan oleh cahaya palsu orang itu?",
  ui_story_5083_50830100_75_dialog_content = "... Oh, tidak! Orang-orang sial ini akan memakan semua makanan enak jika kita tidak masuk ke sana sekarang juga!",
  ui_story_5083_50830100_76_dialog_content = "Hei, tunggu aku!",
  ui_story_5083_50830100_77_dialog_content = "Kami harus berjuang mati-matian untuk beberapa kaleng buah. Makanan kami bahkan lebih menakutkan daripada sesi latihan kami kadang-kadang.",
  ui_story_5083_50830100_78_dialog_content = "Aku mau yang apel. Bagaimana dengan kamu?",
  ui_story_5083_50830100_79_dialog_content = "Aku tidak peduli, berikan saja apa yang tersisa... Hai!",
  ui_story_5083_50830100_80_dialog_content = "Ups!",
  ui_story_5083_50830100_81_dialog_content = "Lihat, itu gadis yang mengalahkanmu di kompetisi terakhir! Saya dengar dia sudah menjadi Petugas Teknologi.",
  ui_story_5083_50830100_82_dialog_content = "Tidak ada yang meminta perkenalan, sekarang kembalikan kaleng itu padaku!",
  ui_story_5083_50830100_83_dialog_content = "Oh ya, kamu adalah orang itu... Uh... Ah, biarlah! Pertandingan yang baik, rekan prajurit!",
  ui_story_5083_50830100_84_dialog_content = "Itu Barton! Kamu bahkan tidak mencoba untuk mengingat namaku, 'kan?!",
  ui_story_5083_50830100_85_dialog_content = "Maaf, hanya saja aku telah mengeliminasi kamu begitu mudah, bersama dengan sekelompok orang lain.",
  ui_story_5083_50830100_86_dialog_content = "Tch... Kita akan menentukan pemenang sebenarnya lain kali, Gronru! Ingat kata-kataku!",
  ui_story_5083_50830100_87_dialog_content = "Tunggu saja... Aku akan memenangkan semuanya kembali dan lebih banyak lagi!",
  ui_story_5083_50830100_88_dialog_content = "Aku rasa aku belum pernah melihat seorang prajurit mencuci piring dengan begitu marah, Barton. Aku harus bilang, aku terkesan!",
  ui_story_5083_50830100_89_dialog_content = "... C-Komandan!",
  ui_story_5083_50830100_90_dialog_content = "Matahari pasti sudah terbit di kota bawah tanah ini pagi ini. Kamu biasanya hanya membilas piring sebelum melemparkannya ke samping, tetapi sekarang kamu mencucinya seolah-olah hidupmu bergantung padanya.",
  ui_story_5083_50830100_91_dialog_content = "Katakan padaku, apakah kamu memukul kepala kamu atau sesuatu?",
  ui_story_5083_50830100_92_dialog_content = "Tidak sama sekali, Pak!",
  ui_story_5083_50830100_93_dialog_content = "Lalu katakan padaku apa yang sedang terjadi sekarang.",
  ui_story_5083_50830100_94_dialog_content = "Saya tidak tahu, pak. Saya rasa saya butuh hari libur untuk menyelesaikan semuanya!",
  ui_story_5083_50830100_95_dialog_content = "Kesulitan menyeimbangkan kerja dan istirahat? Atau mungkin pertempuran itu memberikan dampak yang terlalu besar padamu? Kamu tidak masih merasa takut, bukan?",
  ui_story_5083_50830100_96_dialog_content = "Tidak, pak. Bukan itu!",
  ui_story_5083_50830100_97_dialog_content = "Lalu tenangkan dirimu, prajurit! Tapi lagi, kamu jauh lebih produktif seperti ini—",
  ui_story_5083_50830100_98_dialog_content = "Wow!",
  ui_story_5083_50830100_99_dialog_content = "Tapi kamu masih lemah dan penuh celah! Kamu benar-benar berpikir bisa menjadi bintang bersinar dari 2nd Legion?",
  ui_story_5083_50830100_100_dialog_content = "Tuan, saya tidak mengharapkan serangan mendadak dari seseorang yang saya percaya!",
  ui_story_5083_50830100_101_dialog_content = "Aku mengajarkanmu untuk selalu menjaga kewaspadaan dan senjatamu siap. Jika kamu melakukan seperti yang kuperintahkan, aku tidak akan bisa mengejutkanmu dengan begitu mudah.",
  ui_story_5083_50830100_102_dialog_content = "Kamu tampaknya tidak yakin, tetapi strategi apapun yang mengarah ke kemenangan itu benar! Tidak semua masalah memerlukan pendekatan langsung, dan dalam perang, hasil adalah segalanya.",
  ui_story_5083_50830100_103_dialog_content = "Sepertinya kamu masih membutuhkan temperamen sebelum bisa digunakan dalam pertempuran.",
  ui_story_5083_50830100_104_dialog_content = "Kembali ke lapangan latihan dan berikan aku dua puluh putaran lagi dengan kecepatan biasamu!",
  ui_story_5083_50830100_105_dialog_content = "... Ya pak!",
  ui_story_5083_50830100_106_dialog_content = "Sangat hening di sini, bukan? Bagaimana aku bisa tahu jika kamu benar-benar berlari, prajurit?! Biarkan aku mendengar kamu bernyanyi dengan keras!",
  ui_story_5083_50830100_107_dialog_content = "Siap, Pak!",
  ui_story_5083_50830100_108_dialog_content = "\"I don't know what I've been told!\"",
  ui_story_5083_50830100_109_dialog_content = "Lebih keras!",
  ui_story_5083_50830100_110_dialog_content = "<size=45>\"Membunuh Eclipsite tidak pernah membosankan!\"</size>",
  ui_story_5083_50830100_111_dialog_content = "Apa ini... apakah Barton sedang melakukan latihan tambahan di samping?",
  ui_story_5083_50830100_112_dialog_content = "Kau tidak akan bisa mendahuluiku seperti itu!",
  ui_story_5083_50830100_113_dialog_content = "Hei Barton! Aku berhasil mengejarmu lagi!",
  ui_story_5083_50830100_114_dialog_content = "Ini bukan balapan, idiot.",
  ui_story_5083_50830100_115_dialog_content = "Sekarang saatnya saya di sini, dan kamu tidak akan mengambil posisi pertama di jam tangan saya!",
  ui_story_5083_50830100_116_dialog_content = "Argh—Kembali kesini, kamu idiot!",
  ui_story_5083_50830100_117_dialog_content = "Kamu itu idiot!",
  ui_story_5083_50830100_118_dialog_content = "Hahahaha—",
  ui_story_5083_50830100_119_dialog_content = "Letnan Reinhardt?",
  ui_story_5083_50830100_120_dialog_content = "Mereka berdua... menarik.",
  ui_story_5083_50830200_1_dialog_content = "<color=#e8d9bb>A shrill whistle pierces the air.</color>",
  ui_story_5083_50830200_2_dialog_content = "Berpakaian dan ambil perlengkapanmu!",
  ui_story_5083_50830200_3_dialog_content = "Dengan cepat, gerutu!",
  ui_story_5083_50830200_4_dialog_content = "Aaaaaahhh—",
  ui_story_5083_50830200_5_dialog_content = "Hnng...?",
  ui_story_5083_50830200_6_dialog_content = "Tiga dua satu!",
  ui_story_5083_50830200_7_dialog_content = "<color=#e8d9bb>Seember air es menyiram Barton, membuatnya merasa kedinginan sampai ke tulang dan membuatnya terjaga sepenuhnya.</color>",
  ui_story_5083_50830200_8_dialog_content = "<size=45>Aaaahhhh!!!</size>",
  ui_story_5083_50830200_9_dialog_content = "Ayo bergerak, kalian yang malas dan tidak berguna! Tanpa rasa sakit, tidak ada keuntungan!",
  ui_story_5083_50830200_10_dialog_content = "Jika kamu tidak bisa bangun dan siap bertempuran dalam waktu kurang dari lima detik, bagaimana kamu berharap bisa bertahan di garis depan?",
  ui_story_5083_50830200_11_dialog_content = "Kamu perlu secepat dan sefatal peluru! Kamu memiliki sepuluh detik untuk sampai di lapangan latihan; dua kali lipat latihan bagi siapa saja yang terlambat!",
  ui_story_5083_50830200_12_dialog_content = "Dan Barton, kamu harus memakai ember ini di kepalamu!",
  ui_story_5083_50830200_13_dialog_content = "Jika kamu belum mengejar ketika Dogg memasuki putaran keduanya, aku akan memberimu tambahan satu putaran untuk setiap detik yang dibutuhkan!",
  ui_story_5083_50830200_14_dialog_content = "Sial, aku dingin dan basah kuyup... Aku tidak bisa memakai ikat pinggangku! Kenapa harus aku?!",
  ui_story_5083_50830200_15_dialog_content = "Begitu lah! Jika kamu mendengarkan aku, tetap waspada, dan selalu siap dengan senjatamu, kamu tidak akan berada dalam kekacauan seperti ini!",
  ui_story_5083_50830200_16_dialog_content = "Kamu pikir Eclipsite akan menunggu kamu mandi dan menikmati sarapan yang enak? Mereka bisa menyerang dari mana saja kapan saja, jadi kita harus selalu tetap waspada!",
  ui_story_5083_50830200_17_dialog_content = "Bagaimana aku bisa melindungi diriku dari air saat tidur?!",
  ui_story_5083_50830200_18_dialog_content = "Itu masalahmu, bukan milikku! Jika kamu tidak bisa tetap kering, kamu bisa lupakan tentang menjadi contoh untuk siapa pun!",
  ui_story_5083_50830200_19_dialog_content = "Ini benar-benar tidak masuk akal... Saya akan baik-baik saja selama saya memiliki senjata—",
  ui_story_5083_50830200_20_dialog_content = "Senjata tidak seharusnya menjadi hal pertama yang kamu cari, kau idiot! Sekarang berhenti mengotak-atik ikat pinggangmu dan ayo bergerak!",
  ui_story_5083_50830200_21_dialog_content = "Anjing itu juga berlari secepat yang dia bisa! Dia bahkan tidak mencoba membantu saya!",
  ui_story_5083_50830200_22_dialog_content = "Heh! Sekarang tunjukkan padaku bagaimana rencanamu untuk mengejar mereka.",
  ui_story_5083_50830200_23_dialog_content = "Aku tidak menyerah! <size=45>Lihat ini!</size>",
  ui_story_5083_50830200_24_dialog_content = "<color=#e8d9bb>Barton mengaum saat ia melempar ember ke samping dan merobek celananya menjadi celana pendek, lalu berlari gila-gilaan menuju sisa kelompoknya.</color>",
  ui_story_5083_50830200_25_dialog_content = "Bahkan Barton kadang-kadang memiliki awal yang lambat, ya? Itu sama sekali tidak seperti dia...",
  ui_story_5083_50830200_26_dialog_content = "<size=45>Saya datang untukmu, Dogg!!!</size>",
  ui_story_5083_50830200_27_dialog_content = "Ini kamu—ada apa dengan tatapan itu?!",
  ui_story_5083_50830200_28_dialog_content = "Pakaianmu semua kusut dan robek... Apa kamu, seorang badut?! Berhenti mencoba untuk menodai 2nd Legion!",
  ui_story_5083_50830200_29_dialog_content = "Diam! Celanaku hanya menghambatku mengejarmu, jadi apa alasanmu membiarkanku?!",
  ui_story_5083_50830200_30_dialog_content = "Kamu terlihat sangat konyol sampai-sampai aku harus melambat dan memarahimu!",
  ui_story_5083_50830200_31_dialog_content = "Hah! Kamu jelas-jelas takut barusan—",
  ui_story_5083_50830200_32_dialog_content = "<color=#e8d9bb>Tiba-tiba, seseorang berlari melewati kedua orang tersebut, menghentikan pertengkaran kecil mereka.</color>",
  ui_story_5083_50830200_33_dialog_content = "Hup, dua, tiga, empat...",
  ui_story_5083_50830200_34_dialog_content = "...",
  ui_story_5083_50830200_35_dialog_content = "<color=#e8d9bb>Terpaku diam, Barton dan Dogg berusaha sekuat tenaga untuk mengimbangi tantangan terbaru mereka.</color>",
  ui_story_5083_50830200_36_dialog_content = "Hup, two, three, four...",
  ui_story_5083_50830200_37_dialog_content = "<color=#e8d9bb>Makin cepat dan cepat, ketiganya berlari... Dengan para prajurit lainnya yang menonton mereka dengan saksama, mereka menyelesaikan beberapa putaran dengan kecepatan yang sangat tinggi—dan berlari langsung melewati garis finis.</color>",
  ui_story_5083_50830200_38_dialog_content = "Aku tidak akan kalah—",
  ui_story_5083_50830200_39_dialog_content = "<color=#e8d9bb>Ketiganya melewati garis finis pada saat yang sama. Benar-benar lelah, Barton dan Dogg membawa diri mereka untuk berhenti secara bertahap. Namun—</color>",
  ui_story_5083_50830200_40_dialog_content = "Hup, two, three, four...",
  ui_story_5083_50830200_41_dialog_content = "<color=#e8d9bb>Reinhardt terus berlari, meskipun dengan kecepatan yang sedikit lebih lambat.</color>",
  ui_story_5083_50830200_42_dialog_content = "Mana mungkin...",
  ui_story_5083_50830200_43_dialog_content = "Dia mengambilnya terlalu jauh.",
  ui_story_5083_50830200_44_dialog_content = "Kita tidak bisa membiarkan dia mengejek kita seperti ini. Apakah kamu masih bisa berlari?",
  ui_story_5083_50830200_45_dialog_content = "Tentu saja saya bisa! Ayo—",
  ui_story_5083_50830200_46_dialog_content = "<color=#e8d9bb>Suara peluit berbunyi, dan setiap prajurit berkumpul di sekitar komandan.</color>",
  ui_story_5083_50830200_47_dialog_content = "Tch, ayo kita bergabung dengan yang lain.",
  ui_story_5083_50830200_48_dialog_content = "Dia bersama 1st Legion, bukan? Dia punya nyali, mengganggu latihan 2nd Legion dan mengejek kami seperti itu...",
  ui_story_5083_50830200_49_dialog_content = "Apa pun. Apa gunanya bertahan jika kita bahkan tidak bisa mengimbangi rookie terbaru dari 1st Legion?",
  ui_story_5083_50830200_50_dialog_content = "Pfft—",
  ui_story_5083_50830200_51_dialog_content = "Jika kamu tidak bisa mengalahkan saya, apa yang membuatmu berpikir kamu akan bisa mengejar Reinhardt?",
  ui_story_5083_50830200_52_dialog_content = "Bukan kamu lagi... Hmph, jangan terlalu sombong. Aku hanya perlu terus tumbuh dan menjadi lebih kuat.",
  ui_story_5083_50830200_53_dialog_content = "Oh? Jadi kamu tidak menyangkal bahwa aku telah mengalahkanmu?",
  ui_story_5083_50830200_54_dialog_content = "Benar. Tidak ada gunanya menyangkalnya ketika aku jelas-jelas kalah—",
  ui_story_5083_50830200_55_dialog_content = "Tapi pertanyaan sebenarnya adalah... Mengapa kamu berada di tempat teduh selama latihan?!",
  ui_story_5083_50830200_56_dialog_content = "Aku ingin kamu tahu bahwa sebagai Tech Officer, aku sedang melakukan banyak pekerjaan serius sekarang ini!",
  ui_story_5083_50830200_57_dialog_content = "Kerja serius, kakiku... Dan apa itu dengan alat itu?",
  ui_story_5083_50830200_58_dialog_content = "Berhenti bermain-main di sini, Barton. Kita seharusnya berkumpul dengan yang lain.",
  ui_story_5083_50830200_59_dialog_content = "Jangan khawatir, orang tua itu bisa menunggu beberapa detik lagi—",
  ui_story_5083_50830200_60_dialog_content = "Jangan meremehkan penemuan terbaru saya! Ini memiliki potensi untuk mengubah kehidupan setiap prajurit di Illumina—",
  ui_story_5083_50830200_61_dialog_content = "Memperkenalkan Drone Asisten Cerdas Generasi Berikutnya! Setelah ini diproduksi, mereka akan menjadi penjaga belakang optimal setiap prajurit.",
  ui_story_5083_50830200_62_dialog_content = "Wow! Apakah ini berarti kamu telah menjadi lebih kuat sejak Emperor's Cup terakhir?",
  ui_story_5083_50830200_63_dialog_content = "Nah, sekarang kamu mulai paham, kan? Lihat? Kamu tidak tahu berapa banyak waktu yang telah aku habiskan untuk desain ini!",
  ui_story_5083_50830200_64_dialog_content = "Barton!",
  ui_story_5083_50830200_65_dialog_content = "Apa?!",
  ui_story_5083_50830200_66_dialog_content = "Barton! Dogg! Apa yang kalian pikirkan sedang kalian lakukan?!",
  ui_story_5083_50830200_67_dialog_content = "Ganti seragam kalian dan bawa pantat malas kalian ke Central Tower! Kalian akan berdiri di bawah cahayanya sepanjang hari, tanpa pengecualian!!!",
  ui_story_5083_50830200_68_dialog_content = "A-apa?!?",
  ui_story_5083_50830200_69_dialog_content = "<color=#e8d9bb>Menara Sentral. Hub transportasi yang ramai dan terang ini berfungsi sebagai jantung Kota Gannon—</color>",
  ui_story_5083_50830200_70_dialog_content = "<color=#e8d9bb>Serta tempat yang sangat mencolok untuk menghukum tentara Illumina yang lebih nakal.</color>",
  ui_story_5083_50830200_71_dialog_content = "...",
  ui_story_5083_50830200_72_dialog_content = "...",
  ui_story_5083_50830200_73_dialog_content = "... Maaf.",
  ui_story_5083_50830200_74_dialog_content = "Hah?",
  ui_story_5083_50830200_75_dialog_content = "Aku adalah alasan kamu juga mendapatkan...",
  ui_story_5083_50830200_76_dialog_content = "Kamu telah bertingkah sangat aneh beberapa hari terakhir ini, Barton.",
  ui_story_5083_50830200_77_dialog_content = "Apakah karena pertempuran itu?",
  ui_story_5083_50830200_78_dialog_content = "Aku bilang jangan terlalu banyak berpikir, Pria. Kamu tidak sepenuhnya salah untuk itu.",
  ui_story_5083_50830200_79_dialog_content = "Hal-hal hanya tidak berjalan sesuai keinginanmu, itu saja... Jadi berhenti merajuk. Jika tidak, tidak akan terasa benar ketika aku akhirnya mengalahkanmu.",
  ui_story_5083_50830200_80_dialog_content = "Setelah semua... Komandan Pango pernah bilang kamu adalah yang paling menjanjikan di antara rekrutan barunya.",
  ui_story_5083_50830200_81_dialog_content = "Hah? Dia benar-benar memuji saya?",
  ui_story_5083_50830200_82_dialog_content = "Terkadang kamu benar-benar idiot—",
  ui_story_5083_50830200_83_dialog_content = "Terima kasih, Dogg.",
  ui_story_5083_50830200_84_dialog_content = "?!",
  ui_story_5083_50830200_85_dialog_content = "Hampir saja aku lupa, tapi aku belum sempat berterima kasih dengan benar atas bantuanmu waktu itu.",
  ui_story_5083_50830200_86_dialog_content = "Jadi, terima kasih telah datang menyelamatkan saya tepat pada waktunya.",
  ui_story_5083_50830200_87_dialog_content = "... Aku hanya mengikuti perintah Komandan Pango, jadi jangan sebut itu.",
  ui_story_5083_50830200_88_dialog_content = "Ugh... Panas sekali—",
  ui_story_5083_50830200_89_dialog_content = "<color=#e8d9bb>Di bawah terangnya cahaya Central Tower, dua prajurit menghabiskan seluruh hari dengan berkeringat dan berdiri tegak.</color>",
  ui_story_5083_50830200_90_dialog_content = "<color=#e8d9bb>Di akhir hari, komandan tanpa ampun mereka akhirnya muncul dan membebaskan mereka dari hukuman mereka—</color>",
  ui_story_5083_50830200_91_dialog_content = "Akhirnya... Sedetik lagi dan cahaya Illumina akan membuatku kering terpanggang.",
  ui_story_5083_50830200_92_dialog_content = "Aku heran Dogg masih punya cukup energi untuk pergi ke ruang makan... Kayaknya aku akan mandi dulu...",
  ui_story_5083_50830200_93_dialog_content = "Bip—Barton terlihat.",
  ui_story_5083_50830200_94_dialog_content = "Hah? Itu drone... Dan dia tahu siapa saya?",
  ui_story_5083_50830200_95_dialog_content = "Tunggu, apakah kamu drone Gronru dari sebelumnya hari ini?",
  ui_story_5083_50830200_96_dialog_content = "Tidak, Barton... Aku adalah Navigatormu.",
  ui_story_5083_50830200_97_dialog_content = "Eh? Maksudmu apa, hah?",
  ui_story_5083_50830200_98_dialog_content = "Saya di sini untuk memandu kamu...",
  ui_story_5083_50830200_99_dialog_content = "Itu tidak benar-benar menjelaskan semuanya... Tahu kan, meskipun penampilanmu terlihat kuno, saya menemukan Anda cukup menarik.",
  ui_story_5083_50830200_100_dialog_content = "...Apakah ini berarti drone sekarang menjadi peralatan standar?",
  ui_story_5083_50830200_101_dialog_content = "Saya tidak keberatan sama sekali! Nah, jika kamu di sini untuk memandu saya, maka tunjukkan jalannya!",
  ui_story_5083_50830200_102_dialog_content = "Aku mengerti.",
  ui_story_5083_50830200_103_dialog_content = "Bip—Barton, aku...",
  ui_story_5083_50830200_104_dialog_content = "Aku akan memandu kamu keluar dari ini...",
  ui_story_5083_50830301_1_dialog_content = "Bip—Barton... Sensor saya menunjukkan bahwa kamu membutuhkan mandi...",
  ui_story_5083_50830301_2_dialog_content = "Shower di asrama saat ini penuh. Mencari opsi alternatif... Saya telah menemukan rumah mandi umum di sektor perumahan. Sekarang merutekan... Silakan ikuti saya.",
  ui_story_5083_50830301_3_dialog_content = "Hei, tidak buruk sama sekali! Kamu jauh lebih pintar daripada model lain yang pernah saya lihat!",
  ui_story_5083_50830301_4_dialog_content = "Mungkin aku harus membuka dirimu dan melihat apa yang ada di dalamnya?",
  ui_story_5083_50830301_5_dialog_content = "Bip—Bip—Tolong jangan—",
  ui_story_5083_50830301_6_dialog_content = "Cuma bercanda, anak kecil. Membongkar model yang belum pernah dilihat seperti kamu mungkin akan membuatku berada dalam masalah yang tak terkira.",
  ui_story_5083_50830301_7_dialog_content = "Bip—Tujuan kita berjarak 300 meter. Di persimpangan berikutnya, silakan naik lift ke lantai dua.",
  ui_story_5083_50830301_8_dialog_content = "Kamu benar-benar sangat membantu, nak! Kadang-kadang, Gannon City bisa sangat sulit untuk dinavigasi.",
  ui_story_5083_50830301_9_dialog_content = "Aku hanya berharap kita bisa menggunakan kamu di Undercity lainnya!",
  ui_story_5083_50830301_10_dialog_content = "Lokasi saat ini: Sektor Perumahan, Gang 9, Lantai Atas... Lokasi selanjutnya: Monumen Pusat—",
  ui_story_5083_50830301_11_dialog_content = "Tunggu.",
  ui_story_5083_50830301_12_dialog_content = "Beep—Ya, Barton...?",
  ui_story_5083_50830301_13_dialog_content = "Itu memorial...",
  ui_story_5083_50830301_14_dialog_content = "Bahkan dari sini, aku masih bisa melihatnya dengan jelas.",
  ui_story_5083_50830301_15_dialog_content = "Aku bertanya-tanya... apakah nama mereka sudah ditambahkan ke dalamnya?",
  ui_story_5083_50830301_16_dialog_content = "<color=#e8d9bb>Pertempuran itu, yang terjadi tidak lama lalu, adalah pengalaman pertama Barton dalam pertempuran langsung.</color>",
  ui_story_5083_50830301_17_dialog_content = "<color=#e8d9bb>Itu adalah hari yang gelap dan mendung. Hujan turun seperti benang yang tak terhitung jumlahnya, tak berujung dari langit.</color>",
  ui_story_5083_50830301_18_dialog_content = "Cepat! Pindahkan karung pasir itu ke garis paling depan kita!",
  ui_story_5083_50830301_19_dialog_content = "Parit kedua di sisi kanan kita telah dipenuhi oleh Eclipsites! Kirimkan tentara untuk membersihkannya secepatnya!",
  ui_story_5083_50830301_20_dialog_content = "Kami tidak memiliki cukup samsak, Ma'am!",
  ui_story_5083_50830301_21_dialog_content = "Atau tentara, sejatinya... Kami tidak bisa mengamankan semua posisi kami lagi.",
  ui_story_5083_50830301_22_dialog_content = "Apakah orang-orang sudah selesai dievakuasi?",
  ui_story_5083_50830301_23_dialog_content = "Tidak, Ma'am... Kerusakan pada inti tenaga Undercity telah mengunci sebagian besar sistem transportasi kami, membuat evakuasi menjadi jauh lebih lambat.",
  ui_story_5083_50830301_24_dialog_content = "Sekarang kita harus bagaimana?",
  ui_story_5083_50830301_25_dialog_content = "Temukan apa pun yang bisa Anda gunakan untuk memperkuat pertahanan garis depan kita, dan bagi sisanya pekerjaan di antara pasukan kita yang tersisa. Tidak ada pilihan lain.",
  ui_story_5083_50830301_26_dialog_content = "Di mana Letnan Barton? Saya tidak bisa membuat semua keputusan di sini, jadi saya akan membiarkannya menilai situasi.",
  ui_story_5083_50830301_27_dialog_content = "Dia baru saja kembali dari garis depan, dan sedang beristirahat di belakang.",
  ui_story_5083_50830301_28_dialog_content = "Pengintai! Berapa lama lagi sampai monster-monster itu melancarkan serangan lain?",
  ui_story_5083_50830301_29_dialog_content = "Tidak lama lagi, Kapten! Mereka sedang memulihkan kekuatan mereka saat ini juga!",
  ui_story_5083_50830301_30_dialog_content = "Dimana Comms Officer? Apakah kita sudah selesai memperbaiki jalan? Berapa lama lagi Komandan Pango dan para soldiernya akan sampai di sini?!",
  ui_story_5083_50830301_31_dialog_content = "Saya minta maaf, Bu, tapi seluruh tim komunikasi sudah pergi sekarang.",
  ui_story_5083_50830301_32_dialog_content = "Apa perintah Anda, Ma'am?",
  ui_story_5083_50830301_33_dialog_content = "Komandan Pango dan pasukannya pasti akan datang. Kita hanya perlu bertahan sampai saat itu.",
  ui_story_5083_50830301_34_dialog_content = "Enam Undercity kita sedang diserang sekarang ini, dan ada orang-orang di luar sana yang lebih membutuhkan bantuan daripada kita.",
  ui_story_5083_50830301_35_dialog_content = "Jika komandan tertahan di garis depan...",
  ui_story_5083_50830301_36_dialog_content = "Maka kita harus bertahan untuk orang-orang itu juga.",
  ui_story_5083_50830301_37_dialog_content = "Bagaimana kita bisa... Aku masih punya keluarga di kampung halaman...",
  ui_story_5083_50830301_38_dialog_content = "Maaf... Tapi aku tidak bisa menjanjikan apapun padamu sekarang.",
  ui_story_5083_50830301_39_dialog_content = "Tugas kita adalah melindungi tempat ini dengan nyawa kita. Kita tidak bisa membiarkan Eclipsite lolos dari kita.",
  ui_story_5083_50830301_40_dialog_content = "Rekan-rekan kita di Illumina mengandalkan kita untuk melindungi mereka...",
  ui_story_5083_50830301_41_dialog_content = "Jika kita harus mati, kita mati dengan terhormat di medan perang.",
  ui_story_5083_50830301_42_dialog_content = "Aku takut... Ibu memberiku syal baru sebelum aku pergi, tapi sekarang... Aku bahkan tidak ingat kapan syal ini terbakar seperti ini...",
  ui_story_5083_50830301_43_dialog_content = "...",
  ui_story_5083_50830301_44_dialog_content = "... Aku tahu ini salah, tapi minta seseorang bangunkan Letnan Barton sekarang juga.",
  ui_story_5083_50830301_45_dialog_content = "Mungkin dia akan tahu apa yang harus dilakukan.",
  ui_story_5083_50830301_46_dialog_content = "Letnan Barton—Letnan—",
  ui_story_5083_50830301_47_dialog_content = "Apa itu? Rasanya seperti baru saja tertidur... Tapi tak apa. Kamu juga istirahatlah; tidak ada yang tahu kapan mereka akan menyerang lagi.",
  ui_story_5083_50830301_48_dialog_content = "Pak! Pasukan komunikasi kita telah dieliminasi, dan kita tidak memiliki cara untuk berkomunikasi dengan sisanya Legion.",
  ui_story_5083_50830301_49_dialog_content = "Komandan Batalyon dan Officer Disiplin... juga hilang saat menutupi mundur kami terakhir kali.",
  ui_story_5083_50830301_50_dialog_content = "Mengerti... Menurut rantai komando, seharusnya sekarang aku yang bertanggung jawab, 'kan?",
  ui_story_5083_50830301_51_dialog_content = "Berikan aku peta itu.",
  ui_story_5083_50830301_52_dialog_content = "Mata-mata kita melaporkan bahwa Eclipsite berkumpul di dataran tinggi di utara. Saat ini kita tidak memiliki cara untuk menyerang mereka dari jarak jauh.",
  ui_story_5083_50830301_53_dialog_content = "Sebagian besar fungsi Undercity dinonaktifkan setelah gelombang pertama serangan.",
  ui_story_5083_50830301_54_dialog_content = "Pada titik ini, kami tidak memiliki cara untuk mengetahui jika atau kapan komandan akan tiba dengan bala bantuan.",
  ui_story_5083_50830301_55_dialog_content = "Juga... Beberapa prajurit percaya kita harus meninggalkan posisi ini dan evakuasi bersama dengan warga sipil.",
  ui_story_5083_50830301_56_dialog_content = "Tapi itu berarti meninggalkan seluruh Undercity, Pak!",
  ui_story_5083_50830301_57_dialog_content = "Berapa banyak orang yang kita miliki tersisa?",
  ui_story_5083_50830301_58_dialog_content = "Kurang dari tiga ratus... Kita hanya tidak memiliki jumlah yang cukup untuk mempertahankan Undercity ini lagi.",
  ui_story_5083_50830301_59_dialog_content = "... Ini jauh lebih sulit daripada simulasi militer apa pun, itu pasti.",
  ui_story_5083_50830301_60_dialog_content = "Tidak bisa percaya bahwa orang tua itu berpikir kita bisa mempertahankan seluruh kota sendirian... Jika kita tidak mempertaruhkan nyawa untuk menerobos keluar, mungkin kita sudah mati di sana.",
  ui_story_5083_50830301_61_dialog_content = "Sepertinya hanya ada satu pilihan yang tersisa untuk kita...",
  ui_story_5083_50830301_62_dialog_content = "Letnan Barton! <size=45>Seorang kurir telah tiba!</size>",
  ui_story_5083_50830301_63_dialog_content = "Masuklah. Tolong beri tahu saya jika Anda memiliki kabar baik untuk kami.",
  ui_story_5083_50830301_64_dialog_content = "Ya, Pak! Serangan mendadak dari Commander Pango sangat sukses, dan tiga undercities telah diselamatkan! Mereka sedang dalam perjalanan ke posisi ini saat kita berbicara!",
  ui_story_5083_50830301_65_dialog_content = "Perintahmu adalah bertahan sampai mereka tiba!",
  ui_story_5083_50830301_66_dialog_content = "Kukira kamu bilang itu kabar baik? Sudahkah kamu lihat keadaan kita sekarang ini?!",
  ui_story_5083_50830301_67_dialog_content = "Maaf, Pak... Komandan Pango tahu betapa beratnya, tetapi tiga kota bawah tanah tidak akan terselamatkan jika bukan karena keberanian dan pengorbanan prajurit Anda.",
  ui_story_5083_50830301_68_dialog_content = "Jadi, tolong percayalah padanya. Bantuan akan segera datang, Tuan.",
  ui_story_5083_50830301_69_dialog_content = "Eclipsite sedang bergerak, Letnan Barton. Apa perintah Anda?",
  ui_story_5083_50830301_70_dialog_content = "Jika kita mundur ke Undercity sebelum evakuasi selesai, tidak ada jaminan bahwa Eclipsite tidak akan hanya mengelilingi kita...",
  ui_story_5083_50830301_71_dialog_content = "Tapi posisi ini sudah hancur... Tidak akan mudah untuk mencegahnya dari serbuan—",
  ui_story_5083_50830301_72_dialog_content = "Jadi kita menerjang masuk.",
  ui_story_5083_50830301_73_dialog_content = "I'm sorry?",
  ui_story_5083_50830301_74_dialog_content = "Sebagai perwira yang memimpin, aku memerintahkan semua prajurit untuk bersiap menyerbu musuh!",
  ui_story_5083_50830301_75_dialog_content = "Kita tidak bisa membiarkan monster-monster itu lolos dengan ini!",
  ui_story_5083_50830301_76_dialog_content = "Pikirkan tentang orang-orang yang mengandalkan kita! Pikirkan tentang orang tua kalian di Kota Gannon... Apakah kalian bersedia menyerah dan mati seperti pengecut di tempat ini?",
  ui_story_5083_50830301_77_dialog_content = "T-Tenanglah, Letnan! Perintah Komandan Pango adalah untuk bertahan di posisi ini!",
  ui_story_5083_50830301_78_dialog_content = "Bagaimana kamu bisa mengatakan itu? Kita telah bertarung tanpa henti selama sepuluh hari berturut-turut. Apakah kamu serius menyarankan kita untuk bersembunyi di sini dan menunggu yang tak terhindarkan?",
  ui_story_5083_50830301_79_dialog_content = "Tidakkah kamu bisa mencium rasa takut dalam hati mereka? Karena aku bisa, dan aku menolak untuk membiarkan mereka mati di sini!",
  ui_story_5083_50830301_80_dialog_content = "Prajurit dari 2nd Legion tidak pernah mundur dan tidak pernah menyerah!",
  ui_story_5083_50830301_81_dialog_content = "Jika kita semua akan mati, setidaknya kita akan pergi dalam kemegahan!",
  ui_story_5083_50830301_82_dialog_content = "Barton... Kamu...",
  ui_story_5083_50830301_83_dialog_content = "Kami menyerang langsung ke musuh, dan kami tidak akan berhenti sampai kami memaksa mereka untuk mundur!",
  ui_story_5083_50830301_84_dialog_content = "<size=45>Semua pasukan, ambil senjatamu dan kuatkan tekadmu—</size>",
  ui_story_5083_50830301_85_dialog_content = "<size=45>SERAANG!!!</size>",
  ui_story_5083_50830302_1_dialog_content = "<color=#e8d9bb>Seruan Barton bergema di kegelapan sebelum fajar. Saat api mengancam untuk melahap Undercity, pertarungan brutal terjadi.</color>",
  ui_story_5083_50830302_2_dialog_content = "Terus tembak! Jangan kendur!",
  ui_story_5083_50830302_3_dialog_content = "Kami menangkap mereka tanpa kesiapan! Sekarang kesempatan kita—",
  ui_story_5083_50830302_4_dialog_content = "Groar!",
  ui_story_5083_50830302_5_dialog_content = "Jangan berhenti! Tujuan kita adalah merebut kembali tanah tinggi dan memberi kesempatan kepada pasukan kita untuk mengangkut artileri berat kita ke sana!",
  ui_story_5083_50830302_6_dialog_content = "<color=#e8d9bb>Terompet terus memberi sinyal kemajuan mereka, dan prajurit berani dari Illumina semakin menekan ke dalam barisan musuh.</color>",
  ui_story_5083_50830302_7_dialog_content = "Graaaaaah!",
  ui_story_5083_50830302_8_dialog_content = "Terus berlanjut!",
  ui_story_5083_50830302_9_dialog_content = "<color=#e8d9bb>Kapanpun prajurit yang memegang trompet jatuh, yang lainnya cepat mengambil tempat mereka.</color>",
  ui_story_5083_50830302_10_dialog_content = "Di mana para penembak? Jangan tertinggal dulu!",
  ui_story_5083_50830302_11_dialog_content = "<color=#e8d9bb>Di medan perang yang seperti penggilingan daging ini, wajah Barton sudah tertutup oleh darah dan keringat. Meski begitu, dia masih memimpin serangan dengan bendera Illumina yang dikibarkan tinggi-tinggi.</color>",
  ui_story_5083_50830302_12_dialog_content = "Aku akan melindungimu, sekarang pergi!",
  ui_story_5083_50830302_13_dialog_content = "<color=#e8d9bb>Dengan bendera di satu tangan dan senjata temannya di tangan lainnya, dia membuka api pada Eclipsite saat mereka meluncur turun lereng—</color>",
  ui_story_5083_50830302_14_dialog_content = "Kamu tidak akan mengambil ini dariku!!!",
  ui_story_5083_50830302_15_dialog_content = "<color=#e8d9bb>Dengan satu dorongan kuat, Barton menusuk Eclipsite dengan benderanya dan menancapkannya dengan kuat di puncak bukit. Segera, cahaya Illumina bersinar ke mata setiap prajurit yang hadir—</color>",
  ui_story_5083_50830302_16_dialog_content = "Datang dan tangkap aku, kamu monster kotor!",
  ui_story_5083_50830302_17_dialog_content = "Barton—!",
  ui_story_5083_50830302_18_dialog_content = "Suara itu... Dogg?!",
  ui_story_5083_50830302_19_dialog_content = "<color=#e8d9bb>Saat fajar menyingsing, Barton akhirnya melihat medan perang melalui penglihatannya yang penuh darah. Di kejauhan, tampak satu batalyon tentara.</color>",
  ui_story_5083_50830302_20_dialog_content = "Goblog sia... Aku tidak percaya kau malah berlari langsung ke perut binatang buas!",
  ui_story_5083_50830302_21_dialog_content = "Tebak tidak ada jalan kembali sekarang... Semua pasukan, bersiap untuk menyerang musuh!",
  ui_story_5083_50830302_22_dialog_content = "Lindungi tanah tinggi dengan segala cara, agar Letnan Barton dapat terus memberikan tembakan penekan!",
  ui_story_5083_50830302_23_dialog_content = "Siap, Pak!",
  ui_story_5083_50830302_24_dialog_content = "Hahaha! Cadangan saya akhirnya di sini, Eclipsite—sekarang mati!",
  ui_story_5083_50830302_25_dialog_content = "<color=#e8d9bb>Trompet memberi sinyal serangan demi serangan berdarah. Para prajurit berani dari Illumina melanjutkan serangan tanpa henti mereka, dan segera, gelombang kegelapan surut di bawah cahaya fajar.</color>",
  ui_story_5083_50830302_26_dialog_content = "<color=#e8d9bb>Saat matahari bersinar di medan perang, tubuh-tubuh prajurit yang tak terhitung jumlahnya terlihat membentuk barikade di sekitar Undercity. Bahkan dalam kematian, mereka terus mempertahankan rumah mereka.</color>",
  ui_story_5083_50830302_27_dialog_content = "Hei Barton... Kau masih hidup?",
  ui_story_5083_50830302_28_dialog_content = "Urgh... Aku pikir begitu... Tidak bisa melihat dengan semua darah ini di wajahku, tapi sepertinya aku tidak kehilangan bagian penting apa pun.",
  ui_story_5083_50830302_29_dialog_content = "Bodoh kau...",
  ui_story_5083_50830302_30_dialog_content = "Kamu hampir mati di tempat ini, tahu itu? Sungguh mimpi buruk...",
  ui_story_5083_50830302_31_dialog_content = "Sst! Dengar itu?",
  ui_story_5083_50830302_32_dialog_content = "<color=#e8d9bb>Saat matahari semakin terang, sebuah klakson kuat berbunyi tanpa henti—</color>",
  ui_story_5083_50830302_33_dialog_content = "Ini adalah kekuatan utama kita... Pria tua akhirnya tiba di sini...",
  ui_story_5083_50830302_34_dialog_content = "Mereka serius... Muncul ketika mereka bilang mereka akan datang... Sial...",
  ui_story_5083_50830302_35_dialog_content = "Dogg! Barton!",
  ui_story_5083_50830302_36_dialog_content = "... Di mana di dunia ini kedua orang bodoh itu?!",
  ui_story_5083_50830302_37_dialog_content = "<color=#e8d9bb>Setelah melihat tumpukan mayat yang berserakan di medan perang, komandan berdarah besi dari 2nd Legion berbisik dengan nada gemetar.</color>",
  ui_story_5083_50830302_38_dialog_content = "Semua anak-anak itu... Tidak...",
  ui_story_5083_50830302_39_dialog_content = "Dogg! Barton! Kamu... Kamu orang-orang bodoh!!! Jangan bilang padaku...",
  ui_story_5083_50830302_40_dialog_content = "Kamu...",
  ui_story_5083_50830302_41_dialog_content = "Kalian idiot masih hidup!",
  ui_story_5083_50830302_42_dialog_content = "Komandan... Misi kita... sudah selesai, pak.",
  ui_story_5083_50830302_43_dialog_content = "Maaf pria tua... Kami tidak menyerahkan bagian mana pun dari Undercity... tapi... beberapa hal mungkin telah rusak selama pertempuran...",
  ui_story_5083_50830302_44_dialog_content = "Benar... Dengan memukul mundur Eclipsite, kamu telah melindungi Undercity ini dan mencegah dua lainnya dari invasi... Kamu menang, anak-anak.",
  ui_story_5083_50830302_45_dialog_content = "Barton... ini adalah kali pertama Anda memimpin pasukan dan rasio korban sudah hampir satu banding sepuluh?!",
  ui_story_5083_50830302_46_dialog_content = "<size=45>Berani-beraninya kau!!!</size> Seharusnya aku menyerahkanmu ke pengadilan militer karena melanggar perintah dan bermain jadi pahlawan!!!",
  ui_story_5083_50830302_47_dialog_content = "Membunuh diri sendiri adalah satu hal, tapi kamu hampir saja membunuh Dogg juga!",
  ui_story_5083_50830302_48_dialog_content = "Tapi, kita masih hidup, 'kan?",
  ui_story_5083_50830302_49_dialog_content = "Ini semua tidak akan terjadi jika saja kamu mendengarkan aku!",
  ui_story_5083_50830302_50_dialog_content = "Aku akan mencatat insiden ini dalam laporan dan menganggap kali pertama kamu memimpin sebagai kegagalan total!",
  ui_story_5083_50830302_51_dialog_content = "Apa?! Tapi kamu memberi kami misi yang mustahil! Jika kami tidak memulai pertarungan dengan Eclipsites, kami sudah lama akan dikuasai!",
  ui_story_5083_50830302_52_dialog_content = "Hei! Kembali ke sini, pria tua yang busuk! Aku menuntut penjelasan yang lebih baik dari itu!!",
  ui_story_5083_50830302_53_dialog_content = "Sial... Dia tidak melihat betapa buruknya di sini, dan dia masih saja menggangguku... Kita hampir terjebak di lubang neraka ini!",
  ui_story_5083_50830302_54_dialog_content = "Beristirahatlah, Barton. Komandan hanya khawatir tentangmu.",
  ui_story_5083_50830302_55_dialog_content = "Dia hanya mengomelimu karena kamu hampir mati, itu saja.",
  ui_story_5083_50830302_56_dialog_content = "Begitu dia menyadari komunikasi kami terputus, dia mengirim saya dan tim saya lebih dulu untuk memberikan bala bantuan.",
  ui_story_5083_50830302_57_dialog_content = "...",
  ui_story_5083_50830302_58_dialog_content = "Sekarang bangun. Saatnya kita kembali...",
  ui_story_5083_50830302_59_dialog_content = "Kita menang? Kita menang! Aku benar-benar selamat...",
  ui_story_5083_50830302_60_dialog_content = "Tapi pemimpin peleton dan yang lainnya...",
  ui_story_5083_50830302_61_dialog_content = "Hampir semua dari mereka gugur dalam pertempuran...",
  ui_story_5083_50830302_62_dialog_content = "Seluruh batalion prajurit... serta bala bantuan...",
  ui_story_5083_50830302_63_dialog_content = "... Ketika aku bangun tadi, aku menyadari bahwa komandan telah mencari mayat kita sepanjang waktu... Apakah itulah sebabnya suaranya gemetar tadi?",
  ui_story_5083_50830302_64_dialog_content = "Apakah aku membuat panggilan yang salah, Dogg?",
  ui_story_5083_50830302_65_dialog_content = "Tidak ada gunanya khawatir tentang itu sekarang.",
  ui_story_5083_50830302_66_dialog_content = "Ada lebih banyak Eclipsite daripada yang dilaporkan oleh mata-mata kita sebelumnya.",
  ui_story_5083_50830302_67_dialog_content = "Terlepas dari apa yang terjadi, kamu berhasil menyelesaikan misi.",
  ui_story_5083_50830302_68_dialog_content = "Bukan hanya mempertahankan Undercity ini, kamu juga telah membunuh sejumlah besar Eclipsite.",
  ui_story_5083_50830302_69_dialog_content = "... Para pria dan wanita berani yang bertarung di sampingmu mati dengan terhormat dan tanpa penyesalan. Saya yakin akan hal itu.",
  ui_story_5083_50830302_70_dialog_content = "Jika... Jika saya tidak memberikan perintah untuk menyerang...",
  ui_story_5083_50830302_71_dialog_content = "Apakah jumlah mereka yang berdiri sekarang bertambah?",
  ui_story_5083_50830302_72_dialog_content = "Jangan dipikirkan.",
  ui_story_5083_50830302_73_dialog_content = "Ini adalah perang, Barton. Tidak seperti simulasi militer kita, tidak ada yang dijamin di sini.",
  ui_story_5083_50830302_74_dialog_content = "Bahkan komandan terhebat sekalipun tidak memiliki cara untuk mengetahui apakah pertempuran akan berjalan sesuai dengan perintah mereka.",
  ui_story_5083_50830302_75_dialog_content = "Peta dan model tidak pernah bisa mencerminkan setiap bagian dari pertempuran, atau semangat yang tak kenal takut dari tentara Illumina.",
  ui_story_5083_50830302_76_dialog_content = "Serangan balikmu berhasil, dan kamu keluar sebagai pemenang. Itulah hasil dari pertama kalinya kamu memimpin.",
  ui_story_5083_50830302_77_dialog_content = "Berhasil, huh...",
  ui_story_5083_50830302_78_dialog_content = "Mengenai di mana harus ditingkatkan dan bagaimana menyelamatkan lebih banyak nyawa di lain waktu... Itu adalah hal yang harus kamu pikirkan saat kita terus bergerak maju.",
  ui_story_5083_50830302_79_dialog_content = "Mungkin kamu akan membuat keputusan berbeda lain kali. Bagaimanapun juga, hasil dari pertempuran ini sudah ditentukan.",
  ui_story_5083_50830302_80_dialog_content = "Dan sebagai orang yang selamat, kita harus menanggung segalanya. Bukan hanya yang baik, tetapi juga yang buruk.",
  ui_story_5083_50830302_81_dialog_content = "Menerima hasil dari pertempuran, dan berbagi kemenangan kita dengan yang lain...",
  ui_story_5083_50830302_82_dialog_content = "Itu saja yang bisa kita lakukan sebagai komandan saat ini.",
  ui_story_5083_50830400_1_dialog_content = "Beep—Kamu memiliki pesan baru, Barton.",
  ui_story_5083_50830400_2_dialog_content = "Pesan berikut ini adalah dari Komandan Pango dari 2nd Legion, dan ini tidak mencerminkan pandangan pribadi saya—",
  ui_story_5083_50830400_3_dialog_content = "Hei, punk! Kamu masih malas-malasan di tempat tidur, bukan?!",
  ui_story_5083_50830400_4_dialog_content = "Hanya karena bukan hari latihan bukan berarti kamu bisa santai saja!",
  ui_story_5083_50830400_5_dialog_content = "Bawa pantat menyesalmu ke sektor perumahan! Saya punya pekerjaan khusus untukmu!",
  ui_story_5083_50830400_6_dialog_content = "Dan tugas itu adalah, uh... Ahem, memastikan tidak ada yang menjual perbekalan secara diam-diam di luar sana.",
  ui_story_5083_50830400_7_dialog_content = "Anda memiliki satu hari untuk menyelesaikan misi! Tidak masalah apakah Anda berhasil atau tidak, asalkan Anda menghabiskan seluruh hari di sektor perumahan! Dan jangan berpikir untuk kembali lebih awal, mengerti?! Diberhentikan!",
  ui_story_5083_50830400_8_dialog_content = "Manis!",
  ui_story_5083_50830400_9_dialog_content = "Bip—Kenapa kamu begitu bahagia? Komandan tadi berteriak pada kamu.",
  ui_story_5083_50830400_10_dialog_content = "Ha, kamu tidak tahu itu, bukan? Kita sering lewat lantai atas sektor permukiman, tapi itu dilarang untuk nongkrong.",
  ui_story_5083_50830400_11_dialog_content = "Mereka selalu mendirikan gedung baru di sana, jadi saya selalu ingin memeriksanya sendiri!",
  ui_story_5083_50830400_12_dialog_content = "Bip—Tolong berhenti mengguncang saya...",
  ui_story_5083_50830400_13_dialog_content = "<size=45>Wuu-huu! Waktunya bersenang-senang!!!</size>",
  ui_story_5083_50830400_14_dialog_content = "Kamu terlihat cukup rapi, Barton. Saya dengar kamu akan pergi ke sektor perumahan hari ini?",
  ui_story_5083_50830400_15_dialog_content = "Benar sekali! Ada yang butuh apa-apa dari pusat distribusi? Saya akan ke sana, jadi cukup berikan saya vouchernya, dan saya akan mengambil barang-barang Anda.",
  ui_story_5083_50830400_16_dialog_content = "H-Hey! Satu per satu, atau voucher akan menjadi berantakan. Lagipula, aku hanya bisa membawa sebanyak ini!",
  ui_story_5083_50830400_17_dialog_content = "Komandan mengatakan dia memberimu misi, tapi sepertinya dia hanya ingin memberimu hari libur.",
  ui_story_5083_50830400_18_dialog_content = "Begitu ya? Kurasa kemampuan berkomunikasinya tidak jauh lebih baik dari kamu, ya?",
  ui_story_5083_50830400_19_dialog_content = "... Cukup pergi saja, bodoh kau!",
  ui_story_5083_50830400_20_dialog_content = "Lihatlah! Ini adalah area alokasi baru yang mereka letakkan tepat di sebelah sektor perumahan!",
  ui_story_5083_50830400_21_dialog_content = "Bip—Harus ada kata yang lebih baik daripada plopped, Barton...",
  ui_story_5083_50830400_22_dialog_content = "Saya tidak tahu apa yang kamu bicarakan. Sekarang tunjukkan aku ke tempat terdekat untuk bersenang-senang; Saya masih punya banyak belanjaan!",
  ui_story_5083_50830400_23_dialog_content = "... Bagaimana dengan misimu?",
  ui_story_5083_50830400_24_dialog_content = "Ah, jangan khawatir tentang itu. Bahkan Dogg berpikir saya di sini untuk istirahat, jadi mari kita percaya padanya.",
  ui_story_5083_50830400_25_dialog_content = "Komandan Pango praktis membesarkannya. Saya tidak pikir ada orang lain yang lebih mengenal pria tua itu daripada dia.",
  ui_story_5083_50830400_26_dialog_content = "Sekarang mari kita bersenang-senang! Tunjukkan jalannya!",
  ui_story_5083_50830400_27_dialog_content = "Beep—Ya, Barton... Saya menemukan tempat yang dikenal sebagai Hidden Arcade 60 meter dari sini, di gang ke kanan kita.",
  ui_story_5083_50830400_28_dialog_content = "Sebuah arcade, huh... Apakah mereka benar-benar memiliki hal semacam itu di area alokasi? Kita masih berperang, setelah semua... Mari kita lihat.",
  ui_story_5083_50830400_29_dialog_content = "S-Serius?! Ini pasti video game yang pernah aku dengar di akademi—",
  ui_story_5083_50830400_30_dialog_content = "Selamat datang di Arcade Tersembunyi. Meskipun kita masih dalam perang, saya sangat berharap bahwa Anda akan menemukan sedikit kedamaian dan kesenangan di sini.",
  ui_story_5083_50830400_31_dialog_content = "Semua game kami dirancang dan dikembangkan oleh bos arcade. Pelanggan baru berhak mendapatkan satu putaran bermain gratis!",
  ui_story_5083_50830400_32_dialog_content = "Jika kamu mencapai skor tinggi di Naval King, kamu bisa memilih hadiah yang sesuai dengan skor kamu!",
  ui_story_5083_50830400_33_dialog_content = "Jika Anda gagal dalam upaya Anda, cukup tukarkan voucher Anda dengan token dan terus bermain untuk skor yang lebih tinggi!",
  ui_story_5083_50830400_34_dialog_content = "Bosmu terdengar seperti pemenang sejati bagi saya! Perhatikan ini, saya akan mengalahkan seluruh level dalam satu kali pergi!",
  ui_story_5083_50830400_35_dialog_content = "Permainan Selesai! Skor: 5.",
  ui_story_5083_50830400_36_dialog_content = "Maaf pak, tetapi Anda membutuhkan skor 500 untuk kaos Naval King atau skor 1.000 untuk permainan itu sendiri. Apakah Anda ingin menukar voucher Anda dengan beberapa token?",
  ui_story_5083_50830400_37_dialog_content = "Benar sekali aku lakukan! Ini dia.",
  ui_story_5083_50830400_38_dialog_content = "Sekarang perhatikan ini—!",
  ui_story_5083_50830400_39_dialog_content = "Permainan Selesai! Skor: 40.",
  ui_story_5083_50830400_40_dialog_content = "Hei, berapa banyak voucher yang dibutuhkan untuk membeli kaos Naval King itu?",
  ui_story_5083_50830400_41_dialog_content = "Heheh... Karena kamu sudah cukup menghabiskan untuk mendapatkan status VIP, sekarang kamu memiliki hak istimewa untuk membelinya dengan voucher 100 poin. Apakah kamu ingin membelinya?",
  ui_story_5083_50830400_42_dialog_content = "Wow Barton, aku tidak menyangka kamu akan sangat menyukai kemeja itu.",
  ui_story_5083_50830400_43_dialog_content = "Se-Sedang apa kamu di sini?!",
  ui_story_5083_50830400_44_dialog_content = "Kebetulan saya adalah pengembang di balik semua game ini! Yah, saya dan Denier.",
  ui_story_5083_50830400_45_dialog_content = "Hampir tidak. Kamu yang melakukan semua pekerjaan karena saya tidak benar-benar peduli tentang hal ini.",
  ui_story_5083_50830400_46_dialog_content = "Ngomong-ngomong, Denier itu juniorku!",
  ui_story_5083_50830400_47_dialog_content = "Saya telah mendengar tentang kamu, Barton... Bukan skor yang buruk yang kamu dapatkan di sana.",
  ui_story_5083_50830400_48_dialog_content = "Uh, hai... Dengar Gronru, mesin game-mu telah menghabiskan banyak voucherku.",
  ui_story_5083_50830400_49_dialog_content = "Seharusnya saya menggunakan sebagian dari mereka untuk membeli barang untuk rekan satu tim saya, jadi bisakah Anda...",
  ui_story_5083_50830400_50_dialog_content = "Hahaha, aku tidak menyangka kamu akan begitu buruk dalam video game! Meski begitu, aku berterima kasih karena kamu sangat menikmatinya.",
  ui_story_5083_50830400_51_dialog_content = "Sekarang saya tahu itu akan menjadi hit besar bagi semua orang!",
  ui_story_5083_50830400_52_dialog_content = "Sepertinya mengujinya di sini adalah langkah yang tepat. Saya bahkan mendapatkan kembali sebagian uang yang saya investasikan dalam game-game ini!",
  ui_story_5083_50830400_53_dialog_content = "... Tunggu, jadi kamu menjalankan bisnis pribadi untuk mencari untung di sini?",
  ui_story_5083_50830400_54_dialog_content = "Maksud saya, kami memang menawarkan percobaan gratis... Jadi itu seharusnya tidak menjadi masalah, kan?",
  ui_story_5083_50830400_55_dialog_content = "Huh, ini masalah besar, Gronru. Ketika kamu ditangkap, coba jangan tarik aku turun bersamamu.",
  ui_story_5083_50830400_56_dialog_content = "Seolah-olah! Aku akan memberi tahu mereka bahwa kamu telah membantu saya membangun semua mesin game ini!",
  ui_story_5083_50830400_57_dialog_content = "Apa?! S-Saya hanya membantu karena Anda memerintahkan saya untuk melakukannya, Tech Officer!",
  ui_story_5083_50830400_58_dialog_content = "Ya, tapi kamu menikmatinya, bukan?",
  ui_story_5083_50830400_59_dialog_content = "Sejauh menyangkut penelitian... Saya rasa itu cukup menyenangkan.",
  ui_story_5083_50830400_60_dialog_content = "Lihat? Dan aku bisa katakan bahwa kamu juga tertarik dengan permainan ini, Barton. Pikir kamu bisa melepaskan aku kali ini?",
  ui_story_5083_50830400_61_dialog_content = "Yah, saya menikmati memainkan gawai baru sebanyak orang lain. Bagaimana kalau begini, berikan saya kembali voucher itu, dan saya akan pura-pura ini tidak pernah terjadi.",
  ui_story_5083_50830400_62_dialog_content = "Oh, jangan seperti itu! Apa salahnya sedikit menghargai usaha kita?",
  ui_story_5083_50830400_63_dialog_content = "Setelah semua, setiap potongan teknologi baru yang aku kembangkan dirancang untuk membantu prajurit garis depan seperti kamu.",
  ui_story_5083_50830400_64_dialog_content = "Bantu, hah... Tunggu, itu mengingatkan saya! Apakah kamu mengenali drone ini?",
  ui_story_5083_50830400_65_dialog_content = "Hah? Kemana perginya?",
  ui_story_5083_50830400_66_dialog_content = "Drone apa?",
  ui_story_5083_50830400_67_dialog_content = "Ini drone tua yang datang padaku lebih awal hari ini. Dia menyebut dirinya Navigatorku!",
  ui_story_5083_50830400_68_dialog_content = "Aku telah mengikuti dan mengobrol dengannya sepanjang hari.",
  ui_story_5083_50830400_69_dialog_content = "Wow, itu terdengar cukup berteknologi tinggi, 'kan, Denier?",
  ui_story_5083_50830400_70_dialog_content = "Setuju. Saya tidak berpikir Illumina memiliki teknologi cerdas seperti itu, dan bagi kamu untuk mengatakan itu \"tampak tua\" bahkan semakin tidak masuk akal...",
  ui_story_5083_50830400_71_dialog_content = "Benarkah? Karena saya pikir kamu yang membuatnya. Bertanya-tanya kemana si kecil pergi... Yah, saya yakin dia tidak bisa tersesat karena dia adalah drone navigasi dan semuanya.",
  ui_story_5083_50830400_72_dialog_content = "Lain kali saya mendapat kesempatan, akan saya tunjukkan padamu.",
  ui_story_5083_50830400_73_dialog_content = "Saya juga ingin melihatnya... Apapun yang mengarah ke masa depan yang lebih kuat selalu menarik bagi saya.",
  ui_story_5083_50830400_74_dialog_content = "Berikut adalah voucher Anda, Barton. Jangan lupa untuk menjaga tempat ini sebagai rahasia kecil kita, oke?",
  ui_story_5083_50830400_75_dialog_content = "Baiklah, dan terima kasih! Saya jarang mendapat kesempatan untuk melihat bagian kota ini, jadi saya belum siap untuk kembali. Bagaimana kalau saya mentraktir kalian berdua makan enak?",
  ui_story_5083_50830400_76_dialog_content = "Hitung saya masuk! Saya tahu kamu orang baik, Barton!",
  ui_story_5083_50830400_77_dialog_content = "Aku juga sudah kenyang dengan makanan lab, jadi terima kasih... Dan jika benar-benar enak, aku ingin merekomendasikannya kepada saudariku.",
  ui_story_5083_50830400_78_dialog_content = "Oh ya! Hei Barton, apakah kamu tahu bahwa kakak perempuannya tidak lain adalah Reinhardt yang hebat?",
  ui_story_5083_50830400_79_dialog_content = "Jangan katakan seperti itu, Gronru. Itu memalukan.",
  ui_story_5083_50830400_80_dialog_content = "Benarkah? Saya sama sekali tidak bisa membedakan, karena saudarimu bersinar lebih terang daripada siapa pun.",
  ui_story_5083_50830400_81_dialog_content = "... Aku akan mengejarnya suatu hari nanti.",
  ui_story_5083_50830400_82_dialog_content = "Begitu? Karena menurutku kamu sudah baik-baik saja—Sekarang ayo kita makan!",
  ui_story_5083_50830400_83_dialog_content = "Itu tidak buruk sama sekali. Kurasa aku bisa merekomendasikannya kepada... Dia.",
  ui_story_5083_50830400_84_dialog_content = "Hmm... Kalian berdua memang sangat berbeda satu sama lain.",
  ui_story_5083_50830400_85_dialog_content = "Aku tahu kamu sudah melihat Reinhardt beraksi, tapi kamu belum sempat melihat Denier bersinar, Barton.",
  ui_story_5083_50830400_86_dialog_content = "Kamu suka simulasi militer, kan? Mungkin kamu berdua bisa bermain pertandingan.",
  ui_story_5083_50830400_87_dialog_content = "Saya tidak masalah dengan kompetisi lainnya, tetapi uji strategi bertarung melawan peneliti? Tentu saja, ayo lakukan!",
  ui_story_5083_50830400_88_dialog_content = "Aku tidak memintamu untuk mencari masalah untukku, Gronru... Tapi baiklah. Aku menerima tantanganmu, Letnan Barton. Tapi aku memberi peringatan: Jangan meremehkan aku jika aku adalah kamu.",
  ui_story_5083_50830400_89_dialog_content = "<color=#e8d9bb>Kelompok itu kembali ke toko tersembunyi Gronru, di mana Barton dan Denier terlibat dalam pertempuran simulasi di atas meja pasir.</color>",
  ui_story_5083_50830400_90_dialog_content = "<color=#e8d9bb>Untuk kejutan Barton, taktik Denier jauh lebih kejam dan tak kenal henti daripada apa yang dia harapkan dari seorang peneliti.</color>",
  ui_story_5083_50830400_91_dialog_content = "<color=#e8d9bb>Dengan mengorbankan pion demi pion, dia semakin mendalam masuk ke wilayah Barton, yang membuatnya terkejut. Ketika dia menyadari betapa berbahayanya situasinya, dia sudah berada di ambang kekalahan.</color>",
  ui_story_5083_50830400_92_dialog_content = "(Ini tidak baik! Aku sudah kalah dari Gronru; aku tidak bisa mampu kalah dari temannya juga!)",
  ui_story_5083_50830400_93_dialog_content = "<color=#e8d9bb>Merona karena malu, Barton tiba-tiba membanting potongan berikutnya ke posisi, merusak sisi papan Denier.</color>",
  ui_story_5083_50830400_94_dialog_content = "<color=#e8d9bb>Saat dia berusaha untuk mengatur kembali bidaknya, Barton menekan keuntungannya dan melancarkan serangkaian serangan.</color>",
  ui_story_5083_50830400_95_dialog_content = "Itu adalah gerakan yang kotor, Barton... Lihat? Denier hampir menangis...",
  ui_story_5083_50830400_96_dialog_content = "Moral tidak berarti apa-apa di medan perang; yang penting adalah menang dan kalah! Komandan saya mengajari saya untuk menang berapa pun biayanya, dan itu persis yang akan saya lakukan!",
  ui_story_5083_50830400_97_dialog_content = "<color=#e8d9bb>Meskipun kata-katanya keras, jarak sudah terlalu sulit untuk dijembatani. Setelah menaruh kembali potongan-potongannya di papan pasir, Denier dengan gemetar mengembalikan ketenangannya.</color>",
  ui_story_5083_50830400_98_dialog_content = "<color=#e8d9bb>Mengumpan, mengapit, dan menghancurkan lawannya dengan terus menerus mengorbankan bidaknya... Itulah bagaimana Denier keluar sebagai pemenang dalam pertempuran mereka.</color>",
  ui_story_5083_50830400_99_dialog_content = "Hahahaha! Sepertinya dia telah mengalahkanmu dalam strategi dan sopan santun, Barton!",
  ui_story_5083_50830400_100_dialog_content = "Kamu menyebut dirimu letnan dengan taktik-taktik licik itu? Tunggu saja sampai aku ceritakan...",
  ui_story_5083_50830400_101_dialog_content = "Er... T-Tunggu sebentar, kalian berdua! Kalian tidak boleh memberitahu orang lain tentang apa yang terjadi di sini hari ini! Tolong!",
  ui_story_5083_50830400_102_dialog_content = "Jika kabar ini tersebar, aku tidak akan pernah bisa melupakannya! <size=45>Tolong! Aku akan melakukan apapun!!!</size>",
  ui_story_5083_50830500_1_dialog_content = "<color=#e8d9bb>Seorang Barton yang tampak murung muncul kembali di gerbang kamp membawa beberapa tas berbagai ukuran. Saya harus pergi memberi tahu dia—</color>",
  ui_story_5083_50830500_2_dialog_content = "Kamu pergi kemana? Kamu menghilang setengah hari, tahu...",
  ui_story_5083_50830500_3_dialog_content = "Bip—Bahaya, Barton—",
  ui_story_5083_50830500_4_dialog_content = "Bahaya apa? Kami di kamp... Hah?",
  ui_story_5083_50830500_5_dialog_content = "<color=#e8d9bb>Reinhardt berdiri di tengah lapangan latihan 2nd Legion, sebuah tombak di tangan. Dia tampaknya telah menunggu untuk waktu yang lama.</color>",
  ui_story_5083_50830500_6_dialog_content = "Dia tampak seperti siap untuk membunuh seseorang. Bertanya-tanya siapa yang membuatnya marah?",
  ui_story_5083_50830500_7_dialog_content = "...",
  ui_story_5083_50830500_8_dialog_content = "<size=45>Barton—!</size>",
  ui_story_5083_50830500_9_dialog_content = "Berani-beraninya kau menggunakan trik murahan terhadap kakakku! Aku akan memberimu pelajaran yang tidak akan pernah kau lupakan!!",
  ui_story_5083_50830500_10_dialog_content = "Apa dia, anak kecil? Bagaimana dia bisa memberitahu kakaknya tentangku?!",
  ui_story_5083_50830500_11_dialog_content = "Bip—Saran tindakan: LARI!",
  ui_story_5083_50830500_12_dialog_content = "Ini barangmu, setiap orang! Maaf, tapi aku harus pergi—",
  ui_story_5083_50830500_13_dialog_content = "Kembali kesini, pengecut!!!",
  ui_story_5083_50830500_14_dialog_content = "<color=#e8d9bb>Reinhardt tanpa ampun mengejar Barton, tombaknya yang menyala terus membelah kegelapan malam.</color>",
  ui_story_5083_50830500_15_dialog_content = "Hei, berhenti sudah! Aku akan melawan jika ini terus berlanjut.",
  ui_story_5083_50830500_16_dialog_content = "Kira-kira kamu bisa menggertakku seperti kamu menggertak kakakku? Ayo coba saja!",
  ui_story_5083_50830500_17_dialog_content = "Berhenti mengayunkan benda itu saat kamu berbicara! Itu berbahaya!",
  ui_story_5083_50830500_18_dialog_content = "<color=#e8d9bb>Barton terus berusaha melarikan diri dari Reinhardt, yang menolak untuk membiarkannya pergi. Tak lama kemudian, keduanya berlari sepanjang tiga jalan yang panjang—</color>",
  ui_story_5083_50830500_19_dialog_content = "Baiklah, itu cukup! Ambil ini!",
  ui_story_5083_50830500_20_dialog_content = "Pasir? Sungguh? Kau menjijikkan.",
  ui_story_5083_50830500_21_dialog_content = "Apa pun yang diperlukan untuk menang! Sekarang ambil ini!",
  ui_story_5083_50830500_22_dialog_content = "<color=#FFB400>Star-Piercing Spear</color>!",
  ui_story_5083_50830500_23_dialog_content = "<color=#e8d9bb>Kedua orang itu bertarung bolak-balik di seberang jalan, menyebabkan kepanikan yang tidak kecil. Prajurit bergegas ke tempat kejadian, tetapi tidak yakin bagaimana cara menghentikan pertarungan liar itu.</color>",
  ui_story_5083_50830500_24_dialog_content = "Semoga kamu siap untuk gaya pipa airku!",
  ui_story_5083_50830500_25_dialog_content = "Rasakan ini!",
  ui_story_5083_50830500_26_dialog_content = "Haha, lumayan juga! Teruskan!",
  ui_story_5083_50830500_27_dialog_content = "<size=45>Hentikan, kalian bunglon!</size>",
  ui_story_5083_50830500_28_dialog_content = "Berkelahi satu sama lain seperti sekumpulan anak-anak... Jika kalian merasa gelisah, kembali saja ke lapangan latihan dan berikan aku seratus putaran masing-masing!!!",
  ui_story_5083_50830500_29_dialog_content = "Ugh, ini semua salahmu. Sekarang aku juga harus berlari seratus putaran.",
  ui_story_5083_50830500_30_dialog_content = "Kau pikir kau tidak pantas mendapatkan itu setelah menindas adik seperguruanmu?",
  ui_story_5083_50830500_31_dialog_content = "Kamu bicara seolah-olah saudarimu tidak menggunakan taktik yang paling tidak manusiawi untuk mengalahkanku... Aku tidak yakin dia membutuhkanmu untuk membela dia seperti ini sama sekali.",
  ui_story_5083_50830500_32_dialog_content = "Berhenti berdebat dan percepat langkahmu, kalian idiot!",
  ui_story_5083_50830500_33_dialog_content = "Jangan ragu untuk bertarung lagi setelah kamu menyelesaikan seratus putaran lari, asumsikan kamu masih bisa berdiri setelahnya!",
  ui_story_5083_50830500_34_dialog_content = "Huft, huft...",
  ui_story_5083_50830500_35_dialog_content = "Whoa, kamu tidak serius, kan? Heh... Sekarang aku benar-benar bersemangat! Ayo pergi!",
  ui_story_5083_50830500_36_dialog_content = "Cobalah untuk mengimbangi! Aku masih akan memukulmu meski kau tak bisa berdiri!",
  ui_story_5083_50830500_37_dialog_content = "<color=#e8d9bb>Dua prajurit muda itu berlari mengelilingi lintasan dengan segenap kekuatan mereka. Seiring bertambahnya jumlah putaran mereka, langkah mereka juga semakin lelah.</color>",
  ui_story_5083_50830500_38_dialog_content = "Aku terkejut kau bisa mengejarku... Tapi aku belum selesai!",
  ui_story_5083_50830500_39_dialog_content = "<color=#e8d9bb>Enam puluh putaran, tujuh puluh putaran... Langkah kaki mereka menjadi lambat dan tidak teratur, seolah-olah kaki mereka penuh dengan timah.</color>",
  ui_story_5083_50830500_40_dialog_content = "Hukuman ini mungkin sedikit berlebihan, Komandan Pango...",
  ui_story_5083_50830500_41_dialog_content = "Apakah saya meminta pendapatmu? Orang-orang masih membersihkan kekacauan yang mereka tinggalkan, tahu!",
  ui_story_5083_50830500_42_dialog_content = "Karena begundal congkak itu sangat suka berkelahi, aku pikir aku akan membuat mereka menderita sedikit lebih banyak hari ini.",
  ui_story_5083_50830500_43_dialog_content = "<color=#e8d9bb>Delapan puluh lap, sembilan puluh lap... Kedua mereka mulai goyah dari sisi ke sisi, tetapi mereka terus saling mendorong hingga akhir.</color>",
  ui_story_5083_50830500_44_dialog_content = "Hei... Masih ada semangat bertarung dalam dirimu?",
  ui_story_5083_50830500_45_dialog_content = "Haruskah kamu... bertanya? Yang bisa aku pikirkan... adalah bagaimana aku akan menangani tombakmu itu.",
  ui_story_5083_50830500_46_dialog_content = "<color=#e8d9bb>Sembilan puluh sembilan, seratus—Peluit komandan menandakan akhir dari hukuman mereka yang melelahkan, dan kedua orang itu segera roboh ke tanah.</color>",
  ui_story_5083_50830500_47_dialog_content = "Apakah kamu... masih hidup... di sana?",
  ui_story_5083_50830500_48_dialog_content = "Yep... masih bernapas...!",
  ui_story_5083_50830500_49_dialog_content = "Masih ingin... bertarung? Saya siap... kapanpun kamu siap...",
  ui_story_5083_50830500_50_dialog_content = "Heh... Aku tidak akan melawanmu... Jika kamu bahkan tidak bisa berdiri, tapi jangan khawatir, aku akan menerima tantangan apa pun darimu kapan saja.",
  ui_story_5083_50830500_51_dialog_content = "Oh ya...? Wah, tujuanmu mulia sekali... Hahaha—uhuk, uhuk—",
  ui_story_5083_50830500_52_dialog_content = "<color=#e8d9bb>Reinhardt tertawa terbahak-bahak, tetapi serangan batuk dengan cepat menghentikannya. Namun, dia berhasil berdiri dan mengulurkan tangannya.</color>",
  ui_story_5083_50830500_53_dialog_content = "Uhuk, anggaplah dirimu sebagai sainganku. Kau telah memperolehnya.",
  ui_story_5083_50830500_54_dialog_content = "Komandanmu membuat poin yang baik. Kita semua adalah prajurit Illumina—sedikit kompetisi itu sehat, tetapi kita tidak seharusnya bertengkar antar kita sendiri.",
  ui_story_5083_50830500_55_dialog_content = "Menurut etiket Illumina, kita harus berjabat tangan dan berbaikan.",
  ui_story_5083_50830500_56_dialog_content = "Kamu memiliki semua kualitas yang saya cari dalam seseorang, dan saya yakin saya akan membutuhkan bantuanmu di masa depan.",
  ui_story_5083_50830500_57_dialog_content = "Tak bisa dipercaya... Kau bahkan lebih sombong daripada yang kuduga, dan kau masih saja seorang rekrutan baru.",
  ui_story_5083_50830500_58_dialog_content = "Tidak ada salahnya memberitahumu, tapi aku memiliki mimpi kecil untuk menjadi Grand Marshal suatu hari nanti.",
  ui_story_5083_50830500_59_dialog_content = "Kamu menyebut itu \"mimpi kecil\"? Menarik...",
  ui_story_5083_50830500_60_dialog_content = "Baiklah, aku percaya padamu! Tidak ada yang bisa memalsukan aura yang kamu pancarkan, itu pasti.",
  ui_story_5083_50830500_61_dialog_content = "Kita seimbang untuk sekarang, tapi jangan sombong! Kita akan memiliki banyak kesempatan untuk bersaing di masa depan.",
  ui_story_5083_50830500_62_dialog_content = "Menantikannya.",
  ui_story_5083_50830500_63_dialog_content = "Tatapan matanya memberi tahu saya bahwa dia sangat serius. Cahayanya bahkan lebih terang dari komandan.",
  ui_story_5083_50830500_64_dialog_content = "Hmph, Illumina akan jauh lebih baik dengan seseorang seperti itu yang memimpin... Tidak sabar untuk melihat kemana dia akan pergi!",
  ui_story_5083_50830500_65_dialog_content = "Apa yang kamu gumamkan, Barton? Kesini!",
  ui_story_5083_50830500_66_dialog_content = "Legiun kita akhirnya kembali lengkap, jadi saatnya untuk foto grup tradisional kita.",
  ui_story_5083_50830500_67_dialog_content = "Komandan Pango bertahan karena dia ingin menunggumu. Tidak heran dia begitu marah saat melihatmu berkelahi dengan Reinhardt! Sekarang cepatlah dan datang ke sini!",
  ui_story_5083_50830500_68_dialog_content = "Foto grup... Tentu saja!",
  ui_story_5083_50830500_69_dialog_content = "Di sini, kami menyimpankan tempat untukmu tepat di samping Komandan Pango.",
  ui_story_5083_50830500_70_dialog_content = "Trims!",
  ui_story_5083_50830500_71_dialog_content = "Hmph, masih berjalan ya? Kurasa latihanku tidak sepenuhnya sia-sia pada dirimu setelah semua.",
  ui_story_5083_50830500_72_dialog_content = "Aku masih muda dan penuh semangat, tidak seperti seorang komandan tertentu—",
  ui_story_5083_50830500_73_dialog_content = "Cukup, kalian berdua... Saatnya pidato Anda, Komandan.",
  ui_story_5083_50830500_74_dialog_content = "Hmph!",
  ui_story_5083_50830500_75_dialog_content = "Hmph!",
  ui_story_5083_50830500_76_dialog_content = "... Tentara dari Legiun Kedua! Kita berkumpul di sini hari ini untuk merayakan kelulusan Anda dari boot camp! Selamat atas bertahan dalam program pelatihan pria tua ini!",
  ui_story_5083_50830500_77_dialog_content = "Saya bangga bisa mengatakan bahwa saya telah membentuk kalian semua menjadi prajurit terbaik Illumina. Tapi jangan salah paham: Eclipsite yang akan kalian hadapi di masa depan seratus kali lebih brutal!",
  ui_story_5083_50830500_78_dialog_content = "Tapi sebagai prajurit dari 2nd Legion, kita tidak akan pernah mundur atau menyerah! Sekarang, mari kita selesaikan foto ini, sehingga kamu bisa pulang dan menikmati tiga hari libur yang telah kamu perjuangkan dengan keras!",
  ui_story_5083_50830500_79_dialog_content = "Tiga sorakan untuk Komandan Pango!",
  ui_story_5083_50830500_80_dialog_content = "Jangan berterima kasih dulu! Masa depan tidak akan mudah bagi kalian semua; setelah kalian kembali dari garis depan, harapkan lebih banyak latihan dari komandan tua kalian! Itu saja!",
  ui_story_5083_50830500_81_dialog_content = "Baiklah, sekarang setiap orang tersenyum lebar—Jayalah Illumina!",
  ui_story_5083_50830500_82_dialog_content = "<size=45>Splendor Illumina!</size>",
  ui_story_5083_50830600_1_dialog_content = "Waktu liburan hampir usai, jadi jangan sampai aku melihat kamu bermalas-malasan!",
  ui_story_5083_50830600_2_dialog_content = "Pasti akan aku kerjakan keras untuk meningkatkan keahlian menembakku, Komandan!",
  ui_story_5083_50830600_3_dialog_content = "Jika kamu menembak mati Eclipsite dan jatuh di atasmu, yang di belakangnya akan langsung melompat ke atasmu. Bagaimana kamu berharap untuk tetap bisa menembak dengan jelas dalam keadaan seperti itu?",
  ui_story_5083_50830600_4_dialog_content = "Selain itu, ada Eclipsites di luar sana yang kebal terhadap senjata api. Yang perlu kamu lakukan adalah melatih kemampuan pedangmu, Barton!",
  ui_story_5083_50830600_5_dialog_content = "Senjata jarak dekat yang baik tidak akan pernah mengecewakanmu! Selama kamu ingat itu saat menghunus pedangmu, kamu tidak akan pernah merasa terjebak oleh musuh!",
  ui_story_5083_50830600_6_dialog_content = "...",
  ui_story_5083_50830600_7_dialog_content = "Seorang prajurit Illumina tidak takut mati! Setiap hari, kami bertarung dengan nyawa kami untuk membebaskan Astra dari malapetaka Eclipsite! Namun, yang kami takuti adalah mati sia-sia!",
  ui_story_5083_50830600_8_dialog_content = "Itulah mengapa tetap hidup harus menjadi prioritas utama Anda dalam pertempuran! Apakah saya sudah jelas?!",
  ui_story_5083_50830600_9_dialog_content = "Siap, Pak!",
  ui_story_5083_50830600_10_dialog_content = "Kerjakan tugasmu, prajurit! Jangan sia-siakan waktumu seperti dua hari terakhir ini!",
  ui_story_5083_50830600_11_dialog_content = "... Sebagai prajurit veteran, tidak mungkin kita terus kalah oleh rekrutan baru 1st Legion.",
  ui_story_5083_50830600_12_dialog_content = "Mengerti, Komandan!",
  ui_story_5083_50830600_13_dialog_content = "Sama seperti Dogg, Komandan Pango memiliki waktu yang sulit untuk mengungkapkan apa yang ada di pikirannya.",
  ui_story_5083_50830600_14_dialog_content = "Kamu pasti berpikir orang tua akan lebih langsung soal sesuatu... Dia pasti benar-benar ingin aku menempatkan Reinhardt di tempatnya, ya?",
  ui_story_5083_50830600_15_dialog_content = "Bip—Saya tidak yakin itu benar-benar benar, Barton.",
  ui_story_5083_50830600_16_dialog_content = "Hahaha! Kamu cukup pemalu untuk sebuah drone, tahu? Kamu selalu tampak menghilang setiap kali orang lain muncul. Pokoknya, kamu seharusnya menjadi Navigatorku, kan?",
  ui_story_5083_50830600_17_dialog_content = "... Apakah kamu memerlukan petunjuk arah?",
  ui_story_5083_50830600_18_dialog_content = "Nah, tapi ada satu tempat yang ingin kulihat hari ini. Ayo pergi.",
  ui_story_5083_50830600_19_dialog_content = "Beep—Kamu ingin menghabiskan hari libur terakhirmu di museum, Barton?",
  ui_story_5083_50830600_20_dialog_content = "Begitulah adanya dengan kami para prajurit; jika kami tidak sedang bertempur, kami sedang berlatih untuk bertempur. Lagipula, setiap tempat pada dasarnya sama saja ketika Anda tinggal di bawah tanah.",
  ui_story_5083_50830600_21_dialog_content = "...Meski begitu, akan menyenangkan memiliki salah satu mesin game Gronru di rumah untuk mengisi waktu.",
  ui_story_5083_50830600_22_dialog_content = "Jika kita tidak sedang berperang, aku merasa bisa bermain game seumur hidupku.",
  ui_story_5083_50830600_23_dialog_content = "Itu atau mendirikan tim eksplorasi untuk berlayar menyeberangi lautan.",
  ui_story_5083_50830600_24_dialog_content = "<color=#FFB400>Damai</color>... Haha! Cukup memikirkannya saja sudah cukup untukku.",
  ui_story_5083_50830600_25_dialog_content = "Beep—Mengaktifkan mode panduan Museum Illumina.",
  ui_story_5083_50830600_26_dialog_content = "<color=#FFB400>Undercity 80</color>, awalnya sektor terdekat dengan Zona Gelap.",
  ui_story_5083_50830600_27_dialog_content = "Selama Perang Dark Zone, Undercity ini memberikan layanan transportasi penting untuk upaya perang Illumina.",
  ui_story_5083_50830600_28_dialog_content = "Komandan Pango juga pernah menyebutkannya... Menurutnya, pertempuran yang terjadi di sana sangat brutal, dan 2nd Legion hampir sepenuhnya dihancurkan.",
  ui_story_5083_50830600_29_dialog_content = "Sebagai anak-anak, kami menghabiskan banyak waktu belajar tentang masa lalu di museum-museum ini. Kami dulu sangat iri dengan legenda-legenda ini... Mereka adalah yang terkeren.",
  ui_story_5083_50830600_30_dialog_content = "Tapi sekarang aku tahu jenis pengorbanan yang dibuat untuk menciptakan legenda-legenda ini... Dan itu bukan sesuatu yang ingin aku lihat lagi.",
  ui_story_5083_50830600_31_dialog_content = "Lanjut... Darkover Crisis, yang masih berlanjut hingga saat ini, diyakini dimulai dengan serangan pada Eraveil dua tahun lalu... Sejauh yang kita ketahui, Caelestite telah sepenuhnya...",
  ui_story_5083_50830600_32_dialog_content = "Hah? Kenapa kamu tiba-tiba berhenti...?",
  ui_story_5083_50830600_33_dialog_content = "Yo, Barton.",
  ui_story_5083_50830600_34_dialog_content = "Sedang apa kau di sini?",
  ui_story_5083_50830600_35_dialog_content = "Menyegarkan kembali sejarah saya, tentu saja. Sejarah Illumina, sejarah perang, hal-hal semacam itu.",
  ui_story_5083_50830600_36_dialog_content = "... Apa pendapatmu tentang bagaimana Illumina akan menjadi di masa depan, Barton?",
  ui_story_5083_50830600_37_dialog_content = "Kenapa tanya begitu?",
  ui_story_5083_50830600_38_dialog_content = "Caelestite yang misterius itu dihancurkan oleh serangan mendadak. Karena itu, kami, Aurorian, tidak akan pernah menerima bimbingan mereka lagi.",
  ui_story_5083_50830600_39_dialog_content = "Krisis <color=#FFB400>Darkover</color> masih belum berakhir, dan kita terus kehilangan semakin banyak prajurit. Lihatlah keluar jendela—Kamu bisa melihat monumen untuk yang gugur dari sini, bukan?",
  ui_story_5083_50830600_40_dialog_content = "Nama-nama setiap saudara laki-laki dan perempuan yang kita kehilangan dalam perang itu terukir di sana... Tapi aku masih bisa mendengar suara mereka bergema di kepalaku.",
  ui_story_5083_50830600_41_dialog_content = "Kita semua mulai belajar sejarah sejak usia muda... Dan semakin tua saya, semakin dekat saya merasa dengan hal-hal yang dipertahankan di sini.",
  ui_story_5083_50830600_42_dialog_content = "Setelah menyaksikan teman-temanku mengorbankan hidup mereka dalam pertempuran, hanya untuk pengorbanan mereka menjadi pelajaran sejarah bagi generasi berikutnya... Aku mulai merasa bingung, Barton.",
  ui_story_5083_50830600_43_dialog_content = "Bingung?",
  ui_story_5083_50830600_44_dialog_content = "Astra dalam bahaya besar, dan meskipun aku bersedia memberikan hidupku demi Astra, aku hanya tidak bisa melihat masa depannya...",
  ui_story_5083_50830600_45_dialog_content = "Kamu tahu orang-orang di Lumopolis sedang bertarung satu sama lain sekarang, kan? Janji mereka untuk membantu kami tidak pernah terwujud, dan kami sudah berhenti berdagang sumber daya dengan mereka.",
  ui_story_5083_50830600_46_dialog_content = "Seluruh Astra saat ini dalam kekacauan. Aku tidak yakin lagi apa yang sedang aku perjuangkan, atau apakah kita bahkan bisa menang.",
  ui_story_5083_50830600_47_dialog_content = "... Apakah kamu takut?",
  ui_story_5083_50830600_48_dialog_content = "Tentu saja aku takut... Keberuntungan adalah satu-satunya alasan kami bertahan hidup ketika rekan-rekan kami yang lain tidak.",
  ui_story_5083_50830600_49_dialog_content = "Kamu bilang ini adalah sesuatu yang harus kita tanggung seumur hidup kita. Aku berusaha sebaik mungkin untuk hidup dengan itu...",
  ui_story_5083_50830600_50_dialog_content = "Tahukah kamu bahwa Committee telah mengganggu rencana Grand Marshal? Mereka masih belum bisa memutuskan cara terbaik untuk melanjutkan perang. Cukup meyakinkan, bukan?",
  ui_story_5083_50830600_51_dialog_content = "Namun, saya yakin rasa takut saya tidak ada apa-apanya dibandingkan dengan para prajurit yang kembali dari Dark Zone War.",
  ui_story_5083_50830600_52_dialog_content = "Saat ini, Illumina tidak memiliki kapten yang jelas di kemudi. Bukankah itu menakutkanmu, Barton?",
  ui_story_5083_50830600_53_dialog_content = "Jika itu masalahnya, maka kita akan melakukannya.",
  ui_story_5083_50830600_54_dialog_content = "Kamu, aku, dan gadis Reinhardt dari 1st Legion!",
  ui_story_5083_50830600_55_dialog_content = "Kita diperbolehkan untuk ikut serta dalam hal-hal ini, bukan?",
  ui_story_5083_50830600_56_dialog_content = "Bagaimanapun, ini adalah masa depan yang kita bicarakan! Siapa lagi yang lebih baik menghadapi tantangan di masa mendatang selain generasi pemimpin berikutnya?",
  ui_story_5083_50830600_57_dialog_content = "Tidak peduli apa yang orang lain pikirkan, aku tidak akan pernah mundur. Aku tidak akan membiarkan Illumina terbalik hanya karena tidak ada yang bisa mengetahui bagaimana cara mengendalikannya!",
  ui_story_5083_50830600_58_dialog_content = "Jadi jika kamu tidak yakin apa yang harus dilakukan, serahkan saja hidupmu kepadaku dan aku akan menunjukkan jalan!",
  ui_story_5083_50830600_59_dialog_content = "Heh... Pembicaraan yang cukup besar untuk seorang pria yang sama sekali tidak memiliki kaki laut.",
  ui_story_5083_50830600_60_dialog_content = "*Berdesah* Aku hanya... Tidak tahu bagaimana kau bisa begitu percaya diri sementara aku masih terjebak dalam pikiranku sendiri.",
  ui_story_5083_50830600_61_dialog_content = "Aku juga anak dari Illumina, Barton. Tidak ada yang bisa menebak siapa yang akan memimpin kapal ini di masa depan.",
  ui_story_5083_50830600_62_dialog_content = "Tapi satu hal yang pasti: Aku akan membuktikan kepada Komandan Pango bahwa aku adalah prajurit elit yang telah dia tunggu selama ini!",
  ui_story_5083_50830600_63_dialog_content = "Lakukan apa pun yang kamu mau, Dogg. Bukan seperti saya mencoba untuk mengesankan pria tua itu atau apa pun.",
  ui_story_5083_50830600_64_dialog_content = "Sebenarnya, sebelum datang ke sini hari ini, aku telah mengajukan permintaan—aku ingin membentuk unit komando untuk 2nd Legion.",
  ui_story_5083_50830600_65_dialog_content = "Setelah apa yang terjadi waktu itu, saya menyadari bahwa pertahanan kita jatuh cukup cepat ketika kita berhadapan dengan Eclipsite.",
  ui_story_5083_50830600_66_dialog_content = "Itulah sebabnya saya ingin mendirikan sebuah <color=#FFB400>cabang serangan</color> dan melatih prajurit untuk melawan Eclipsite. Saya yakin kita akan membutuhkan pejuang seperti itu di masa depan.",
  ui_story_5083_50830600_67_dialog_content = "Seandainya saja Lumopolis memutuskan untuk bekerja sama dengan kita... Mereka bisa membantu kita melatih prajurit berkuda.",
  ui_story_5083_50830600_68_dialog_content = "Aku tahu teknologi akan menentukan banyak pertempuran bagi kita di masa depan... Tapi tidak bisa dipungkiri juga pentingnya unit darat.",
  ui_story_5083_50830600_69_dialog_content = "Dan mengingat tingkat produksi kita masih tertinggal, kita hanya bisa mengandalkan baja dingin untuk membuka jalan dan menjaga musuh tetap jauh.",
  ui_story_5083_50830600_70_dialog_content = "Itu wawasan yang mengesankan, Dogg... Sejujurnya, aku belum memikirkan hal-hal sebanyak itu.",
  ui_story_5083_50830600_71_dialog_content = "Tapi jika itu rencanamu, lalu kenapa kamu sangat menginginkan persetujuan dari komandan? Kenapa kamu merasa harus membuktikan dirimu?",
  ui_story_5083_50830600_72_dialog_content = "Dia adalah komandan kami, dan dia melatih kami sebaik mungkin. Bukankah itu alasan yang cukup?",
  ui_story_5083_50830600_73_dialog_content = "Memang, tapi saya yakin itu bukan satu-satunya alasan.",
  ui_story_5083_50830600_74_dialog_content = "Heh... Meskipun kamu idiot yang berotot, terkadang kamu bisa cukup peka.",
  ui_story_5083_50830600_75_dialog_content = "... Pria tua saya adalah teman baik dengan Komandan Pango di masa lalu. Itulah bagaimana dia akhirnya merawat saya.",
  ui_story_5083_50830600_76_dialog_content = "Dia membesarkan dan merawatku seperti anaknya sendiri. Bagiku, Komandan Pango tidak berbeda dengan ayahku.",
  ui_story_5083_50830600_77_dialog_content = "Anak lelakinya adalah kakak laki-lakiku, dan istrinya adalah ibuku.",
  ui_story_5083_50830600_78_dialog_content = "Saya tidak tahu kalau komandan memiliki keluarga... Apakah sesuatu terjadi pada mereka...?",
  ui_story_5083_50830600_79_dialog_content = "Enam tahun lalu, Undercity tempat kami tinggal diserang.",
  ui_story_5083_50830600_80_dialog_content = "Tapi, sebagai prajurit yang dia adalah, Komandan Pango sedang bertempur di garis depan pada saat itu.",
  ui_story_5083_50830600_81_dialog_content = "Dia mengorbankan istrinya untuk mengungsikan saya dan non-kombatan lainnya.",
  ui_story_5083_50830600_82_dialog_content = "Komandan itu tidak pernah membicarakannya, tetapi dia langsung meminta untuk dipindahkan dari garis depan. Sejak saat itu, dia menolak untuk memimpin operasi pertahanan apa pun di Undercities.",
  ui_story_5083_50830600_83_dialog_content = "... Saya yakin dia masih menyalahkan dirinya sendiri atas apa yang terjadi.",
  ui_story_5083_50830600_84_dialog_content = "Apakah itulah sebabnya pria tua itu... Tidak pernah berlama-lama di kamp?",
  ui_story_5083_50830600_85_dialog_content = "Tidak ada yang salah darinya—Saya hanya berharap saya bisa membuatnya melihat itu.",
  ui_story_5083_50830600_86_dialog_content = "Saya hampir seumuran dengan kakak saya waktu itu... Saya ingin Komandan Pango tahu bahwa salah satu anaknya masih hidup.",
  ui_story_5083_50830600_87_dialog_content = "Namun, tidak peduli seberapa keras aku mencoba, matanya... Selalu menatapmu.",
  ui_story_5083_50830600_88_dialog_content = "Kadang-kadang aku iri padamu, Barton. Apakah karena aku tidak cukup kuat?",
  ui_story_5083_50830600_89_dialog_content = "Di akhir hari... Saya hanya ingin menggantikan tempat kakakku dan mengisi lubang di hati komandan.",
  ui_story_5083_50830600_90_dialog_content = "Dogg... Sejauh yang aku tahu, kamu sudah lebih dari cukup. Tidak ada alasan bagi kamu untuk menjadi orang lain.",
  ui_story_5083_50830600_91_dialog_content = "Seberat apapun kamu, tidak ada orang lain di seluruh Astra seperti kamu! Kamu tidak perlu hidup dalam bayangan orang lain!",
  ui_story_5083_50830600_92_dialog_content = "Saya yakin pria tua itu juga setuju dengan saya. Kenapa lagi dia begitu keras pada kamu?",
  ui_story_5083_50830600_93_dialog_content = "Dan berkat kamu, akhirnya saya mengerti betapa tidak langsungnya pria itu. Dia mungkin tidak akan pernah membuka diri kepada kamu tentang hal itu.",
  ui_story_5083_50830600_94_dialog_content = "Selain itu, kamu bilang kamu juga <color=#FFB400>anak</color>-nya, kan? Aku tidak bisa membayangkan siapa pun yang ingin melihat salah satu anak mereka mencoba menggantikan yang lain.",
  ui_story_5083_50830600_95_dialog_content = "Barton... You...",
  ui_story_5083_50830600_96_dialog_content = "Heh—Hahahaha! Pria, saya tidak tahu kalau kamu punya apa-apa selain otot di otakmu!",
  ui_story_5083_50830600_97_dialog_content = "Kata-kata ini benar-benar tidak cocok untukmu sama sekali, Barton. Setelah adegan yang kamu buat kemarin, kamu adalah orang terakhir yang seharusnya memberi saya saran, hahaha!",
  ui_story_5083_50830600_98_dialog_content = "Aku tidak bercanda, Dogg.",
  ui_story_5083_50830600_99_dialog_content = "Aku tahu. Terima kasih, Barton; kamu telah memberiku banyak hal untuk dipikirkan.",
  ui_story_5083_50830600_100_dialog_content = "Jangan sungkan. Coba untuk sedikit lebih langsung mulai sekarang... Dogg.",
  ui_story_5083_50830700_1_dialog_content = "<color=#e8d9bb>Tidak lama kemudian, Divisi Commando dari 2nd Legion resmi didirikan, dan Dogg dipilih sebagai komandannya setelah dipromosikan menjadi Major. Barton, di sisi lain, dipromosikan menjadi Kapten dan menjadi wakil komandan Batalyon Infanteri Mekanis.</color>",
  ui_story_5083_50830700_2_dialog_content = "<color=#e8d9bb>Tapi, kekhawatiran Dogg terbukti benar, dan segera, keparahan Darkover Crisis mencapai tingkat yang sangat mengerikan.</color>",
  ui_story_5083_50830700_3_dialog_content = "<color=#e8d9bb>Eclipsite berhasil menembus garis pertahanan Illumina dan mulai mengepung Undercity 13 dan 19, instalasi pertahanan terdepan Federasi.</color>",
  ui_story_5083_50830700_4_dialog_content = "<color=#e8d9bb>Komunikasi dinonaktifkan lebih awal dalam pertempuran. Saat seorang kurir berhasil keluar dan tiba di Kota Gannon, dua Undercities sudah berada di bawah pengepungan selama beberapa hari.</color>",
  ui_story_5083_50830700_5_dialog_content = "<color=#e8d9bb>Sebuah darurat antara para pemimpin Kota Gannon dipanggil, tetapi bahkan setelah berjam-jam berunding, keputusan tidak bisa dibuat—</color>",
  ui_story_5083_50830700_6_dialog_content = "Kami tidak bisa menunggu lebih lama lagi! Dengan setiap menit yang kita buang-buang berbincang-bincang di sini, siapa tahu berapa banyak nyawa yang hilang?!",
  ui_story_5083_50830700_7_dialog_content = "2nd Legion siap dikerahkan, Grand Marshal. Berikan perintah dan kami akan segera berangkat.",
  ui_story_5083_50830700_8_dialog_content = "Menurut utusan, Undercity 13 hanya dilengkapi untuk bertahan satu hari lagi dalam pengepungan. Pada titik ini, tidak ada harapan untuk mereka.",
  ui_story_5083_50830700_9_dialog_content = "Dan meski situasi Undercity 19 tampak kurang genting, sangat mungkin pasukan kita hanya akan menemukan kota mati yang dipenuhi Eclipsite saat mereka tiba.",
  ui_story_5083_50830700_10_dialog_content = "Komandan pertahanan Undercity 13 adalah teman lama kamu di masa perang, Pango. Kamu seharusnya lebih tahu daripada siapa pun—",
  ui_story_5083_50830700_11_dialog_content = "Prajurit terhormat seperti dia dan bawahannya lebih memilih meledakkan seluruh Undercity daripada membiarkannya jatuh ke tangan musuh!",
  ui_story_5083_50830700_12_dialog_content = "Dengan cara itu, mereka dapat mencegah Eclipsite dari memanfaatkan sumber daya kita dan menjaga Kota Gannon tetap aman!",
  ui_story_5083_50830700_13_dialog_content = "Kau benar sekali! Aku lebih mengenal orang-orang keras kepala itu daripada kebanyakan orang, dan itulah yang pasti mereka lakukan—",
  ui_story_5083_50830700_14_dialog_content = "Tapi saya juga tahu betapa kuat dan gigihnya mereka!",
  ui_story_5083_50830700_15_dialog_content = "Masih banyak warga sipil dan sumber daya yang terjebak di kota-kota itu, dan para tentara itu bersedia merisikokan hidup mereka untuk mereka!",
  ui_story_5083_50830700_16_dialog_content = "Mereka tidak akan meninggalkan kota mereka hingga akhir yang pahit! Itulah sebabnya saya tahu mereka menunggu kita untuk menyelamatkan mereka!",
  ui_story_5083_50830700_17_dialog_content = "Setengah dari legiunku masih bertempur di Zona Gelap, dan kamu baru saja mengisi ulang legiunmu dengan rekrutan baru.",
  ui_story_5083_50830700_18_dialog_content = "Dan dengan 1st Legion terlalu sibuk memperkuat pertahanan kita... Siapa lagi yang bisa kita kerahkan?",
  ui_story_5083_50830700_19_dialog_content = "Meski semua pasukan kita ada, mempertahankan Kota Gannon dari Eclipsite tidak akan mudah. Apakah kamu benar-benar berpikir kita bisa membiarkan beberapa prajurit?",
  ui_story_5083_50830700_20_dialog_content = "Dan mengingat sejauh itu dua Undercity dari kita, kita tidak akan bisa menggunakan kereta untuk mengirim bala bantuan. Kita harus mengirim mereka dengan berjalan kaki.",
  ui_story_5083_50830700_21_dialog_content = "Dengan komunikasi terputus, kita tidak tahu apa yang menunggu kita di luar sana. Bagaimana jika pasukan kita disergap di tengah jalan? Mereka akan berada dalam bahaya serius!",
  ui_story_5083_50830700_22_dialog_content = "Kamu tidak berpikir bahwa dua Undercity itu dalam bahaya serius sekarang?!?",
  ui_story_5083_50830700_23_dialog_content = "Motor, kenapa sih kau ini tega sekali?!",
  ui_story_5083_50830700_24_dialog_content = "Kau tarik kembali kata-katamu, Pango! Apakah kamu tahu berapa banyak prajurit yang telah kuhilangkan ke Dark Zone?! Kamu bukan satu-satunya yang harus khawatir tentang nyawa orang-orang!",
  ui_story_5083_50830700_25_dialog_content = "Aku sudah selesai mendengarkan omongan sampah ini...",
  ui_story_5083_50830700_26_dialog_content = "Barton!",
  ui_story_5083_50830700_27_dialog_content = "Orang-orang itu memperlakukan kita seperti perisai mereka, dan namun mereka membuang kita ke tanah segera setelah situasi menjadi sulit.",
  ui_story_5083_50830700_28_dialog_content = "Kamu tidak bebas untuk berbicara apa yang ada di pikiranmu di sini, prajurit.",
  ui_story_5083_50830700_29_dialog_content = "Oh maaf, aku akan melihat diriku sendiri keluar—Lagipula, bergaul dengan kalian membuatku muak.",
  ui_story_5083_50830700_30_dialog_content = "Kamu pikir kamu siapa, berbicara seperti itu?!",
  ui_story_5083_50830700_31_dialog_content = "Maaf tentang itu, Tuan. Saya cukup yakin mulutnya tidak sepenuhnya terhubung dengan otaknya.",
  ui_story_5083_50830700_32_dialog_content = "Apa yang kamu pikirkan sedang kamu lakukan, Dogg?! Jangan bicara seperti itu tentang rekan prajuritmu!",
  ui_story_5083_50830700_33_dialog_content = "Apakah kalian sudah selesai?",
  ui_story_5083_50830700_34_dialog_content = "Saya yakin pertengkaran kalian sangat penting, tetapi 1st Legion masih berjuang untuk hidup mereka di luar sana.",
  ui_story_5083_50830700_35_dialog_content = "Katakan padaku, perwira muda: apakah kalian mendukung keputusan komandanmu?",
  ui_story_5083_50830700_36_dialog_content = "Tentu saja, Grand Marshal.",
  ui_story_5083_50830700_37_dialog_content = "... Sebenarnya, aku percaya bahwa komandan dari 3rd Legion memiliki alasan yang kuat.",
  ui_story_5083_50830700_38_dialog_content = "Apa? Kau sudah gila, Dogg?!",
  ui_story_5083_50830700_39_dialog_content = "Aku sudah bilang, aku masih bisa mendengar suara rekan-rekan yang telah gugur dalam kepalaku... Kita tidak boleh ceroboh, jika tidak pengorbanan mereka akan sia-sia.",
  ui_story_5083_50830700_40_dialog_content = "... Kau diberhentikan untuk sekarang.",
  ui_story_5083_50830700_41_dialog_content = "Dimengerti, Komandan Pango! Saya hanya meminta Anda dan Kapten Barton mempertimbangkan risiko dengan hati-hati sebelum membuat keputusan apa pun.",
  ui_story_5083_50830700_42_dialog_content = "Anak-anak Illumina tumbuh besar di bawah kejayaan Central Tower! Mereka sangat mengerti kebenaran dari tujuan kami!",
  ui_story_5083_50830700_43_dialog_content = "Sebelum prajurit kita dikerahkan ke berbagai Undercity, mereka sudah diberi tahu tentang kemungkinan ini jauh-jauh hari.",
  ui_story_5083_50830700_44_dialog_content = "Waktu untuk diskusi telah berakhir, Pango. Kita perlu bekerja sama untuk mempertahankan Kota Gannon.",
  ui_story_5083_50830700_45_dialog_content = "Jika mereka bersedia memberikan nyawa mereka untuk Illumina, maka tugas kita untuk memastikan pengorbanan mereka tidak sia-sia.",
  ui_story_5083_50830700_46_dialog_content = "Jika kamu tidak pergi, maka tentara dan saya akan pergi!",
  ui_story_5083_50830700_47_dialog_content = "Tidak, Pango.",
  ui_story_5083_50830700_48_dialog_content = "Motor benar: kita hampir tidak memiliki pengetahuan tentang situasi di luar sana, dan kita tidak bisa menanggung lebih banyak kerugian lagi. Dalam hal apapun, 1st Legion tidak akan menyisihkan prajurit untuk ini.",
  ui_story_5083_50830700_49_dialog_content = "Kita seharusnya saling membantu melalui cobaan ini. Sekarang bukan waktunya untuk pertikaian internal.",
  ui_story_5083_50830700_50_dialog_content = "Jika para prajurit kita melihat ini, semangat mereka akan jatuh drastis.",
  ui_story_5083_50830700_51_dialog_content = "Grr... Kami pergi, Barton!",
  ui_story_5083_50830700_52_dialog_content = "Pertahankan posisi Anda dan jangan melakukan tindakan tanpa izin, Komandan! Itu adalah perintah!",
  ui_story_5083_50830700_53_dialog_content = "Hei, kalian berdua. Saya mengerti jika hal-hal tidak berjalan terlalu baik di sana?",
  ui_story_5083_50830700_54_dialog_content = "Dengan pengecut itu memimpin 1st Legion? Tentu saja tidak!",
  ui_story_5083_50830700_55_dialog_content = "Jangan pergi dulu! Saya di sini untuk mengantarkan <color=#FFB400>pesanan</color> baru.",
  ui_story_5083_50830700_56_dialog_content = "\"Dengan segera, 2nd Legion harus dikerahkan ke Undercities 13 dan 19 untuk memberikan bala bantuan, dengan Letnan Reinhardt dan sebagian dari 1st Legion juga memberikan dukungan...\"",
  ui_story_5083_50830700_57_dialog_content = "Itu kurang lebih intinya. Bagaimana menurutmu?",
  ui_story_5083_50830700_58_dialog_content = "Kamu serius berpikir untuk memalsukan perintah militer?",
  ui_story_5083_50830700_59_dialog_content = "Jika kamu tidak mau membantu, maka kami akan menanganinya sendiri.",
  ui_story_5083_50830700_60_dialog_content = "Saya bisa mengirimkan beberapa skuad dari 1st Legion; sisanya lebih dari mampu untuk mempertahankan Gannon City bersama dengan 3rd Legion.",
  ui_story_5083_50830700_61_dialog_content = "Kita mungkin tidak memiliki banyak pengaruh di sini, tetapi kehadiran kita di Undercities tersebut bisa berarti perbedaan antara hidup dan mati.",
  ui_story_5083_50830700_62_dialog_content = "Sayangnya, aku tidak memiliki cukup banyak prajurit untuk misi ini. Itulah sebabnya aku ingin meminta bantuan dari 2nd Legion.",
  ui_story_5083_50830700_63_dialog_content = "Kamu tahu apa yang akan terjadi pada dirimu jika kita ikuti ini, 'kan?",
  ui_story_5083_50830700_64_dialog_content = "Aku menghargai kekhawatiranmu, Commander... Tapi, menyelamatkan orang-orang masih lebih penting bagiku.",
  ui_story_5083_50830700_65_dialog_content = "... Kamu hanya letnan rendahan. Apa yang memberimu kepercayaan diri untuk mendekati kami dengan aksi seperti ini?",
  ui_story_5083_50830700_66_dialog_content = "Percayaanku adalah bahwa kalian berdua tidak akan pernah meninggalkan rekan-rekanmu.",
  ui_story_5083_50830700_67_dialog_content = "Apakah Anda masih belum memutuskan, Komandan Pango? Karena saya akan pergi dengannya bagaimanapun juga.",
  ui_story_5083_50830700_68_dialog_content = "Pertama kau melanggar perintah, dan sekarang kau memalsukannya? Kau benar-benar berani, Reinhardt.",
  ui_story_5083_50830700_69_dialog_content = "Itu saja yang harus kamu katakan setelah mengikutiku sejauh ini?",
  ui_story_5083_50830700_70_dialog_content = "Hah! Kamu pikir aku hanya akan berdiri dan membiarkanmu melakukan apa saja yang kamu mau?",
  ui_story_5083_50830700_71_dialog_content = "Menarik... Sepertinya kita bukan satu-satunya yang muak dengan atasan, bukan? Bagus! Sudah saatnya kita yang memegang kendali di sini!",
  ui_story_5083_50830700_72_dialog_content = "Hmph. Undercity 13 adalah yang paling berbahaya, jadi biarkan aku yang mengurusnya.",
  ui_story_5083_50830700_73_dialog_content = "Silakan, Wrath. Berapa banyak prajurit yang kamu butuhkan?",
  ui_story_5083_50830700_74_dialog_content = "Mengingat pasukan di sini sedang kekurangan, aku hanya akan membawa satu peleton saja.",
  ui_story_5083_50830700_75_dialog_content = "Bagaimana kamu berharap bisa berhasil hanya dengan satu peleton? Lupakan, aku akan ikut, dan aku akan membawa lebih banyak prajurit bersamaku!",
  ui_story_5083_50830700_76_dialog_content = "Tunggu!",
  ui_story_5083_50830700_77_dialog_content = "Seberapapun menjengkelkannya Motor, Departemen Intelijennya hampir tidak pernah salah.",
  ui_story_5083_50830700_78_dialog_content = "Situasi Undercity 13 jauh dari optimis... Dari perspektif waktu semata, memang benar bahwa kota ini sudah tak bisa diselamatkan lagi.",
  ui_story_5083_50830700_79_dialog_content = "Jika kita mengirim terlalu banyak pasukan kita, ada kemungkinan besar mereka akan terjebak dalam pertempuran tanpa jalan keluar.",
  ui_story_5083_50830700_80_dialog_content = "Mengerti... Maka hanya akan ada kamu dan tim kecil, Wrath.",
  ui_story_5083_50830700_81_dialog_content = "Jangan kehilangan kepala Anda dalam pertempuran. Prioritaskan evakuasi dan penyelamatan di atas segalanya, mengerti?",
  ui_story_5083_50830700_82_dialog_content = "Seperti aku butuh kamu memberi perintah—Tunggu saja, Reinhardt. Aku akan membawa setiap orang kembali!",
  ui_story_5083_50830700_83_dialog_content = "Tunggu, aku akan pergi bersamamu! Sebagai wakil komandan, aku memiliki banyak prajurit yang akan mengikutiku ke medan perang.",
  ui_story_5083_50830700_84_dialog_content = "Biarkan dia menangani ini, Barton. Saya sudah melihat kekuatannya sendiri, dan dia adalah orang terbaik untuk jenis pertarungan ini.",
  ui_story_5083_50830700_85_dialog_content = "Undercity 19 jauh lebih besar, yang berarti mereka memiliki peluang lebih baik untuk bertahan lebih lama.",
  ui_story_5083_50830700_86_dialog_content = "Tapi jika Undercity 13 sudah tumbang, hampir pasti musuh akan memusatkan serangan mereka ke Undercity 19 selanjutnya.",
  ui_story_5083_50830700_87_dialog_content = "Barton! Kamu mungkin seorang idiot, tetapi aku telah membentukmu menjadi salah satu senjata paling kuat dari Illumina.",
  ui_story_5083_50830700_88_dialog_content = "Pertempuran skala besar seperti itu sangat cocok untukmu dan Divisi Infanteri Mekanis kita.",
  ui_story_5083_50830700_89_dialog_content = "Sayangnya, pengawal yang bertanggung jawab atas gudang peralatan hanya menerima perintah dari komando tertinggi, yang berarti perintah palsu sama sekali tidak berguna. Kamu harus memanfaatkan pergantian shift mereka dan membuat tentara kamu mencuri sebanyak yang mereka bisa.",
  ui_story_5083_50830700_90_dialog_content = "Tunggu, apakah kamu mengatakan kamu ingin kita pergi lebih dulu dan mengamankan Undercity 19 seperti yang kita lakukan terakhir kali?",
  ui_story_5083_50830700_91_dialog_content = "Cukup dengarkan rencana Commander Pango, Barton. Memimpin seluruh 2nd Legion keluar dari Gannon City bukanlah sesuatu yang bisa kita lakukan sendiri.",
  ui_story_5083_50830700_92_dialog_content = "Sekarang cepat, sebelum mereka sempat menyadari! Hemat waktu dengan menggunakan elevator utama untuk naik!",
  ui_story_5083_50830700_93_dialog_content = "... Hanya jangan sampai Komite menangkapmu sebelum kamu datang menyelamatkan kami, pria tua.",
  ui_story_5083_50830700_94_dialog_content = "Tunggu! Apakah semua dari kalian serius melakukan ini?",
  ui_story_5083_50830700_95_dialog_content = "Komandan, kamu dan Barton akan diberi cap sebagai pengkhianat jika kamu pergi seperti ini—Apakah kamu benar-benar bersedia melakukan itu pada Illumina? Pada orang-orang yang kamu pedulikan?!",
  ui_story_5083_50830700_96_dialog_content = "Pelanggaran perintah, pemalsuan perintah, dan pengkhianatan yang nyata... Grand Marshal tidak akan membiarkan kejahatan ini begitu saja.",
  ui_story_5083_50830700_97_dialog_content = "...",
  ui_story_5083_50830700_98_dialog_content = "Aku tidak peduli tentang semua itu, Dogg. Aku hanya memiliki satu pertanyaan untukmu: Kamu datang atau tidak?",
  ui_story_5083_50830700_99_dialog_content = "Setelah semua yang kamu ceritakan padaku di museum, apakah kamu serius bilang bahwa kamu tidak ingin menyelamatkan mereka?",
  ui_story_5083_50830700_100_dialog_content = "Tentu saja saya ingin menyelamatkan mereka! Tapi...",
  ui_story_5083_50830700_101_dialog_content = "Mungkin kita masih bisa membujuk Grand Marshal untuk membantu kita? Jika aku hanya memberitahunya semua ini...",
  ui_story_5083_50830700_102_dialog_content = "Tahan dulu, Dogg! Siapa kamu untuk berdebat dengan Grand Marshal.",
  ui_story_5083_50830700_103_dialog_content = "Tapi tanpa persetujuannya, kita tidak bisa bertindak tentang ini...",
  ui_story_5083_50830700_104_dialog_content = "Izinkan saya mengulangi pertanyaan Barton: Kamu datang atau tidak?",
  ui_story_5083_50830700_105_dialog_content = "Kita akan melanggar perintah tanpa persetujuannya... Aku menolak untuk melakukan kejahatan yang begitu keji terhadap Illumina... Dan meninggalkan aku di belas kasihan Komite...",
  ui_story_5083_50830700_106_dialog_content = "Pengkhianat sejati di sini adalah Grand Marshal dan yang lainnya! Bagaimana mereka bisa memejamkan mata sementara sekutu kita—",
  ui_story_5083_50830700_107_dialog_content = "Cukup, Letnan Reinhardt! Saya sangat mampu mendidik bawahan saya sendiri, terima kasih banyak!",
  ui_story_5083_50830700_108_dialog_content = "Anjing... Aku mengerti dilemamu, jadi kembali saja ke kamp.",
  ui_story_5083_50830700_109_dialog_content = "Peluru yang salah arah tidak memiliki daya henti, jadi tidak perlu bagi kamu untuk ikut serta. Jika kamu masih merasa bersalah tentang ini, silakan laporkan kami.",
  ui_story_5083_50830700_110_dialog_content = "T-Tidak, Commander Pango... Kamu haruslah yang memberi saya perintah! Saya akan pergi ke mana saja selama kamu menyuruh saya—",
  ui_story_5083_50830700_111_dialog_content = "Aku tidak akan memaksamu!",
  ui_story_5083_50830700_112_dialog_content = "Kamu tidak perlu begitu takut, Dogg; kamu tidak melakukan apa-apa yang salah. Tetapi segala sesuatu tidak selalu sejelas hukum-hukum Illumina.",
  ui_story_5083_50830700_113_dialog_content = "Barton. Letnan Reinhardt. Sudah waktunya untuk bergerak.",
  ui_story_5083_50830700_114_dialog_content = "Ikutlah jika itu yang kamu inginkan, tetapi jika kamu tidak bisa membuat pilihan itu, tetaplah di sini dan amankan jalur kembali kami.",
  ui_story_5083_50830700_115_dialog_content = "Bagaimanapun juga, kami akan mengandalkanmu.",
  ui_story_5083_50830700_116_dialog_content = "Barton, kamu idiot... Coba untuk tidak mati sebelum mereka memberikan perintah...",
  ui_story_5083_50830700_117_dialog_content = "<color=#e8d9bb>Reinhardt dan Barton memanfaatkan pergantian penjaga dan memimpin kelompok mereka ke gudang peralatan, mengambil sebanyak mungkin sebelum ada yang bisa menyadari.</color>",
  ui_story_5083_50830700_118_dialog_content = "<color=#e8d9bb>Ketika para pengawal akhirnya menemukan aksi pemberontak, Barton terpaksa membawa bagian belakang dan mengawal mobil lapis baja terakhir melalui hujan tembakan.</color>",
  ui_story_5083_50830700_119_dialog_content = "Cepat! Kami telah mengganggu komunikasi mereka. Sekarang muat semua ke dalam elevator utama sebelum mereka memutus daya!",
  ui_story_5083_50830700_120_dialog_content = "Fyuh—Itu nyaris saja. Mereka jelas menembak untuk membunuh barusan...",
  ui_story_5083_50830700_121_dialog_content = "*Bunyi bip* Yah, kamu memang telah melakukan tindakan pengkhianatan tertinggi, Barton...",
  ui_story_5083_50830700_122_dialog_content = "Eh? Kapan kamu tiba di sini?",
  ui_story_5083_50830700_123_dialog_content = "Maaf kecil, tapi kamu baru saja naik ke kapal yang penuh dengan bajak laut. Masih ada waktu untuk melompat keluar sebelum lift naik lebih tinggi, tahu?",
  ui_story_5083_50830700_124_dialog_content = "Bip—Barton...",
  ui_story_5083_50830700_125_dialog_content = "Navigatormu tidak akan pernah meninggalkanmu—",
  ui_story_5083_50830801_1_dialog_content = "<color=#e8d9bb>Di malam tanpa bulan, lautan Eclipsite berkumpul mengancam di pintu masuk Undercity 19.</color>",
  ui_story_5083_50830801_2_dialog_content = "<color=#e8d9bb>Setelah berhari-hari dikepung, semua meriam jarak pendek kota ini kehabisan amunisi atau sepenuhnya hancur. Orang-orang di dalamnya hanya bisa menunggu akhir dalam keheningan yang tak berdaya.</color>",
  ui_story_5083_50830801_3_dialog_content = "<color=#e8d9bb>Di satu-satunya pintu masuk ke Undercity, para prajurit Illumina berjuang mati-matian untuk menahan Eclipsite. Tanpa amunisi, mereka menggunakan pedang mereka; tanpa pedang, mereka menggunakan tinju mereka.</color>",
  ui_story_5083_50830801_4_dialog_content = "<color=#e8d9bb>Megang teguh keyakinan bahwa mereka adalah perisai Federasi, mereka berjuang tanpa pikiran lain di benak mereka selain kilauan harapan yang paling samar.</color>",
  ui_story_5083_50830801_5_dialog_content = "<color=#e8d9bb>\"Utusan berhasil keluar. Kota Gannon akan segera mengirim bala bantuan.\"</color>",
  ui_story_5083_50830801_6_dialog_content = "<color=#e8d9bb>Setelah sepuluh hari, cahaya redup itu mulai bergetar. Tapi tepat sebelum bisa padam, para prajurit yang teguh melihat jawaban dari doa mereka di balik lautan darah dan tulang—</color>",
  ui_story_5083_50830801_7_dialog_content = "<size=45>Kirim mereka terbang!</size>",
  ui_story_5083_50830801_8_dialog_content = "Itu celah kita! Kirim para pejuang kita untuk memperkuat posisi itu!",
  ui_story_5083_50830801_9_dialog_content = "Isi kembali amunisi setiap orang sebelum memeriksa pertahanan kota! Gunakan meriam jarak pendek apa pun yang masih beroperasi, dan ubah sisanya menjadi meriam sekali pakai!",
  ui_story_5083_50830801_10_dialog_content = "Reinhardt! Pergi cek status kota sementara kami tahan pintu masuk!",
  ui_story_5083_50830801_11_dialog_content = "Cologne! Bawa mobil transportasi berlapis baja itu ke sini!",
  ui_story_5083_50830801_12_dialog_content = "Saya adalah bagian dari bala bantuan yang dikirim dari Kota Gannon! Siapa yang bertanggung jawab atas kota ini sekarang?",
  ui_story_5083_50830801_13_dialog_content = "Komandan kami tewas dalam pertempuran—Kamu bisa menyampaikan informasi apa pun kepadaku!",
  ui_story_5083_50830801_14_dialog_content = "Divisi Infanteri Mekanis akan menstabilkan situasi di permukaan. Ambil sisa prajuritmu dan mulai memperkuat pertahananmu!",
  ui_story_5083_50830801_15_dialog_content = "Untuk warga sipil yang masih terjebak di sini, muat semua sumber daya berharga ke dalam kendaraan lapis baja kita dan gunakan untuk evakuasi segera—",
  ui_story_5083_50830801_16_dialog_content = "Tapi bagaimana dengan kamu dan pasukanmu?",
  ui_story_5083_50830801_17_dialog_content = "Kami akan tetap di sini dan mempertahankan tempat ini sampai damai kembali dipulihkan!",
  ui_story_5083_50830801_18_dialog_content = "Kami hanya tim penyerang, tapi jangan khawatir; sisa pasukan kita akan segera tiba.",
  ui_story_5083_50830801_19_dialog_content = "Tetap bersama dan jangan menyerah! Kita akan melindungi kota ini!",
  ui_story_5083_50830801_20_dialog_content = "<color=#e8d9bb>Saat gelombang kegelapan terus melancarkan serangan tanpa henti, Barton memimpin batalionnya yang terdiri dari belasan tank langsung menuju kekuatan musuh, dengan tekad nekat untuk membalikkan keadaan pertempuran.</color>",
  ui_story_5083_50830801_21_dialog_content = "<color=#e8d9bb>Tapi di hadapan jumlah yang begitu besar, kekuatan mereka jauh dari cukup—</color>",
  ui_story_5083_50830801_22_dialog_content = "Sial, roda tank kita rusak dan ada Eclipsite raksasa yang mendekat! Maaf, Vice-komandan Barton—Sungguh sebuah kehormatan bisa berjuang bersamamu, Pak!",
  ui_story_5083_50830801_23_dialog_content = "Tidak, tunggu, aku akan segera ke sana—",
  ui_story_5083_50830801_24_dialog_content = "Jayalah Illumina!",
  ui_story_5083_50830801_25_dialog_content = "<color=#e8d9bb>Tank yang terhenti menyalakan sisa amunisinya, menghasilkan ledakan besar yang melahap setiap Eclipsite di sekitarnya.</color>",
  ui_story_5083_50830801_26_dialog_content = "<size=45>Makan nih pelurunya, kamu monster menjijikkan!!!</size>",
  ui_story_5083_50830801_27_dialog_content = "Dapatkan senapan jarak dekat itu berfungsi, dan jangan pelit dengan tembakanmu! Habisi sebanyak mungkin yang kamu bisa!",
  ui_story_5083_50830801_28_dialog_content = "Kita perlu mendorong mereka kembali sebelum mereka bisa melakukan hal yang sama kepada kita!",
  ui_story_5083_50830801_29_dialog_content = "<size=45>Siap, Pak!!!</size>",
  ui_story_5083_50830801_30_dialog_content = "Melaporkan! Sistem pertahanan Undercity 13 telah sepenuhnya dinonaktifkan. Mengingat situasi saat ini, kami memperkirakan bahwa Eclipsite akan menerobos masuk ke tempat perlindungan dalam waktu kurang lebih dua puluh menit.",
  ui_story_5083_50830801_31_dialog_content = "Komunikasi masih terputus, dan tim gerilya kita tidak dapat mencapai lantai atas untuk memperbaiki jalur. <color=#FFB400>Eclipsite raksasa</color> yang menyerang kita sebelumnya sudah pergi, tetapi kota ini dipenuhi oleh Eclipsite yang lebih kecil.",
  ui_story_5083_50830801_32_dialog_content = "Dengan stasiun tenaga kita yang sepenuhnya hancur, satu-satunya hal yang masih beroperasi adalah sistem penghancur diri tersembunyi kota ini...",
  ui_story_5083_50830801_33_dialog_content = "Sebagai prajurit, kami siap untuk turun bersama kota, tetapi masih ada begitu banyak warga sipil dan sumber daya di dalam tempat perlindungan...",
  ui_story_5083_50830801_34_dialog_content = "<color=#e8d9bb>Kolonel menatap ke atas ke bagian atas Undercity dalam diam. Kegelapan di atas hanya diterangi oleh nyala api kehancuran yang berkedip-kedip.</color>",
  ui_story_5083_50830801_35_dialog_content = "Anak-anak laki-laki yang menjalankan operasi gerilya kami tidak lebih dari tujuh belas tahun... Mereka tidak pantas mati di sini bersama kami, anjing-anjing tua lainnya.",
  ui_story_5083_50830801_36_dialog_content = "Tempat ini akan segera menjadi sarang Eclipsite... Kota Gannon tidak akan datang untuk menyelamatkan kita, tetapi itu tidak berarti kita bisa membuat masalah lain untuk mereka. Saya yakin kamu mengerti, Pak.",
  ui_story_5083_50830801_37_dialog_content = "... Kita akan menunggu delapan belas menit lagi. Jika mereka benar-benar berhasil menerobos masuk ke tempat perlindungan, kita akan meledakkan seluruh kota. Setidaknya, rakyat kita tidak akan mati di tangan para Eclipsite.",
  ui_story_5083_50830801_38_dialog_content = "Orang-orang di sana pasti ketakutan dengan suara yang datang dari sisi lain pintu itu... Apakah kamu benar-benar bersedia membuat mereka menderita selama delapan belas menit lagi?",
  ui_story_5083_50830801_39_dialog_content = "Tidak, aku memberi mereka delapan belas menit harapan lagi! Aku yakin beberapa dari mereka... Masih berpikir bahwa kita yang akan membuka pintu itu.",
  ui_story_5083_50830801_40_dialog_content = "Betapa kejam... Maaf, Tuan, tapi saya tidak bisa menerima itu. Sebagai penjaga garis depan Kota Gannon, kita ditakdirkan untuk mengorbankan diri kita demi semua Illumina—",
  ui_story_5083_50830801_41_dialog_content = "Saya tidak ingin ada orang yang datang dan menyelamatkan kita jika itu berarti membahayakan diri mereka sendiri... Tapi... Apakah salah untuk percaya...",
  ui_story_5083_50830801_42_dialog_content = "Bahwa cahaya harapan dapat tetap menyala di kota kita?",
  ui_story_5083_50830801_43_dialog_content = "Apakah ada yang mendengar? Saya ulangi, apakah ada yang mendengar?",
  ui_story_5083_50830801_44_dialog_content = "Nama saya adalah Letnan Dua Wrath, dan saya di sini dengan tim bala bantuan dari Gannon City. Kami berhasil menyusup ke level atas Undercity 13 dan memulihkan komunikasi. Apakah ada yang selamat di sana?",
  ui_story_5083_50830801_45_dialog_content = "…!",
  ui_story_5083_50830801_46_dialog_content = "Tidak, jangan jawab dia! Kota ini dipenuhi oleh Eclipsites; mereka tidak akan pernah bisa keluar jika mereka turun ke sini!",
  ui_story_5083_50830801_47_dialog_content = "Saya lebih tahu daripada siapa pun bahwa kota ini sudah tak bisa diselamatkan lagi! Tak lama lagi, Menara Pusat akan runtuh, dimulai dari stasiun tenaga; tak satu pun dari kita yang memiliki harapan untuk melarikan diri!",
  ui_story_5083_50830801_48_dialog_content = "Jangan biarkan mereka turun ke sini! Aktifkan urutan penghancuran diri sebelum tempat ini jatuh ke dalam kegelapan! Itu satu-satunya cara kita memiliki harapan untuk membangun kembali—",
  ui_story_5083_50830801_49_dialog_content = "Aku bisa mendengar suara tembakan; kamu masih bertarung di sana, yang berarti pasti ada yang selamat di suatu tempat. Apakah mereka di tempat perlindungan? Kenapa kamu tidak merespon?",
  ui_story_5083_50830801_50_dialog_content = "Bisakah jadi... Kamu khawatir tentang kami yang akan turun ke sana?",
  ui_story_5083_50830801_51_dialog_content = "Masih tidak ada respon, huh? Sekumpulan orang tua yang keras kepala... Sepertinya kita harus memberi mereka sinyal.",
  ui_story_5083_50830801_52_dialog_content = "Reinhardt memintaku untuk menemanimu agar kamu tidak melakukan sesuatu yang sembrono—Kamu sadar bahwa satu langkah salah akan mendatangkan seluruh kota Eclipsite menyerbu kita, kan?",
  ui_story_5083_50830801_53_dialog_content = "Jika keadilan tetap diam, kegelapan tak akan pernah bisa diusir.",
  ui_story_5083_50830801_54_dialog_content = "Tidakkah kamu bisa merasakan putus asa mereka? Ini persis apa yang akan dilakukan Reinhardt jika dia ada di sini!",
  ui_story_5083_50830801_55_dialog_content = "<color=#e8d9bb>Undercity 13 sudah tak terselamatkan—Tak ada yang meragukan bahwa ini adalah misi yang tak berharapan.</color>",
  ui_story_5083_50830801_56_dialog_content = "<color=#e8d9bb>Tapi dalam kegelapan dan putus asa, tiba-tiba muncul sebuah mercusuar: sebuah kilat dari Kota Gannon yang merobek setiap ketakutan dan keraguan.</color>",
  ui_story_5083_50830801_57_dialog_content = "<color=#e8d9bb>Wrath menggosok-gosokkan sarung tangannya dengan kuat untuk menghasilkan ledakan cahaya dan suara yang kuat, menarik perhatian setiap Eclipsite ke arahnya.</color>",
  ui_story_5083_50830801_58_dialog_content = "Siapa bilang kota ini tidak bisa diselamatkan?! Kita adalah sinar harapan terakhir mereka! Keselamatan terakhir mereka!",
  ui_story_5083_50830801_59_dialog_content = "Sekarang dengarkan! Tim saya dan saya menuju langsung ke lantai bawah, dan kami akan menghabisi segalanya di jalan kami! Siapkan setiap warga sipil untuk dievakuasi sebelum itu!",
  ui_story_5083_50830801_60_dialog_content = "... Siapa sebenarnya kamu? Kenapa kamu sampai sejauh ini untuk kami? Tidak mungkin Grand Marshal menyetujui ini!",
  ui_story_5083_50830801_61_dialog_content = "Sudah kubilang, nama saya adalah Wrath—Calon Grand Marshal dari Illumina! Aku tidak akan membiarkan siapa pun menghentikan aku menjalankan keadilan versiku!",
  ui_story_5083_50830801_62_dialog_content = "<color=#e8d9bb>Wrath memimpin serangan terhadap Eclipsite yang melonjak di sepanjang tangga, pedangnya yang berdansa memotong jalur berdarah melalui barisan mereka. Akhirnya, dia mencapai lantai bawah Undercity.</color>",
  ui_story_5083_50830801_63_dialog_content = "Apakah kalian semua melihat itu? Prajurit itu adalah masa depan Illumina... Buah dari dedikasi dan latihan kita...",
  ui_story_5083_50830801_64_dialog_content = "Dia adalah \"Phospherus\" yang selama ini kita impikan... Cahayanya... Benar-benar mempesona...",
  ui_story_5083_50830801_65_dialog_content = "Impian kita kini berdiri bersinar di depan kita... Bagaimana kita bisa membiarkannya padam?",
  ui_story_5083_50830801_66_dialog_content = "... Aku akan memastikan jalur evakuasi tempat perlindungan dibersihkan dalam sepuluh menit ke depan, meskipun itu berarti mengorbankan hidupku.",
  ui_story_5083_50830801_67_dialog_content = "Dan aku akan memimpin tim untuk bertemu dengannya. Sisanya terserah padamu.",
  ui_story_5083_50830801_68_dialog_content = "<color=#FFB400>Cahaya Phospherus</color>... Tidak peduli apa yang terjadi, aku harus membiarkan setiap orang melihatnya—",
  ui_story_5083_50830801_69_dialog_content = "<color=#e8d9bb>Di pinggiran Undercity, api perang berkobar selama tiga hari berturut-turut tanpa tanda-tanda bala bantuan yang terlihat.</color>",
  ui_story_5083_50830801_70_dialog_content = "<color=#e8d9bb>Dengan habisnya suplai amunisi sekali lagi, para prajurit kembali mengandalkan pertempuran jarak dekat.</color>",
  ui_story_5083_50830801_71_dialog_content = "Tahan barisan! Kita harus mempertahankan posisi ini, atau mereka akan memblokir pintu masuk!",
  ui_story_5083_50830801_72_dialog_content = "Mengaum-!",
  ui_story_5083_50830801_73_dialog_content = "Tidak di jam tangan saya!",
  ui_story_5083_50830801_74_dialog_content = "Heh, pria tua... maksudku, Komandan Pango benar! Dapat secara insting beralih ke senjata jarak dekat melawan banyak Eclipsite adalah cara terbaik.",
  ui_story_5083_50830801_75_dialog_content = "Apa kamu sedang memiliki momen pencerahan di sana, Barton?",
  ui_story_5083_50830801_76_dialog_content = "Tidak benar-benar; commander lama telah menanamkan refleks tertentu pada saya, dan saya baru saja melihatnya beraksi untuk pertama kalinya. Heh, saya mulai merasa nyaman dalam jenis pertempuran seperti ini.",
  ui_story_5083_50830801_77_dialog_content = "Kami tidak akan bisa bertahan di posisi ini lebih lama lagi. Saya sarankan kamu membawa tim dan mencoba membuat jalur pelarian melalui musuh. Ini adalah kesempatan terbaik kita untuk membawa orang-orang ini kembali ke Gannon City.",
  ui_story_5083_50830801_78_dialog_content = "Bagaimana denganmu? Jangan bilang kamu akan tinggal di sini?",
  ui_story_5083_50830801_79_dialog_content = "Aku memberi tahu mereka bahwa aku akan berjuang bersama mereka hingga akhir... Jika kita tidak bisa mempertahankan Undercity, kita akan meledakkannya dan memastikan para Eclipsite tidak bisa menggunakannya dengan cara apa pun.",
  ui_story_5083_50830801_80_dialog_content = "Itu tidak mungkin terjadi, Reinhardt! Komandan Pango telah berjanji bahwa dia akan datang, dan dia tidak pernah mengingkari janjinya!",
  ui_story_5083_50830801_81_dialog_content = "... Kami tidak memiliki cara untuk berkomunikasi dengan siapa pun di luar kota, dan tidak ada satupun utusan kami yang kembali. Apakah kamu benar-benar sangat mempercayainya, Barton?",
  ui_story_5083_50830801_82_dialog_content = "Dia mungkin bajingan, tapi pria tua itu tidak pernah berbohong padaku sebelumnya... Jadi tentu saja aku percaya! Aku mempercayainya seperti aku mempercayai kamu untuk melindungi punggungku!",
  ui_story_5083_50830801_83_dialog_content = "Maka saya juga tidak punya alasan untuk meragukannya!",
  ui_story_5083_50830801_84_dialog_content = "Hmph. Demi Illumina dan semua kawan-kawan kami yang telah gugur... Saya menolak untuk menyerah kepada Eclipsite ini atau melarikan diri dalam aib.",
  ui_story_5083_50830801_85_dialog_content = "Maka kita akan berdiri bahu-membahu dan bertarung hingga saat semua harapan hilang!",
  ui_story_5083_50830801_86_dialog_content = "Sebuah Eclipsite besar sedang mendekat, Reinhardt! A-Aku rasa itu mungkin pemimpin mereka!",
  ui_story_5083_50830801_87_dialog_content = "Prajurit Illumina yang lemah—Berlututlah di hadapanku, Duskcaller yang tak terhentikan!",
  ui_story_5083_50830801_88_dialog_content = "Sebuah Eclipsite yang mampu berbicara? Kamu tidak melihat itu setiap hari... Maaf teman, tapi kakiku tidak benar-benar berlutut. Jika itu menjadi masalah, kamu bisa menghadapinya dengan pedangku.",
  ui_story_5083_50830801_89_dialog_content = "Kami bukan tipe yang menyerah, jadi simpan saja. Aku akan membiarkan Tombak Penembus Bintangku menunjukkan cahaya sejati Illumina padamu!",
  ui_story_5083_50830801_90_dialog_content = "Saya telah melihat Ibu memburu bintang-bintang di langit malam, tertarik oleh kehendak mereka yang tak bisa ditolak.",
  ui_story_5083_50830801_91_dialog_content = "Kamu, Aurorian yang menyedihkan, hanya bertahan hidup dalam kegelapan jurang, dan masih berani bertindak dengan begitu semena-mena.",
  ui_story_5083_50830801_92_dialog_content = "Cahaya akan segera memudar dari tempat ini... Dan Kota Gannon akan berbagi nasib serupa. \"Cahaya sejati dari Illumina\" hanyalah sebuah sandiwara...",
  ui_story_5083_50830801_93_dialog_content = "Hei Reinhardt, sepertinya kita punya seorang penyair di tangan kita.",
  ui_story_5083_50830801_94_dialog_content = "Tidak peduli seberapa paham kebudayaan yang kamu pikir kamu miliki... Kamu tidak akan pernah mengerti, monster.",
  ui_story_5083_50830801_95_dialog_content = "Suatu hari, kita akan keluar dari parit-parit ini dan kembali ke Astra yang damai—Itu akan menjadi awal baru kita, dan kesempatan kita untuk mengikuti cahaya baru.",
  ui_story_5083_50830801_96_dialog_content = "Illumina adalah fajar yang menembus malam dan mengumumkan cahaya siang! Iman kita menyatukan kita, dan oleh iman kita kamu akan dihentikan!",
  ui_story_5083_50830801_97_dialog_content = "Kami semua adalah bara... Percikan kejayaan Illumina! Kamu tidak akan pernah bisa memadamkan cahaya kami!",
  ui_story_5083_50830801_98_dialog_content = "Tidak bisa mengatakannya lebih baik! Tak peduli berapa banyak Eclipsite yang kamu lemparkan kepada kami, kamu tidak akan pernah bisa mematahkan semangat kami!",
  ui_story_5083_50830801_99_dialog_content = "Aku akan membuat kalian membayar mahal atas kesombonganmu, orang lemah—Serang!",
  ui_story_5083_50830801_100_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5083_50830801_101_dialog_content = "<color=#e8d9bb>Sebuah peluru artileri tiba-tiba mengenai Eclipsite dan meledak, membuatnya terhuyung-huyung.</color>",
  ui_story_5083_50830801_102_dialog_content = "<color=#e8d9bb>Terompet berbunyi saat sistem siaran darurat Undercity 19 mulai berdering, menandakan kedatangan bala bantuan yang telah lama ditunggu.</color>",
  ui_story_5083_50830801_103_dialog_content = "<color=#e8d9bb>Prajurit-prajurit itu memalingkan wajah mereka yang penuh dengan darah ke cakrawala. Dibasahi cahaya, seluruh legiun muncul dan mulai bergerak menyerang musuh.</color>",
  ui_story_5083_50830801_104_dialog_content = "<color=#e8d9bb>Bendera Legiun Kedua terbang di atas kepala mereka—Sebuah simbol kekuatan fajar.</color>",
  ui_story_5083_50830801_105_dialog_content = "Kebodohan seperti ini... Beraninya kalian menyerangku, Aurorian bodoh! Kalian akan membayar dengan darah kalian—",
  ui_story_5083_50830801_106_dialog_content = "Sekarang kesempatan kita, Reinhardt! Menyerang!",
  ui_story_5083_50830802_1_dialog_content = "Phospherus... Tidak! Semua dari kalian harus mati di sini! Astra ditakdirkan untuk penderitaan tanpa akhir... Malam abadi tidak akan bisa dihentikan!",
  ui_story_5083_50830802_2_dialog_content = "Maaf, tetapi mengatasi kejahatan juga merupakan takdir setiap pahlawan dalam cerita seperti ini.",
  ui_story_5083_50830802_3_dialog_content = "Apakah saya telah gagal? Tidak! Ini tidak mungkin—",
  ui_story_5083_50830802_4_dialog_content = "Tidak ada jalan keluar dari kehancuranmu... Lonceng telah mulai berdentang... Saat kematianmu<color=#FFB400>telah</color> tiba...",
  ui_story_5083_50830802_5_dialog_content = "Kakakku... Harus melanjutkan pekerjaan muliaku... Ack! <color=#FFB400>Ibu</color>...",
  ui_story_5083_50830802_6_dialog_content = "Apa yang dia bicarakan? Sepertinya masih ada musuh kuat lainnya yang menunggu kita di luar sana...",
  ui_story_5083_50830802_7_dialog_content = "Aku tidak sepenuhnya yakin... Tapi, kita berhasil bertahan, dan itu yang paling penting.",
  ui_story_5083_50830802_8_dialog_content = "Divisi Ketiga, mulailah bekerja untuk menyelamatkan stasiun listrik! Pulihkan komunikasi dan kirim pesan kembali ke Kota Gannon... Tidak, ke setiap Undercity di Federasi!",
  ui_story_5083_50830802_9_dialog_content = "Beritahu mereka bahwa kota ini masih bisa diselamatkan, dan jangan menyerah pada kota ini!",
  ui_story_5083_50830802_10_dialog_content = "Pak, kami baru saja menerima pengiriman darurat dari Undercity 13! Tolong dengarkan!",
  ui_story_5083_50830802_11_dialog_content = "... Comms Officer ku mengatakan bahwa Undercity 19 sekarang aman. Apakah itu ulahmu, Pango?",
  ui_story_5083_50830802_12_dialog_content = "Maaf, teman lama... Aku tidak mampu menyelamatkanmu sendiri.",
  ui_story_5083_50830802_13_dialog_content = "Heh, simpan saja permintaan maafmu. Ini adalah pilihan terbaik, bukan? Jaga baik-baik tempat itu, dan pastikan kita tidak kehilangannya lagi.",
  ui_story_5083_50830802_14_dialog_content = "Perwira muda yang luar biasa itu... Wrath, jika saya tidak salah? Dia sedang memimpin setiap orang keluar dari tempat perlindungan saat kita berbicara.",
  ui_story_5083_50830802_15_dialog_content = "Apa?! Komandan Pango, biarkan saya membawa tim ke sana untuk membantunya!",
  ui_story_5083_50830802_16_dialog_content = "Dia benar! Saya pikir masih ada harapan untuk menyelamatkan Undercity 13—",
  ui_story_5083_50830802_17_dialog_content = "Tutup mulut, kalian berdua! Biarkan pria itu selesai berbicara!",
  ui_story_5083_50830802_18_dialog_content = "Kami telah bertarung tanpa henti selama lima belas hari terakhir... Selain saya, semua perwira kami sudah gugur.",
  ui_story_5083_50830802_19_dialog_content = "Tapi mendengar bahwa Undercity 19 aman membuat hatiku tenang.",
  ui_story_5083_50830802_20_dialog_content = "Kamu tidak mengevakuasi, bukan?",
  ui_story_5083_50830802_21_dialog_content = "Undercity 13 berada di ambang kehancuran, dan seseorang perlu mengaktifkan urutan penghancuran diri... Jika jalan ke Gannon City diblokir, kehancuran juga akan dicegah.",
  ui_story_5083_50830802_22_dialog_content = "Ada kemungkinan kota ini akan dibangun kembali suatu hari nanti... Jadi aku akan tetap di sini dan menunggu sampai hari itu tiba... Namun...",
  ui_story_5083_50830802_23_dialog_content = "... Beberapa prajuritmu menolak untuk pergi, benar?",
  ui_story_5083_50830802_24_dialog_content = "Heh, benar sekali. Bagaimanapun, aku telah melatih setiap orang dari mereka menjadi tentara yang hebat seperti yang mereka miliki hari ini.",
  ui_story_5083_50830802_25_dialog_content = "Saya mengerti... Saya masih memiliki banyak pertempuran yang harus dilakukan di pihak saya, jadi saya meminta prajurit Anda untuk bergabung dengan saya di sini.",
  ui_story_5083_50830802_26_dialog_content = "Itu perintah.",
  ui_story_5083_50830802_27_dialog_content = "Mengerti... Mereka ada di tanganmu sekarang, Pango. Janjikanlah kamu akan merawat mereka dengan baik.",
  ui_story_5083_50830802_28_dialog_content = "Aku berjanji... Teman lama.",
  ui_story_5083_50830802_29_dialog_content = "Ini adalah perpisahan, Pango... Ingatlah untuk menjauh dari kota ini.",
  ui_story_5083_50830802_30_dialog_content = "Saya akan memberi mereka perintah untuk evakuasi sebentar lagi... Jayalah Illumina!",
  ui_story_5083_50830802_31_dialog_content = "Saya hormati kamu, kawan... Jayalah Illumina!",
  ui_story_5083_50830802_32_dialog_content = "Apa yang sedang kamu lakukan, Komandan Pango?! Masih ada orang di Undercity 13, yang berarti masih ada harapan untuk mereka! Kenapa kamu malah mencabut prajuritnya darinya—",
  ui_story_5083_50830802_33_dialog_content = "Hematlah tenagamu dan pergilah beristirahat! Dari ekspresi wajahmu, sepertinya kamu tidak berpikir dengan jernih.",
  ui_story_5083_50830802_34_dialog_content = "Namun…",
  ui_story_5083_50830802_35_dialog_content = "Saya memberimu perintah, Barton! Ingat posisimu, soldier!",
  ui_story_5083_50830802_36_dialog_content = "... Cih!",
  ui_story_5083_50830802_37_dialog_content = "Kamu ingin menyelamatkan sebanyak mungkin dari mereka, 'kan?",
  ui_story_5083_50830802_38_dialog_content = "... Yang kami inginkan hanyalah membangun Illumina. Tapi setelah bertahun-tahun berperang, mata tua kami akhirnya mulai sedikit kabur.",
  ui_story_5083_50830802_39_dialog_content = "Prajurit muda seperti kamu adalah satu-satunya yang bisa menembus cahaya fajar. Mata kamu lebih tajam, dan begitu juga pikiranmu...",
  ui_story_5083_50830802_40_dialog_content = "Heh, Grand Marshal dan saya tidak jauh lebih tua dari kamu saat kami bertempur dalam Perang Zona Gelap.",
  ui_story_5083_50830802_41_dialog_content = "Aku tidak yakin kapan ini dimulai... Tapi entah bagaimana, kita akhirnya menjadi seperti orang-orang yang kita benci saat itu.",
  ui_story_5083_50830802_42_dialog_content = "... Jayalah Illumina! Saya hormat Anda, pak.",
  ui_story_5083_50830802_43_dialog_content = "Ah, pergilah beristirahat. Aku butuh waktu sendiri... Untuk melepas teman lamaku.",
  ui_story_5083_50830802_44_dialog_content = "Bip—Barton... Sensor saya menunjukkan bahwa semangatmu sedang rendah. Tolong ikut denganku...",
  ui_story_5083_50830802_45_dialog_content = "?!",
  ui_story_5083_50830802_46_dialog_content = "Masih hidup, huh? Kamu tidak terlihat seperti itu meskipun.",
  ui_story_5083_50830802_47_dialog_content = "Jangan terkejut! Utusanmu berhasil mencapai Kota Gannon, dan Grand Marshal segera mengirim bala bantuan begitu dia mendengar bahwa Undercity 19 telah diamankan.",
  ui_story_5083_50830802_48_dialog_content = "Kami hanya di sini atas perintah kami.",
  ui_story_5083_50830802_49_dialog_content = "... Apakah kamu baik-baik saja?",
  ui_story_5083_50830802_50_dialog_content = "Kamu... Dasar bodoh! Bisakah kamu datang ke sini lebih lambat lagi?!",
  ui_story_5083_50830802_51_dialog_content = "Apakah kamu tahu berapa banyak orang yang kita kehilangan?! Sialan!",
  ui_story_5083_50830802_52_dialog_content = "Itu saja yang harus kamu katakan padaku?! Jika saya tidak menembak Eclipsite besar itu sebelumnya, kamu pasti sudah selesai—Idiot!",
  ui_story_5083_50830802_53_dialog_content = "Aduh—!!!",
  ui_story_5083_50830802_54_dialog_content = "... Jadi mengapa kamu begitu sedih, Barton? Apakah karena... Komandan Barton bersedia membiarkan temannya pergi seperti itu?",
  ui_story_5083_50830802_55_dialog_content = "Undercity 13 masih bisa diselamatkan... Mereka bisa saja di sini sekarang, membantu kita mempertahankan tempat ini... Tapi sebaliknya, mereka malah akan meledakkan tempat ini.",
  ui_story_5083_50830802_56_dialog_content = "Pria tua itu bahkan berani mengambil prajurit paling setia dari temannya... Dan meninggalkannya di sana untuk mati sendirian...",
  ui_story_5083_50830802_57_dialog_content = "Apakah Anda lebih suka mereka mati di sisinya?",
  ui_story_5083_50830802_58_dialog_content = "Saya yakin kamu tahu persis bagaimana perasaan mereka... Jika kita berada di posisi yang sama, tidak ada yang bisa menjauhkan kita dari Commander Pango.",
  ui_story_5083_50830802_59_dialog_content = "Mereka harus mematahkan kaki kita dan mengunci kita di mobil pelarian untuk membuat kita pergi.",
  ui_story_5083_50830802_60_dialog_content = "...",
  ui_story_5083_50830802_61_dialog_content = "Tapi jika Komandan Pango setuju dengan temannya, berarti memang tidak ada harapan lagi untuk menyelamatkan Undercity 13.",
  ui_story_5083_50830802_62_dialog_content = "Tidak ada alasan bagi begitu banyak orang untuk kehilangan nyawa mereka dalam ledakan... Dengan memberi mereka misi baru, dia juga memberi mereka alasan baru untuk bertahan hidup.",
  ui_story_5083_50830802_63_dialog_content = "Itu selalu menjadi salah satu prinsip panduan Illumina.",
  ui_story_5083_50830802_64_dialog_content = "Tidak ada yang berbohong atau membelakangi satu sama lain, Barton; Undercity 19 akan terus berjuang. Pikirkan itu sebagai... Sebuah kesepakatan tak terucap antara dua officer tua.",
  ui_story_5083_50830802_65_dialog_content = "Jadi, ketika mereka mengemukakan sesuatu yang seabsurd \"misi baru,\" itu hanya cara mereka melindungi tentara yang mereka latih dengan sepenuh hati.",
  ui_story_5083_50830802_66_dialog_content = "Jadi, kenapa tidak bertanya pada mereka apa yang mereka pikirkan?! Saya yakin tidak ada satupun dari mereka yang ingin mendengar komandan mereka sendiri berbicara tentang pengorbanan dirinya...",
  ui_story_5083_50830802_67_dialog_content = "Ini karena mereka adalah anak-anaknya, Barton. Mereka semua adalah anak-anak dari Illumina.",
  ui_story_5083_50830802_68_dialog_content = "Itulah sebabnya dia bersedia pergi sejauh itu untuk mereka...",
  ui_story_5083_50830900_1_dialog_content = "<color=#e8d9bb>Setelah beberapa hari bertempur tanpa henti, Eclipsite akhirnya mulai mundur dari dataran, memperlihatkan bekas luka tak terhitung jumlahnya yang tertinggal di medan perang.</color>",
  ui_story_5083_50830900_2_dialog_content = "<color=#e8d9bb>Undercity 19 telah diselamatkan, tetapi Legiun Kedua telah kehilangan lebih dari setengah pasukannya.</color>",
  ui_story_5083_50830900_3_dialog_content = "<color=#e8d9bb>Barton berbaring di tanah di samping kawan-kawannya yang jatuh, menatap kosong ke arah matahari yang tampaknya tanpa panas.</color>",
  ui_story_5083_50830900_4_dialog_content = "Bangun. Sudah saatnya bagi kita untuk pergi.",
  ui_story_5083_50830900_5_dialog_content = "Komandan Pango?",
  ui_story_5083_50830900_6_dialog_content = "Saya ingin melakukan itu... Tapi, tentara yang kita foto bersama masih terbaring di sini, dan mereka tidak akan pernah bangun.",
  ui_story_5083_50830900_7_dialog_content = "Aku datang ke sini untuk menyelamatkan orang-orang. Aku tidak menyangka begitu banyak rekan-rekanku yang gugur di bawah komandoku...",
  ui_story_5083_50830900_8_dialog_content = "... Di sini.",
  ui_story_5083_50830900_9_dialog_content = "Berat, bukan? Ingatlah mereka, Barton; ingat nama-nama mereka dan masa lalu mereka.",
  ui_story_5083_50830900_10_dialog_content = "Sebagai penyintas dari pertempuran ini, tugas kita adalah untuk melanjutkan.",
  ui_story_5083_50830900_11_dialog_content = "Sialan punk, tampaknya pertarungan ini benar-benar membuatmu kehilangan akal. Tapi kamu masih harus terus berjuang, bahkan jika itu hanya untuk memastikan nama mereka terukir di monumen itu!",
  ui_story_5083_50830900_12_dialog_content = "Kamu pikir aku tidak tahu itu?! Hanya saja...",
  ui_story_5083_50830900_13_dialog_content = "Tidak ada alasan, Barton! Kita memiliki kewajiban untuk memastikan pengorbanan mereka tidak sia-sia! Ataukah tindakan mereka benar-benar berarti sedikit bagi kamu?!",
  ui_story_5083_50830900_14_dialog_content = "... Bagus. Sekarang bahwa Undercity 19 telah diselamatkan, pertempuran ini akan menjadi sebuah pesan.",
  ui_story_5083_50830900_15_dialog_content = "Ini adalah pesan untuk semua Undercity, termasuk mereka yang masih berjuang di garis depan.",
  ui_story_5083_50830900_16_dialog_content = "Mendengar tentang kemenangan kita hari ini akan memperkuat kepercayaan setiap orang... Jika Undercity 19 bisa diselamatkan, maka Undercity lainnya di Illumina juga bisa.",
  ui_story_5083_50830900_17_dialog_content = "Suatu hari nanti, Astra akan bebas dari kerusakan perang ini.",
  ui_story_5083_50830900_18_dialog_content = "Tapi, itu adalah pembicaraan untuk lain waktu. Setidaknya, kita berhasil menjaga api harapan tetap hidup, dan itu pasti berarti sesuatu.",
  ui_story_5083_50830900_19_dialog_content = "Meskipun itu berarti terus-menerus mengorbankan jiwa kita untuk mempertahankan apinya, semuanya akan sepadan pada akhirnya—",
  ui_story_5083_50830900_20_dialog_content = "Hmph—Saya tidak berniat membuat banyak pengorbanan begitu saya memimpin kapal ini.",
  ui_story_5083_50830900_21_dialog_content = "Jika ada yang harus terbakar demi harapan, maka itu akan aku. Jika hari itu tiba, api akan membakar lebih panas dari sebelumnya...",
  ui_story_5083_50830900_22_dialog_content = "<color=#e8d9bb>Pesan tentang penyelamatan Undercity 19 menyebar di seluruh Illumina seperti api yang merambat cepat. Sebelum para prajurit bahkan kembali ke rumah, Kota Gannon sudah dipenuhi dengan berita tentang kemenangan mereka.</color>",
  ui_story_5083_50830900_23_dialog_content = "<color=#e8d9bb>Menurut laporan resmi, Barton dan yang lainnya dijuluki sebagai pahlawan elit yang dikerahkan oleh Grand Marshal sendiri.</color>",
  ui_story_5083_50830900_24_dialog_content = "<color=#e8d9bb>Mengingat prestasi luar biasa mereka, setiap tuduhan pidana yang sebelumnya ditujukan kepada mereka secara singkat dihapuskan—</color>",
  ui_story_5083_50830900_25_dialog_content = "Apa itu ajaran Illumina, Pango? Beritahu aku sekarang juga!",
  ui_story_5083_50830900_26_dialog_content = "\"Satu untuk semua, dan semua untuk satu.\"",
  ui_story_5083_50830900_27_dialog_content = "Jangan lupa sisanya! \"Demi Illumina, semua perintah harus diikuti!\"",
  ui_story_5083_50830900_28_dialog_content = "Kamu beroperasi dengan mengabaikan perintah sepenuhnya, dan kamu mengajari bawahanmu untuk melakukan hal yang sama!",
  ui_story_5083_50830900_29_dialog_content = "Jika bukan karena penyelamatan Undercity 19, mungkin keadaan tidak akan berakhir hampir sebaik ini untukmu atau prajuritmu!",
  ui_story_5083_50830900_30_dialog_content = "Bawahan Anda kehilangan nyawa mereka karena keangkuhan Anda!",
  ui_story_5083_50830900_31_dialog_content = "Kami sama sekali tidak merasa beruntung, Grand Marshal! Kami telah mengorbankan begitu banyak demi—",
  ui_story_5083_50830900_32_dialog_content = "Kesunyian!",
  ui_story_5083_50830900_33_dialog_content = "N-Namamu adalah Barton, kan? Kamu pikir hanya karena kamu seorang pahlawan maka kamu bisa bicara sembarangan?!",
  ui_story_5083_50830900_34_dialog_content = "Dia tidak bermaksud apa-apa, Grand Marshal! Rekan kerja saya di sini hanya seorang bodoh!",
  ui_story_5083_50830900_35_dialog_content = "... Dan kamu! Apakah kamu tahu berapa banyak masalah yang kamu timbulkan dengan mengikuti contoh mereka—",
  ui_story_5083_50830900_36_dialog_content = "Maaf mengganggu, Grand Marshal.",
  ui_story_5083_50830900_37_dialog_content = "Sekretaris Komite? Siapa yang membiarkanmu masuk ke sini?!",
  ui_story_5083_50830900_38_dialog_content = "Saya hanya di sini untuk menyampaikan pesan mendesak dari Komite, pak.",
  ui_story_5083_50830900_39_dialog_content = "Dengan suksesnya operasi penyelamatan dan publisitas seputar para pahlawannya, moral dalam Illumina berada pada titik tertinggi sepanjang masa. Komite sangat puas dengan tindakan yang diambil oleh para prajurit berani ini.",
  ui_story_5083_50830900_40_dialog_content = "Senang? Dengan mereka?! Hah!",
  ui_story_5083_50830900_41_dialog_content = "Yang patut mendapat pujian adalah Letnan Reinhardt... Serta Kapten Barton. Committee percaya bahwa kedua prajurit ini harus dijadikan sebagai panutan untuk seluruh Federasi.",
  ui_story_5083_50830900_42_dialog_content = "Kami masih berperang di sini. Ini bukan saatnya bermain-main!",
  ui_story_5083_50830900_43_dialog_content = "Justru KARENA kita sedang berperang, Komite melihat kebutuhan akan tentara yang luar biasa seperti itu untuk meningkatkan sentimen publik.",
  ui_story_5083_50830900_44_dialog_content = "... Mau ke mana sebenarnya kalian ini?",
  ui_story_5083_50830900_45_dialog_content = "Kenapa tidak mempromosikan wakil komandanku, lalu? Dia mungkin seorang idiot, tetapi dia cukup terampil untuk mengambil alih seluruh Divisi Infanteri Mekanis.",
  ui_story_5083_50830900_46_dialog_content = "Itu harus cukup mudah untuk diatur, Pak. Untuk kamu, Letnan Reinhardt, kami masih membahas tentang hadiah yang mungkin untukmu. Maukah kamu menemani saya? Sekarang juga, tolong.",
  ui_story_5083_50830900_47_dialog_content = "Memimpin.",
  ui_story_5083_50830900_48_dialog_content = "Jika tidak ada yang lain, Grand Marshal, maka kami juga akan pergi.",
  ui_story_5083_50830900_49_dialog_content = "... Kau diberhentikan.",
  ui_story_5083_50830900_50_dialog_content = "Tunggu sebentar! Dogg, Komandan Pango... Apakah ada yang aneh tentang pertemuan tadi?",
  ui_story_5083_50830900_51_dialog_content = "Anggota Komite itu hampir tidak memperhatikan Grand Marshal. Dia bahkan lebih kasar kepadanya daripada aku...",
  ui_story_5083_50830900_52_dialog_content = "Katakan sesuatu, maukah kamu? Aku tidak bisa menjadi satu-satunya yang merasa ini aneh! Mereka bahkan tidak repot-repot berkonsultasi dengan Grand Marshal tentang promosiku!",
  ui_story_5083_50830900_53_dialog_content = "...",
  ui_story_5083_50830900_54_dialog_content = "Itu bukan urusanmu, anak laki-laki.",
  ui_story_5083_50830900_55_dialog_content = "Aku tahu Committee memiliki banyak kekuasaan atas kita, tapi—",
  ui_story_5083_50830900_56_dialog_content = "Aku sudah bilang itu bukan urusanmu! Tak ada gunanya mencoba memahami orang-orang itu, Barton... Atau membicarakan mereka, sekalipun.",
  ui_story_5083_50830900_57_dialog_content = "Terima saja promosimu dan kerja keraslah untuk melatih rekrutan baru untuk 2nd Legion—",
  ui_story_5083_50830900_58_dialog_content = "Dan jangan biarkan aku pernah menangkapmu bermalas-malasan.",
  ui_story_5083_50831000_1_dialog_content = "Hei, Reinhardt! Punya waktu untuk bicara?",
  ui_story_5083_50831000_2_dialog_content = "Kamu dari Legiun ke-2, bukan? Apa yang membawamu ke sini di saat seperti ini? Jika kamu di sini untuk berkelahi, aku adalah lawan yang lebih baik daripada Reinhardt.",
  ui_story_5083_50831000_3_dialog_content = "Tenanglah Wrath, dia tidak di sini untuk memulai apa pun. Komandan Barton adalah teman saya.",
  ui_story_5083_50831000_4_dialog_content = "... Aku sudah memikirkannya selama beberapa hari sekarang, tapi aku masih tidak bisa memahaminya. Mengapa mereka melakukan ini padamu, Reinhardt? Di atas tidak mempromosikanmu, Komandan Legiunmu sendiri menghukummu karena menyelamatkan Undercity 19!",
  ui_story_5083_50831000_5_dialog_content = "Mari kita bicara di tempat yang pribadi.",
  ui_story_5083_50831000_6_dialog_content = "Aku hanya akan bertanya, Reinhardt: apa hubunganmu dengan Committee?",
  ui_story_5083_50831000_7_dialog_content = "Aku bukan bodoh; siapa pun bisa melihat bahwa kau terhubung dengan mereka dengan cara tertentu, terutama karena mereka tampaknya tidak pernah meninggalkanmu sendirian.",
  ui_story_5083_50831000_8_dialog_content = "Ketika sekretaris itu menerobos masuk ke ruang pertemuan Grand Marshal waktu itu, dia sebenarnya ada di sana untukmu, bukan?",
  ui_story_5083_50831000_9_dialog_content = "Apa yang dia inginkan darimu? Dan kenapa... Kenapa mereka tidak melindungimu?",
  ui_story_5083_50831000_10_dialog_content = "Sebagai temanmu, saya telah mencari kesempatan yang tepat untuk memberitahumu tentang hal-hal ini, Barton.",
  ui_story_5083_50831000_11_dialog_content = "Untuk permulaan, kamu benar-benar tepat: Komite memang memberikan perhatian khusus padaku. Alasannya... Mungkin karena mereka telah memilihku untuk sesuatu.",
  ui_story_5083_50831000_12_dialog_content = "Saya tidak sepenuhnya yakin apa itu... Tapi sepertinya mereka memiliki rencana pelatihan khusus untukku, satu yang akan membuka potensi tempurku sepenuhnya.",
  ui_story_5083_50831000_13_dialog_content = "Mungkin itu alasan mereka memutuskan untuk muncul saat pertemuan itu.",
  ui_story_5083_50831000_14_dialog_content = "Mengenai mengapa mereka tidak menghentikan komandanku dari menghukumku... Saya pikir itu mungkin semacam peringatan.",
  ui_story_5083_50831000_15_dialog_content = "Sebuah peringatan, huh... Apakah ini berarti Dogg benar tentang kamu? Apakah kamu hanya di sini karena ada seseorang di komite yang mendukungmu?",
  ui_story_5083_50831000_16_dialog_content = "Apakah kamu benar-benar orang seperti itu, Reinhardt?",
  ui_story_5083_50831000_17_dialog_content = "Tidak sedikit pun! Jika ada, saya hanyalah pion dalam skema besar-besaran ini.",
  ui_story_5083_50831000_18_dialog_content = "Meskipun Committee melatihku untuk menjadi lebih kuat... Mereka juga sama khawatirnya untuk menjaga agar aku tetap di bawah kendali mereka.",
  ui_story_5083_50831000_19_dialog_content = "Barton... Jika aku menceritakan lebih banyak lagi tentang ceritaku, kamu akan berakhir di \"kapal bajak laut\" ku seperti waktu itu.",
  ui_story_5083_50831000_20_dialog_content = "Apakah kamu baik-baik saja dengan itu?",
  ui_story_5083_50831000_21_dialog_content = "Aku pernah mempercayaimu dengan hidupku sebelumnya, bukan? Kenapa aku harus menolak kali ini?",
  ui_story_5083_50831000_22_dialog_content = "Seiring memanasnya pertempuran, setiap prajurit memiliki potensi untuk menjadi bahan bakar bagi api kemenangan... Ini terutama berlaku untuk orang-orang di Komite.",
  ui_story_5083_50831000_23_dialog_content = "Saya dan kakak saya, serta salah satu teman saya, semua menjadi bagian dari rencana mereka... Dan meskipun mereka mengatakan mereka hanya menguji kita, ada sesuatu yang tidak terasa benar.",
  ui_story_5083_50831000_24_dialog_content = "Tidak sembarang orang bisa bertahan dengan pelatihan khusus mereka, terutama bukan anak-anak... Setelah menjalaninya sendiri, saya tahu betapa brutalnya itu.",
  ui_story_5083_50831000_25_dialog_content = "Setelah melihat segala yang telah saya lihat, saya tidak percaya bahwa Grand Marshal tidak tahu tentang tindakan Committee... Bahkan, saya pikir dia mendukungnya.",
  ui_story_5083_50831000_26_dialog_content = "Saya tidak meragukan keyakinan Grand Marshal terhadap perang, tetapi saya bisa melihat ketakutan dan kelelahan di matanya. Kehendak untuk terus berjuang tidak cukup untuk menjamin masa depan, setidaknya tidak sendiri.",
  ui_story_5083_50831000_27_dialog_content = "... Kamu pernah cerita padaku tentang <color=#FFB400>mimpi kecilmu</color> menjadi Grand Marshal suatu hari nanti.",
  ui_story_5083_50831000_28_dialog_content = "Masih benar. Suatu hari, aku akan menjadi Grand Marshal Illumina yang paling kuat dan tegas!",
  ui_story_5083_50831000_29_dialog_content = "Aku yakin ada yang sudah bilang kepadamu untuk tidak mengajukan pertanyaan tentang Komite, bukan Barton? Tapi kenyataannya, Illumina tidak akan bisa berlayar sampai kita bisa bebas dari mereka.",
  ui_story_5083_50831000_30_dialog_content = "Heh, kamu pikir kapal bajak lautmu ini cukup besar untuk membawa setiap orang di Illumina?",
  ui_story_5083_50831000_31_dialog_content = "Tidak tahukah kamu? Bahkan seekor burung bayi harus membebaskan diri dari telurnya untuk menemukan tempatnya di dunia. Untuk melangkah lebih jauh ke depan, kita perlu membebaskan diri dari belenggu kita.",
  ui_story_5083_50831000_32_dialog_content = "Jika kita benar-benar ingin membebaskan seluruh Astra dan memulai dari awal... Kita harus mulai dengan membebaskan Illumina dari orang-orang yang mengendalikannya dari balik layar.",
  ui_story_5083_50831000_33_dialog_content = "Anda harus serius jika ingin memberontak melawan kekuatan yang berkuasa.",
  ui_story_5083_50831000_34_dialog_content = "Kamu tidak akan mencapai apa pun itu hanya dengan kata-kata saja, Reinhardt. Jadi beritahu saya, bagaimana saya bisa membantu kamu?",
  ui_story_5083_50831000_35_dialog_content = "Dengan bergabung dengan saya dan membantu saya memberantas korupsi di Illumina.",
  ui_story_5083_50831000_36_dialog_content = "Saat ini, para prajurit Illumina terikat oleh berbagai macam belenggu. Tidak yakin akan makna di balik pengorbanan mereka, mereka hanya hidup dan bertarung, mengetahui bahwa mereka mungkin harus mati untuk kita suatu hari nanti.",
  ui_story_5083_50831000_37_dialog_content = "Dan mereka yang menolak untuk bertempur diburu oleh <color=#FFB400>Eksekutor</color>. Apakah ini benar-benar yang terbaik yang bisa diharapkan oleh Illumina?",
  ui_story_5083_50831000_38_dialog_content = "Kita tidak diberi pilihan saat kita datang ke dunia ini, tetapi rakyat kita harus tahu apa yang mereka perjuangkan dan mati untuk itu!",
  ui_story_5083_50831000_39_dialog_content = "Dan itu dimulai dengan kamu, saya, dan setiap orang yang percaya pada masa depan yang lebih baik! Begitu kita mulai menapaki jalan ini, hanya masalah waktu sebelum Illumina menemukan pencerahan sejati.",
  ui_story_5083_50831000_40_dialog_content = "Hanya dengan begitu kita bisa berharap untuk menyelamatkan seluruh Astra, dan begitu kita mulai lagi... Kita bisa mengejar impian yang lebih besar.",
  ui_story_5083_50831000_41_dialog_content = "Jika kamu ingin menghapus korupsi Illumina, kamu harus siap untuk kemungkinan terburuk: perang lainnya.",
  ui_story_5083_50831000_42_dialog_content = "Aku tidak pernah berniat untuk menuruti orang-orang tua yang ragu-ragu itu.",
  ui_story_5083_50831000_43_dialog_content = "Aku akan membiarkan jiwaku menyala jika itu yang diperlukan untuk menghilangkan tipu daya mereka yang busuk. Selama itu menerangi jalan ke depan untuk semua orang Illumina, aku tidak akan menyesal.",
  ui_story_5083_50831000_44_dialog_content = "Hampir pasti aku harus menghadapi mereka sebagai <color=#FFB400>pengkhianat</color>, yang berarti aku butuh setiap sekutu yang bisa kudapatkan!",
  ui_story_5083_50831000_45_dialog_content = "Itulah semangatnya, Reinhardt! Selama kamu tidak pernah kehilangan pandangan terhadap cahaya itu, hidupku akan selalu ada di tanganmu!",
  ui_story_5083_50831000_46_dialog_content = "Baik itu aku atau prajuritku, yakinlah bahwa kami akan mengikuti setiap perintah yang kamu berikan kepada kami.",
  ui_story_5083_50831000_47_dialog_content = "Hanya saja...",
  ui_story_5083_50831000_48_dialog_content = "Hanya apa?",
  ui_story_5083_50831000_49_dialog_content = "Heh... Hahahaha! Hanya saja setelah mendapatkan degradasi begitu banyak, kamu memiliki perjalanan panjang di depanmu jika ingin menjadi Grand Marshal!",
  ui_story_5083_50831000_50_dialog_content = "Jadi sebaiknya kau waspada, atau aku mungkin akan mengalahkanmu terlebih dahulu!",
  ui_story_5083_50831000_51_dialog_content = "Aku akan pastikan untuk memberimu selamat dengan sepenuh hati jika kamu menjadi Grand Marshal terlebih dahulu.",
  ui_story_5083_50831000_52_dialog_content = "Meski saya rasa posisi itu sendiri bukanlah yang penting.",
  ui_story_5083_50831000_53_dialog_content = "Ya, kau benar.",
  ui_story_5083_50831000_54_dialog_content = "Ada satu hal lagi—saya benar-benar tidak ingin menyembunyikan apa pun ini dari Komandan Pango, mengingat dia praktis membesarkan saya.",
  ui_story_5083_50831000_55_dialog_content = "Kita butuh semua teman yang bisa kita dapatkan, 'kan? Lagi pula... Hal terakhir yang aku inginkan adalah menjadikannya musuh.",
  ui_story_5083_50831000_56_dialog_content = "Jangan khawatir, kamu bisa memberitahukan segalanya yang kita bicarakan di sini kepadanya.",
  ui_story_5083_50831000_57_dialog_content = "Kamu mempercayakan hidupmu padaku; hanya adil jika aku melakukan hal yang sama untukmu.",
  ui_story_5083_50831000_58_dialog_content = "Saya percaya pada penilaian Anda, serta orang-orang yang paling Anda percaya.",
  ui_story_5083_50831000_59_dialog_content = "Jadi apa yang kita tunggu? Mengapa tidak mengumpulkan semua orang dan membicarakan semuanya?",
  ui_story_5083_50831000_60_dialog_content = "Saya dengar ruang makan sedang menawarkan makanan baru yang lezat. Mari kita panggil semua orang ke Area Alokasi dan bicara.",
  ui_story_5083_50831000_61_dialog_content = "<size=45>Kedengarannya bagus untuk saya!</size>",
  ui_story_5083_50831100_1_dialog_content = "Saya meminta teman-teman saya untuk menghubungi beberapa orang yang mungkin simpatik terhadap tujuan kita. Akan sangat membantu jika kita bisa mendapatkan Denier untuk bergabung dengan kita juga... Tapi mari kita pergi ke sana untuk saat ini.",
  ui_story_5083_50831100_2_dialog_content = "Mungkin saya harus kembali ke kamp dulu? Dengan begitu, saya bisa membawa Dogg dan pria tua itu juga.",
  ui_story_5083_50831100_3_dialog_content = "Jangan khawatir, teman-teman saya akan menyampaikan pesan kepada Dogg jika mereka melihatnya. Sedangkan untuk Komandan Pango, dia mungkin akan merasa sedikit tidak nyaman di ruangan penuh dengan tentara muda yang berpotensi memberontak.",
  ui_story_5083_50831100_4_dialog_content = "Dan setelah beberapa kali berada di sisi buruknya, aku rasa aku harus lebih siap sebelum mendekatinya tentang hal ini.",
  ui_story_5083_50831100_5_dialog_content = "Ha! Jadi kamu juga takut pada pria tua itu, ya?",
  ui_story_5083_50831100_6_dialog_content = "H-Hanya pelankan suaramu dan ikuti aku!",
  ui_story_5083_50831100_7_dialog_content = "Omong-omong, apakah ada makanan yang ingin kamu makan? Atau mungkin hobi atau minat?",
  ui_story_5083_50831100_8_dialog_content = "Kamu bisa santai sampai semua orang berkumpul. Aku akan mencari kita meja di kafetaria.",
  ui_story_5083_50831100_9_dialog_content = "Tidak. Kenapa aku harus berlarian jika tak ada perang?",
  ui_story_5083_50831100_10_dialog_content = "Lalu, apa yang kamu lakukan di waktu luangmu di pangkalan?",
  ui_story_5083_50831100_11_dialog_content = "Tinggal di barak atau melakukan latihan sendiri.",
  ui_story_5083_50831100_12_dialog_content = "Apa? Itu cukup payah.",
  ui_story_5083_50831100_13_dialog_content = "Tidak, bukan itu! Lagi pula, tidak ada hal lebih penting yang harus kita lakukan untuk sementara ini.",
  ui_story_5083_50831100_14_dialog_content = "Belum lagi keadaan berantakan di mana-mana karena perang yang sedang berlangsung.",
  ui_story_5083_50831100_15_dialog_content = "Setidaknya aku akan pergi bersama teman-teman perempuanku saat cuti, tapi sepertinya kamu lebih suka di rumah seperti Gronru.",
  ui_story_5083_50831100_16_dialog_content = "Itu tidak 100% benar. Aku juga mengikuti tren terbaru.",
  ui_story_5083_50831100_17_dialog_content = "Aku bahkan tahu di mana letak taman bermain rahasia di dekat sini.",
  ui_story_5083_50831100_18_dialog_content = "Baiklah, kamu pergi bersantai sementara aku pergi mengambil meja dan menjemput Helios dan yang lainnya di perjalanan.",
  ui_story_5083_50831100_19_dialog_content = "Oh, ngomong-ngomong, Helios adalah teman masa kecilku. Dia sangat baik, dan kalian pasti akan cocok.",
  ui_story_5083_50831100_20_dialog_content = "Saya tidak tahu harus pergi ke mana, apalagi hangout...",
  ui_story_5083_50831100_21_dialog_content = "Jika saya tahu, saya akan kembali ke basis dan memberi Dogg tahu lebih dulu.",
  ui_story_5083_50831100_22_dialog_content = "Beep—Silakan coba menikmati waktu luang Anda, Barton.",
  ui_story_5083_50831100_23_dialog_content = "Aku bahkan tidak tahu kemana aku pergi, jadi saya rasa \"tempat bermain rahasia\" Gronru adalah satu-satunya pilihan saya.",
  ui_story_5083_50831100_24_dialog_content = "Tapi, apakah seseorang seperti Gronru tertarik dengan hal seperti itu?",
  ui_story_5083_50831100_25_dialog_content = "Dia tipe orang yang akan berkata, \"Wow, masa depan Illumina! Sangat membosankan. Aku pulang untuk bermain game.\"",
  ui_story_5083_50831100_26_dialog_content = "Apa yang kamu lakukan berkelana di luar arcade rahasiaku? Ingin melawan Raja Angkatan Laut lagi?",
  ui_story_5083_50831100_27_dialog_content = "Itu muncul entah dari mana... Hei, kemana perginya droneku? Apakah dia kabur lagi? Seberapa pemalu dia bisa?",
  ui_story_5083_50831100_28_dialog_content = "Ada pesta yang ingin mengundangmu. Reinhardt belum memberitahumu? Kita akan bertemu di kafetaria untuk membahas beberapa hal.",
  ui_story_5083_50831100_29_dialog_content = "Pesta? Aku belum mendengar tentang itu... Kedengarannya menyenangkan dan aku ingin pergi!",
  ui_story_5083_50831100_30_dialog_content = "Hati-hati untuk tidak ditipu lagi. Anda mungkin tidak bisa keluar dari situ.",
  ui_story_5083_50831100_31_dialog_content = "Kita hampir sampai. Ada yang ingin kamu makan?",
  ui_story_5083_50831100_32_dialog_content = "Jelas kamu tidak tahu apa yang lezat atau tidak, Barton.",
  ui_story_5083_50831100_33_dialog_content = "Aku tidak punya waktu untuk memilih-milih. Illumina akan berada dalam masalah besar jika kami para prajurit mulai membenci ransum militer.",
  ui_story_5083_50831100_34_dialog_content = "Kami berusaha meningkatkan kualitas makanan di sini, hanya untuk memanjakan lidah di garis depan.",
  ui_story_5083_50831100_35_dialog_content = "Seperti Ikan Bakar Umbraton yang Dikeringkan dan batangan energi cokelat. Kamu akan tahu saat mencobanya!",
  ui_story_5083_50831100_36_dialog_content = "Enak, tapi kamu baru saja melahapnya, Barton. Apakah kamu masih akan punya ruang untuk nanti?",
  ui_story_5083_50831100_37_dialog_content = "*Nyam, nyam* Nafsu makan saya lebih besar dari biasanya. Itu adalah syarat untuk menjadi seorang prajurit yang baik.",
  ui_story_5083_50831100_38_dialog_content = "Kurasa jika kamu menang lain kali, aku akan mengirimmu untuk mencoba produk baru untukku dan menghemat perjalananku.",
  ui_story_5083_50831100_39_dialog_content = "Hei, apa yang kamu lakukan di sana, Barton?",
  ui_story_5083_50831100_40_dialog_content = "Aku diutus untuk menjemputmu... Ada apa ini? Kamu sedang menjejali dirimu!",
  ui_story_5083_50831100_41_dialog_content = "Abai saja itu dan coba kue kering ceri ini yang telah dikeringkan!",
  ui_story_5083_50831100_42_dialog_content = "Apa? Tidak, terima kasih. Saya rasa saya mungkin akan kenyang hanya dengan satu gigitan.",
  ui_story_5083_50831100_43_dialog_content = "Oh, ayo, coba saja. Ini benar-benar enak.",
  ui_story_5083_50831100_44_dialog_content = "Aku di sini untuk urusan bisnis, jadi ambil itu... Aku tidak bisa percaya kamu tidak memperlakukannya dengan serius!",
  ui_story_5083_50831100_45_dialog_content = "Sebenarnya ini tidak buruk.",
  ui_story_5083_50831100_46_dialog_content = "Berikan saya yang lain.",
  ui_story_5083_50831100_47_dialog_content = "Santai saja atau kamu akan terlalu kenyang nanti! Ayo, mari kita lihat Reinhardt.",
  ui_story_5083_50831100_48_dialog_content = "Apa yang kalian lakukan...?",
  ui_story_5083_50831100_49_dialog_content = "Sesuatu yang menyenangkan! Dan kamu ada di dalamnya. Jangan coba-coba melarikan diri setelah makan.",
  ui_story_5083_50831100_50_dialog_content = "Di sini! Aku menemukan tempat di pojok. Datanglah dengan cepat!",
  ui_story_5083_50831100_51_dialog_content = "Oh, aku belajar banyak hal baru jadi kita akan segera berlatih bertarung.",
  ui_story_5083_50831100_52_dialog_content = "Dengan serius?",
  ui_story_5083_50831100_53_dialog_content = "Halo, namaku Helios. Terima kasih telah membawa Reinhardt pulang dengan selamat.",
  ui_story_5083_50831100_54_dialog_content = "Aku Barton. Ini adalah Dogg. Kau bisa menghilangkan formalitas. Kita kan Illumina.",
  ui_story_5083_50831100_55_dialog_content = "Belum lagi Reinhardt juga cukup membantuku.",
  ui_story_5083_50831100_56_dialog_content = "Kita punya masalah! Denier terjebak dalam kerumunan yang berjuang untuk makanan dan tidak bisa keluar. Aku butuh dua orang untuk datang bersamaku!",
  ui_story_5083_50831100_57_dialog_content = "Ada apa dengan keributan ini?",
  ui_story_5083_50831100_58_dialog_content = "Kamu tidak bercanda tentang tidak memperhatikan makanan, aku lihat. Penawaran baru adalah prioritas untuk garis depan, jadi Gannon hanya mendapatkan kelebihannya.",
  ui_story_5083_50831100_59_dialog_content = "Dikatakan mereka sangat lezat, jadi pertarungan tidak jarang terjadi.",
  ui_story_5083_50831100_60_dialog_content = "Aku harus pergi membantunya!",
  ui_story_5083_50831100_61_dialog_content = "Benarkah, Reinhardt, kamu mengumpulkan semua orang hanya untuk berjuang demi makanan di kafetaria?",
  ui_story_5083_50831100_62_dialog_content = "Ini adalah noda besar pada kehormatan Legion jika kita bahkan tidak bisa mengamankan makanan! Setiap orang, ikuti saya ke medan perang! Kecuali untuk Reinhardt.",
  ui_story_5083_50831100_63_dialog_content = "Ah, muda dan antusias, saya lihat!",
  ui_story_5083_50831100_64_dialog_content = "Jadi, kita hanya menunggu di sini?",
  ui_story_5083_50831100_65_dialog_content = "Saya tidak berpikir kita harus terlibat.",
  ui_story_5083_50831100_66_dialog_content = "Denier mendapatkan puding favoritmu, Gronru!",
  ui_story_5083_50831100_67_dialog_content = "Benarkah? Baiklah, biarkan aku bersiap untuk serangan!",
  ui_story_5083_50831100_68_dialog_content = "Panas, panas... Banyak sekali orang, saya bahkan tidak bisa mendapatkan nampan.",
  ui_story_5083_50831100_69_dialog_content = "Biarkan aku membantu kamu... Aduh!",
  ui_story_5083_50831100_70_dialog_content = "Bilang kan, panas.",
  ui_story_5083_50831100_71_dialog_content = "Minggir! Lihat, Barton, saya mendapatkan dua kali lipat dari yang kamu dapatkan.",
  ui_story_5083_50831100_72_dialog_content = "Dari mana kau mendapatkan nampan itu?",
  ui_story_5083_50831100_73_dialog_content = "Inilah artinya menjadi elit dari elit dan komandan dari komando.",
  ui_story_5083_50831100_74_dialog_content = "Masih belum bisa membawa Denier keluar dari sana, tapi aku sudah mendapatkan cukup untuk kita semua.",
  ui_story_5083_50831100_75_dialog_content = "Berikut minumannya! Wajib untuk acara ini!",
  ui_story_5083_50831100_76_dialog_content = "Bagaimana kalau kita adakan kontes?",
  ui_story_5083_50831100_77_dialog_content = "Aku siap!",
  ui_story_5083_50831100_78_dialog_content = "Apakah kamu lupa sesuatu, Reinhardt?",
  ui_story_5083_50831100_79_dialog_content = "Oh, Denier, Gronru, dan Vaughn masih berdesakan di dekat permen.",
  ui_story_5083_50831100_80_dialog_content = "Ada kerumunan besar untuk itu, jadi mari kita lakukan satu putaran sambil menunggu.",
  ui_story_5083_50831100_81_dialog_content = "Sebaiknya aku memeriksa mereka.",
  ui_story_5083_50831100_82_dialog_content = "Jangan terburu-buru. Reinhardt mengatakan kita punya waktu untuk satu putaran.",
  ui_story_5083_50831100_83_dialog_content = "Saya rasa itu tidak masalah. Kami memang punya waktunya.",
  ui_story_5083_50831100_84_dialog_content = "Nah, bersulang?",
  ui_story_5083_50831100_85_dialog_content = "Bersulang!",
  ui_story_5083_50831100_86_dialog_content = "<color=#e8d9bb>Generasi Terang Illumina mengadakan pertemuan pertama mereka di sudut dengan tawa.</color>",
  ui_story_5083_50831100_87_dialog_content = "<color=#e8d9bb>Aku hanya tidak bisa memalingkan mataku dari pesta ini. Aku ingin mengabadikan momen ini, meski sebentar saja.</color>",
  ui_story_5083_50831100_88_dialog_content = "Bagaimana dengan sebuah lagu? Tunjukkan lagu perjuangan yang kamu tulis, Dogg.",
  ui_story_5083_50831100_89_dialog_content = "Lepaskan aku, kau bodoh, dan nyanyikanlah sendiri!",
  ui_story_5083_50831100_90_dialog_content = "Mereka benar-benar tidak terburu-buru...",
  ui_story_5083_50831100_91_dialog_content = "Jangan khawatir tentang saudaramu. Dia sudah cukup tua untuk tidak tersesat.",
  ui_story_5083_50831100_92_dialog_content = "Lalu mari kita buat toast lagi untuk kemitraan luar biasa kita!",
  ui_story_5083_50831100_93_dialog_content = "Apa kemitraan luar biasa yang kamu bicarakan?",
  ui_story_5083_50831100_94_dialog_content = "Tidak ada gunanya berpaling, karena ini dia!",
  ui_story_5083_50831100_95_dialog_content = "<size=45>Bersulang!</size>",
  ui_story_5083_50831200_1_dialog_content = "...",
  ui_story_5083_50831200_2_dialog_content = "Sejujurnya, saya tidak berpikir kamu bisa menjerat kami.",
  ui_story_5083_50831200_3_dialog_content = "Kamu bodoh, Barton. Apakah kamu sadar apa yang sedang kamu katakan?",
  ui_story_5083_50831200_4_dialog_content = "Saya pikir saya sudah menjelaskan dengan sangat jelas... Dan saya memiliki keyakinan pada Reinhardt!",
  ui_story_5083_50831200_5_dialog_content = "Dia sudah gila.",
  ui_story_5083_50831200_6_dialog_content = "Tenanglah, Barton. Dia telah diturunkan ke pangkat terendah.",
  ui_story_5083_50831200_7_dialog_content = "Jadi mungkin dia sedang memanfaatkan kamu, atau bahkan kita 2nd Legion.",
  ui_story_5083_50831200_8_dialog_content = "Aku telah mempertahankan Undercity 19 selama beberapa hari bersamanya.",
  ui_story_5083_50831200_9_dialog_content = "Dia rela mati untuk mereka, jadi bagaimana dia bisa jadi orang jahat?",
  ui_story_5083_50831200_10_dialog_content = "Dia mau, kan?",
  ui_story_5083_50831200_11_dialog_content = "Mungkin Illumina saat ini tidak begitu menarik untuk diceritakan, dan banyak masalah yang tidak bisa diselesaikan dengan mudah, tetapi...",
  ui_story_5083_50831200_12_dialog_content = "Memenuhi tujuanmu berarti kamu harus berdiri melawan Grand Marshal dan teman-temanmu.",
  ui_story_5083_50831200_13_dialog_content = "Aku tidak setuju, tidak selama kita masih melawan Eclipsites.",
  ui_story_5083_50831200_14_dialog_content = "Aku tidak akan pernah menyetujui itu!",
  ui_story_5083_50831200_15_dialog_content = "Selama hidupku, aku telah berjuang untuk Illumina. Aku melihat setiap orang sebagai darah dagingku sendiri.",
  ui_story_5083_50831200_16_dialog_content = "Aku tak akan membiarkan pengkhianatan apapun dan tak akan pernah membantumu!",
  ui_story_5083_50831200_17_dialog_content = "Saya mengerti. Saya pikir Anda tidak akan melihatnya seperti itu.",
  ui_story_5083_50831200_18_dialog_content = "Tapi aku pikir kamu bisa mengerti dari mana asalku.",
  ui_story_5083_50831200_19_dialog_content = "Kami tidak bertujuan untuk menjadi Lumopolis lainnya. Kami hanya ingin menjadi pilar yang menopang Illumina.",
  ui_story_5083_50831200_20_dialog_content = "Perubahan hanya datang setelah itu...",
  ui_story_5083_50831200_21_dialog_content = "Cukup! Aku tidak mau mendengar lagi!",
  ui_story_5083_50831200_22_dialog_content = "...",
  ui_story_5083_50831200_23_dialog_content = "Saya melatihmu dan saya percaya pada penilaian saya.",
  ui_story_5083_50831200_24_dialog_content = "Saya percaya kamu bisa mempercayai Reinhardt dengan hidupmu.",
  ui_story_5083_50831200_25_dialog_content = "Tapi meskipun yang terburuk terjadi, aku tidak ingin bertarung dengan rekan lama... dan aku tidak ingin harus membunuhmu, Barton.",
  ui_story_5083_50831200_26_dialog_content = "Saya tidak melatihmu untuk melawan Illumina, atau Aurorian mana pun, sebenarnya.",
  ui_story_5083_50831200_27_dialog_content = "Itu juga bukan yang kami inginkan! Kami hanya percaya pada keadilan dan berjuang untuk masa depan...",
  ui_story_5083_50831200_28_dialog_content = "Terus bicara dan aku akan mengurungmu di sel sendiri.",
  ui_story_5083_50831200_29_dialog_content = "Santai saja, Barton. Kamu belum yakin apa yang harus dilakukan.",
  ui_story_5083_50831200_30_dialog_content = "Luangkan waktu Anda dan pikirkan dengan baik.",
  ui_story_5083_50831200_31_dialog_content = "Luangkan waktu dan pikirkan lagi? Maksudmu sebenarnya terus menerima omong kosong ini, bukan?",
  ui_story_5083_50831200_32_dialog_content = "Saya telah dipromosikan menjadi letnan kolonel dan menjadi komandan batalyon. Saya tidak berpikir saya masih harus melatih rekrutan baru.",
  ui_story_5083_50831200_33_dialog_content = "Setiap sersan pelatih bisa melakukan itu. Tempat saya seharusnya adalah di garis depan!",
  ui_story_5083_50831200_34_dialog_content = "Dan pemotretan untuk Komite... Aku bukan supermodel.",
  ui_story_5083_50831200_35_dialog_content = "Mengapa mereka tidak bisa memperhatikan para pahlawan sejati di depan sana? Saya membuang-buang waktu saya berbicara tentang betapa amannya di sini!",
  ui_story_5083_50831200_36_dialog_content = "Masih terlalu dini untukmu.",
  ui_story_5083_50831200_37_dialog_content = "Apa maksudmu?",
  ui_story_5083_50831200_38_dialog_content = "Hanya ketika sekutu membantu Anda di masa depan, Anda bisa menjadi...",
  ui_story_5083_50831200_39_dialog_content = "Beep—Setidaknya Barton belum dihukum.",
  ui_story_5083_50831200_40_dialog_content = "Oh, bagaimana bisa aku melupakannya.",
  ui_story_5083_50831200_41_dialog_content = "Aku seharusnya berbicara dengan teman-temanku daripada mengoceh sendirian.",
  ui_story_5083_50831200_42_dialog_content = "Sayang sekali Dogg tidak sependapat dengan saya.",
  ui_story_5083_50831200_43_dialog_content = "Tidak apa-apa, saya bisa melihat Reinhardt. Apakah kamu tahu di mana dia berada?",
  ui_story_5083_50831200_44_dialog_content = "Bip—Ikuti saya, Barton.",
  ui_story_5083_50831200_45_dialog_content = "Ini adalah toko Gronru... Tapi dia dekat dengan kedua orang itu jadi dia harus tahu di mana Reinhardt berada.",
  ui_story_5083_50831200_46_dialog_content = "Siapa yang kamu bicarakan? Dia tidak ada. Saya yang bertanggung jawab saat dia pergi, jadi ceritakan urusanmu kepada saya.",
  ui_story_5083_50831200_47_dialog_content = "Katakanlah, bukankah seharusnya kamu berada di pangkalan, Propaganda untuk Illumina?",
  ui_story_5083_50831200_48_dialog_content = "Aku menyelinap keluar.",
  ui_story_5083_50831200_49_dialog_content = "Tapi lupakan itu. Dimana Reinhardt? Kemana dia pergi?",
  ui_story_5083_50831200_50_dialog_content = "Melakukan latihan khususnya dan bermimpi menjadi Grand Marshal.",
  ui_story_5083_50831200_51_dialog_content = "Bukankah kalian berhubungan baik? Kenapa kamu sangat tidak setuju dengannya?",
  ui_story_5083_50831200_52_dialog_content = "Siapa tahu?",
  ui_story_5083_50831200_53_dialog_content = "Mungkin kakak perempuanku tidak bisa memahami aku lagi...",
  ui_story_5083_50831200_54_dialog_content = "Meskipun kamu mengalahkan saya dalam simulasi, saya punya saran untuk kamu.",
  ui_story_5083_50831200_55_dialog_content = "Kamu tidak pernah bisa menjadi Reinhardt. Kamu tidak sama.",
  ui_story_5083_50831200_56_dialog_content = "Apa pun yang membuatmu tidak nyaman, kamu harus menjelaskannya pada adikmu yang terkasih.",
  ui_story_5083_50831200_57_dialog_content = "Dia selalu menjagamu... Jangan pendam semuanya atau tidak ada yang akan tahu.",
  ui_story_5083_50831200_58_dialog_content = "Jadi, apa yang kau inginkan dengannya?",
  ui_story_5083_50831200_59_dialog_content = "Jangan khawatir tentang itu. Aku tidak bisa berbicara dengannya jika dia tidak ada. Cukup beri tahu dia bahwa aku mampir.",
  ui_story_5083_50831200_60_dialog_content = "Tentu.",
  ui_story_5083_50831200_61_dialog_content = "<color=#e8d9bb>Kata-kata Denier membuat Barton merasa tenang. Dia kembali ke pangkalan dan melanjutkan tugas-tugasnya untuk Komite setelah tindakan disipliner.</color>",
  ui_story_5083_50831200_62_dialog_content = "<color=#e8d9bb>Tapi dia tidak pernah mendapatkan balasan...</color>",
  ui_story_5083_50831200_63_dialog_content = "<color=#e8d9bb>Kota Gannon mengumumkan ledakan laboratorium serius dengan Reinhardt, timnya, dan Gronru hilang dalam tindakan.</color>",
  ui_story_5083_50831301_1_dialog_content = "<color=#e8d9bb>Musim semi telah tiba lagi, namun Darkover Crisis masih berlanjut. Tidak ada yang tahu dari mana asal Eclipsite dan mengapa jumlah mereka terus bertambah.</color>",
  ui_story_5083_50831301_2_dialog_content = "<color=#e8d9bb>Mereka masih berkeliaran di Astra dan membantai kehidupan, yang cukup untuk membuat setiap orang berjuang sampai akhir.</color>",
  ui_story_5083_50831301_3_dialog_content = "<color=#e8d9bb>Dalam perang yang semakin meningkat, pesan mendesak mencapai Gannon, menunjukkan penampakan Eclipsite di dekat pertahanan kota.</color>",
  ui_story_5083_50831301_4_dialog_content = "Apa yang terjadi? Undercity 13 telah mengaktifkan penghancuran diri, dan kami telah menutup semua akses permukaan dari sana.",
  ui_story_5083_50831301_5_dialog_content = "Undercity 19 masih beroperasi. Tidak ada permintaan bantuan, jadi mereka mungkin telah mempertahankan jalur tersebut.",
  ui_story_5083_50831301_6_dialog_content = "Semua Undercity di sepanjang jalur tetap beroperasi. Tidak ada pelanggaran yang dilaporkan.",
  ui_story_5083_50831301_7_dialog_content = "Mungkin saja itu hanya Eclipsite yang lepas datang melintasi gunung atau muncul dari reruntuhan bawah tanah seperti sebelumnya.",
  ui_story_5083_50831301_8_dialog_content = "Ya, tapi pastikan mereka semua dibasmi dengan sangat teliti, bagaimanapun juga.",
  ui_story_5083_50831301_9_dialog_content = "Kirim satu tim lagi untuk melacak sumbernya.",
  ui_story_5083_50831301_10_dialog_content = "Perang ini sedang sengit sekarang. 1st Legion dalam pertahanan perimeter mungkin tidak memiliki soldier untuk cadangan.",
  ui_story_5083_50831301_11_dialog_content = "Eclipsite tidak hanya muncul begitu saja dari udara tipis. Kepuasan diri hanya akan membunuh kita!",
  ui_story_5083_50831301_12_dialog_content = "Jika Legion tidak bisa menyisihkan siapa pun, kami akan menanganinya sendiri.",
  ui_story_5083_50831301_13_dialog_content = "Saya masih memiliki dua batalion utuh di bawah saya. Ini akan menjadi kesempatan mereka untuk menunjukkan kekuatan mereka.",
  ui_story_5083_50831301_14_dialog_content = "Kamu benar. Kita tidak bisa kehilangan apapun dalam perang.",
  ui_story_5083_50831301_15_dialog_content = "Maaf, tetapi sepertinya kamu lupa bahwa saya ada di sini. Komandan Barton dan anak buahnya harus mengikuti tugas-tugas komite. Itu adalah prioritas.",
  ui_story_5083_50831301_16_dialog_content = "Saya membuat permintaan kepada Grand Marshal. Ini tidak ada hubungannya dengan kamu.",
  ui_story_5083_50831301_17_dialog_content = "Maafkan saya, tetapi tugas saya adalah menyampaikan pesan dan melaporkan semua hal kembali ke Komite—termasuk pertemuan Anda.",
  ui_story_5083_50831301_18_dialog_content = "Dengar kamu, kita adalah yang membela Gannon di sini, jadi tenangkan dirimu!",
  ui_story_5083_50831301_19_dialog_content = "Mengingat Barton dan Dogg masih harus melakukan propaganda untuk Komite, mungkin mereka tidak seharusnya meninggalkan kota.",
  ui_story_5083_50831301_20_dialog_content = "Mungkin kamu bisa membawa ini, Pango, bersama timmu dan salah satu batalyon.",
  ui_story_5083_50831301_21_dialog_content = "Tentu, tapi tidak masuk akal jika orang kedua di komando saya mati dalam pertempuran sementara dua prajurit muda yang baik ini ada di sini melakukan pekerjaan yang sibuk!",
  ui_story_5083_50831301_22_dialog_content = "Saya sudah memberi tahu Anda tentang konsekuensi, Pango.",
  ui_story_5083_50831301_23_dialog_content = "Bawa Dogg bersamamu. Saya sendiri yang menyetujui permintaan pendaftarannya, jadi saya akan bertanggung jawab sepenuhnya.",
  ui_story_5083_50831301_24_dialog_content = "Ini perintahku dan kamu bisa kutip aku, Sekretaris Komite.",
  ui_story_5083_50831301_25_dialog_content = "Itu adalah apa adanya. Aku hanya tidak tahan tidak mengetahui dari mana asal Eclipsites.",
  ui_story_5083_50831301_26_dialog_content = "Mundur dan latih prajurit kali ini, Barton.",
  ui_story_5083_50831301_27_dialog_content = "Tidak mungkin, aku punya firasat buruk tentang ini.",
  ui_story_5083_50831301_28_dialog_content = "Sebagai Twin Shields, kedua undercity telah memenuhi tujuan mereka, jadi mengapa Eclipsites muncul di sekitar Gannon sekarang?",
  ui_story_5083_50831301_29_dialog_content = "Itu adalah hal yang biasa sebelumnya, dan mereka sekarang lebih dekat hanya karena 1st Legion terlalu tipis karena kampanye yang intens.",
  ui_story_5083_50831301_30_dialog_content = "Kamu yakin ini bukan masalah?",
  ui_story_5083_50831301_31_dialog_content = "Mereka belum membiarkanku keluar dari Gannon atau melakukan operasi apa pun dalam waktu yang lama sekarang, namun kamu malah dikirim ke medan pertempuran yang sengit.",
  ui_story_5083_50831301_32_dialog_content = "Aku bahkan mulai meragukan Grand Marshal...",
  ui_story_5083_50831301_33_dialog_content = "Diam! Apakah otakmu berhenti bekerja karena terkurung, dan apakah kamu bahkan telah melupakan ajaran kita?",
  ui_story_5083_50831301_34_dialog_content = "Matamu penuh dengan kemarahan dan penentangan! Apakah mereka telah memadamkan setiap benang kehormatan terakhir dalam dirimu?!",
  ui_story_5083_50831301_35_dialog_content = "Kemari, kamu punk!",
  ui_story_5083_50831301_36_dialog_content = "Lihat cahaya itu! Menara Pusat tidak pernah redup. Kamu tumbuh di bawah cahaya itu, jadi kamu harus menjaganya dengan nyawamu!",
  ui_story_5083_50831301_37_dialog_content = "Aku tidak peduli apa masalahmu dengan para atasan, tetapi ingat ini—kamu selalu Illumina.",
  ui_story_5083_50831301_38_dialog_content = "Baru saja aku khawatir tentangmu...",
  ui_story_5083_50831301_39_dialog_content = "Kemudian dedikasikan dirimu untuk tujuan ini dan jangan proyeksikan masalah pribadimu pada Illumina.",
  ui_story_5083_50831301_40_dialog_content = "Grand Marshal mungkin tampak bingung atau bahkan lemah, tetapi dia bukan tipe yang akan mengkhianati sekutunya.",
  ui_story_5083_50831301_41_dialog_content = "Aku tidak akan membiarkan kamu menghina para prajurit kami lagi!",
  ui_story_5083_50831301_42_dialog_content = "Tapi setidaknya ajak aku! Aku benar-benar tidak bisa melepaskan, jadi biarkan aku...",
  ui_story_5083_50831301_43_dialog_content = "Lupakan saja, Barton. Saya yakin itu sudah pernah dicoba.",
  ui_story_5083_50831301_44_dialog_content = "Jangan khawatir, aku ada di belakangmu. Jika terjadi pertarungan, aku akan meminta bantuan segera dan memanggilmu dengan namamu.",
  ui_story_5083_50831301_45_dialog_content = "Dengan cara itu, kamu tidak bisa ditahan lagi.",
  ui_story_5083_50831301_46_dialog_content = "...",
  ui_story_5083_50831301_47_dialog_content = "Saya sama baiknya, jadi tidak ada alasan untuk tidak mempercayai saya, kan?",
  ui_story_5083_50831301_48_dialog_content = "Tunggu saja, Barton. Aku tak akan pernah jadi pelengkap. Lebih baik kau ubah sikap aroganmu.",
  ui_story_5083_50831301_49_dialog_content = "Kutukan! Ini benar-benar menggangguku, seperti sesuatu yang mengerikan akan terjadi.",
  ui_story_5083_50831301_50_dialog_content = "Kenapa aku menjadi begitu gelisah...",
  ui_story_5083_50831301_51_dialog_content = "Beep—Kamu mendapatkan pesan baru, Barton.",
  ui_story_5083_50831301_52_dialog_content = "Pengirim Tidak Dikenal: \"Reinhardt pingsan saat mencoba menyelamatkan orang-orang dalam kecelakaan laboratorium.\"",
  ui_story_5083_50831301_53_dialog_content = "…?",
  ui_story_5083_50831301_54_dialog_content = "\"Maaf, aku terlalu percaya diri... tidak mencurigai adanya kesalahan dalam data... □□... Bahaya...\"",
  ui_story_5083_50831301_55_dialog_content = "\"Aku akan bertanggung jawab atas ini... saat beristirahat... □□... Jangan khawatir, Denier ada di Reinhardt...\"",
  ui_story_5083_50831301_56_dialog_content = "Kesalahan: Menguping terdeteksi. Sinyal terganggu.",
  ui_story_5083_50831301_57_dialog_content = "Itu terdengar seperti Gronru. Tapi kenapa, dan apa yang terjadi?",
  ui_story_5083_50831301_58_dialog_content = "Pesan ini memiliki terlalu banyak enkripsi untuk melacak asalnya.",
  ui_story_5083_50831301_59_dialog_content = "Ini buruk. Semakin berantakan untukku.",
  ui_story_5083_50831301_60_dialog_content = "Mengapa Reinhardt terlibat? Apa yang terjadi pada Gronru? Dan mengapa pesan tersebut dipantau?",
  ui_story_5083_50831301_61_dialog_content = "Apa yang terjadi tanpa aku tahu? Sialan, ini membuatku gila...",
  ui_story_5083_50831301_62_dialog_content = "Bip—Segera beristirahat dan hilangkan stres sangat disarankan, Barton.",
  ui_story_5083_50831301_63_dialog_content = "Tidak, saya tidak bisa istirahat sekarang!",
  ui_story_5083_50831301_64_dialog_content = "Saya tidak bisa hanya berdiam diri dan tidak melakukan apa-apa.",
  ui_story_5083_50831301_65_dialog_content = "Barton...",
  ui_story_5083_50831301_66_dialog_content = "Aku harus pergi dan mengejar Dogg dan yang lainnya.",
  ui_story_5083_50831301_67_dialog_content = "Tapi kamu tidak menerima perintah apa pun, Barton.",
  ui_story_5083_50831301_68_dialog_content = "Aku tidak peduli!",
  ui_story_5083_50831301_69_dialog_content = "Bahkan membuat kesalahan lebih baik daripada tidak melakukan apa-apa sama sekali!",
  ui_story_5083_50831301_70_dialog_content = "Ini semua karena cahaya itu, Pria Tua! Karena itulah kita harus terus maju!",
  ui_story_5083_50831301_71_dialog_content = "Aku tidak peduli apa yang akan terjadi lagi! Aku tidak bisa membiarkan hal buruk terjadi pada siapa pun di antara mereka!",
  ui_story_5083_50831301_72_dialog_content = "2nd Legion, berkumpul!",
  ui_story_5083_50831301_73_dialog_content = "Kami menemukan jejak pertempuran, Commander Barton. Kemungkinan besar Commander telah bertarung melawan Eclipsite di sini sebelum legion menghilang.",
  ui_story_5083_50831301_74_dialog_content = "Mengingat skala pertempuran, kemungkinan bukan Eclipsite yang lepas. Saya percaya Komandan telah mundur.",
  ui_story_5083_50831301_75_dialog_content = "Cepat, ikuti jejak, intai medan, dan buka jalan untuk konvoi!",
  ui_story_5083_50831301_76_dialog_content = "Tidak terlalu terlambat. Saya yakin kita akan berhasil...",
  ui_story_5083_50831302_1_dialog_content = "Bagaimana?",
  ui_story_5083_50831302_2_dialog_content = "Komunikasi masih terblokir. Ini aneh karena Eclipsite tidak memiliki teknologi.",
  ui_story_5083_50831302_3_dialog_content = "Saya percaya kita terkepung.",
  ui_story_5083_50831302_4_dialog_content = "Apa status kita?",
  ui_story_5083_50831302_5_dialog_content = "Hanya dua puluh dari dua ratus yang menjaga belakang yang selamat. Kami juga kehilangan sepertiga dari komando kami.",
  ui_story_5083_50831302_6_dialog_content = "Eclipsite melebihi kita lebih dari yang kita duga. Kami telah kehilangan kendali atas situasi ini.",
  ui_story_5083_50831302_7_dialog_content = "Mungkin sebuah Undercity di sepanjang garis pertahanan telah ditembus sehingga hal ini bisa terjadi.",
  ui_story_5083_50831302_8_dialog_content = "Atau mungkin ada pengkhianat. Bagaimanapun, aku akan memimpin tim untuk memecahkan pengepungan dan memungkinkan kamu untuk pergi.",
  ui_story_5083_50831302_9_dialog_content = "Kamu harus membawa berita ini kembali ke Gannon untuk menghindari kerugian yang lebih besar.",
  ui_story_5083_50831302_10_dialog_content = "Tidak, banyak instalasi belum sepenuhnya dipulihkan dan Outpost 1st Legion masih utuh. Saya tidak bisa begitu saja pergi.",
  ui_story_5083_50831302_11_dialog_content = "Namun…",
  ui_story_5083_50831302_12_dialog_content = "<color=#e8d9bb>DUAR!</color>",
  ui_story_5083_50831302_13_dialog_content = "Apa yang sedang terjadi? Apakah kita sedang diserang Eclipsite?",
  ui_story_5083_50831302_14_dialog_content = "Apakah kamu baik-baik saja? Di mana Komandan Pango?",
  ui_story_5083_50831302_15_dialog_content = "Apa yang kamu lakukan di sini, bocah nakal?",
  ui_story_5083_50831302_16_dialog_content = "Senang melihatmu baik-baik saja, tapi aku rasa ini bukan saatnya untuk bertanya hal itu padaku!",
  ui_story_5083_50831302_17_dialog_content = "Kamu tepat waktu. Apakah kamu melihat Eclipsite?",
  ui_story_5083_50831302_18_dialog_content = "Tim mech saya telah menembus baris mereka. Saya bertemu dengan pengintai dari 1st Legion di jalan dan sudah memberi tahu mereka.",
  ui_story_5083_50831302_19_dialog_content = "Kami memiliki instalasi yang perlu kami pulihkan. Berapa banyak transportasi yang bisa kamu sediakan, Barton? Kami harus melakukan ini sesegera mungkin!",
  ui_story_5083_50831302_20_dialog_content = "Itu tidak akan menjadi masalah. Tapi apa yang terjadi di sini? Aku tidak bisa mendapatkan sinyal apa pun.",
  ui_story_5083_50831302_21_dialog_content = "Kami sudah mencoba mengirim suar SOS.",
  ui_story_5083_50831302_22_dialog_content = "Hanya menara jaga yang bisa melihat flare, dan aku tidak yakin mereka memiliki sinyal untuk meneruskannya ke Gannon.",
  ui_story_5083_50831302_23_dialog_content = "Tidak apa-apa. Jika kamu sudah memberi tahu para pengintai, bantuan seharusnya akan segera datang.",
  ui_story_5083_50831302_24_dialog_content = "Berita buruk, Eclipsites mencoba untuk mengatasi barikade kita dengan jumlah yang besar!",
  ui_story_5083_50831302_25_dialog_content = "Kami juga melihat sebuah <color=#FFB400>Eclipsite raksasa</color> yang mendekat dan harus dihalau!",
  ui_story_5083_50831302_26_dialog_content = "<color=#FFB400>Eclipse Gargantuan</color>? Eclipsite Siege legendaris?",
  ui_story_5083_50831302_27_dialog_content = "Akan sulit untuk membunuh bajingan itu tanpa senjata yang serius...",
  ui_story_5083_50831302_28_dialog_content = "Bagi divisi tank menjadi dua, satu untuk menutupi mundur kita dan satu untuk mempertahankan garis depan!",
  ui_story_5083_50831302_29_dialog_content = "Dapatkan sepuluh carrier dengan empat komando masing-masing untuk memulihkan instalasi permukaan di sekitar Gannon.",
  ui_story_5083_50831302_30_dialog_content = "Siap!",
  ui_story_5083_50831302_31_dialog_content = "<color=#e8d9bb>Bombardir menandakan awal perang. Namun, gema suara bel yang tidak biasa menenggelamkan semua suara.</color>",
  ui_story_5083_50831302_32_dialog_content = "Ayo berlari bersamaku, Dogg! Mari kita buang Eclipsite berukuran super itu!",
  ui_story_5083_50831302_33_dialog_content = "Unit saya masih memiliki menara yang diselamatkan dari Undercity 19, dan menara-menara itu bisa menimbulkan kerusakan besar!",
  ui_story_5083_50831302_34_dialog_content = "Tidak!",
  ui_story_5083_50831302_35_dialog_content = "Kalian berdua pergi dan tinggalkan aku dan timku di belakang.",
  ui_story_5083_50831302_36_dialog_content = "Ini adalah serangan yang direncanakan tetapi kita bukan targetnya... Gannon lah yang menjadi target.",
  ui_story_5083_50831302_37_dialog_content = "Ini bukan operasi yang bisa ditangani hanya oleh kalian berdua, orang tolol.",
  ui_story_5083_50831302_38_dialog_content = "Pergi sekarang dan beri tahu Gannon! Lebih cepat lebih baik!",
  ui_story_5083_50831302_39_dialog_content = "Apa yang kamu katakan? Kita tidak bisa meninggalkanmu di saat-saat seperti ini!",
  ui_story_5083_50831302_40_dialog_content = "Mereka lebih banyak dari kita, tapi itu justru alasan untuk kita tetap bersama-sama.",
  ui_story_5083_50831302_41_dialog_content = "Kamu mendengar <color=#FFB400>dering</color>? Itu adalah Bencana Zona Gelap yang menghancurkan Undercity 13.",
  ui_story_5083_50831302_42_dialog_content = "Dalam Pertempuran Zona Gelap, lonceng itu menandakan kekalahan kita.",
  ui_story_5083_50831302_43_dialog_content = "Kalau kamu tidak pergi sekarang, tak satu pun dari kita yang akan selamat!",
  ui_story_5083_50831302_44_dialog_content = "Namun…",
  ui_story_5083_50831302_45_dialog_content = "Sekarang!",
  ui_story_5083_50831302_46_dialog_content = "Aku tak bisa meninggalkanmu, karena kau lebih dari seorang atasan bagiku... Setidaknya biarkan aku tetap bersamamu.",
  ui_story_5083_50831302_47_dialog_content = "Aku mengerti.",
  ui_story_5083_50831302_48_dialog_content = "Tapi tidak seharusnya ada anak yang meninggal sebelum orang tuanya.",
  ui_story_5083_50831302_49_dialog_content = "Saya sudah kehilangan seorang anak, Dogg. Saya tidak bisa kehilangan kamu juga.",
  ui_story_5083_50831302_50_dialog_content = "Oh…!",
  ui_story_5083_50831302_51_dialog_content = "Kamu pria tua...",
  ui_story_5083_50831302_52_dialog_content = "Aku... paham.",
  ui_story_5083_50831302_53_dialog_content = "Keluar dari sini jika kamu mengerti. Menjauh dari pandanganku sehingga kamu menjauh dari pikiranku!",
  ui_story_5083_50831302_54_dialog_content = "Saya punya pertempuran untuk diperjuangkan!",
  ui_story_5083_50831302_55_dialog_content = "Apa yang kamu lakukan, Dogg?!",
  ui_story_5083_50831302_56_dialog_content = "Ambil Komandan Pango... uh, Pops. Pasukan komando akan membuka jalan untukmu.",
  ui_story_5083_50831302_57_dialog_content = "Ini bukan saatnya kamu bermain pahlawan!",
  ui_story_5083_50831302_58_dialog_content = "Aku selalu iri padamu, Barton...",
  ui_story_5083_50831302_59_dialog_content = "Sebagai seorang elit sepertimu, aku selalu selangkah di belakang, selalu menjadi pelengkap.",
  ui_story_5083_50831302_60_dialog_content = "Ini bukan waktunya untuk itu, bodoh!",
  ui_story_5083_50831302_61_dialog_content = "Biarkan aku selesai. Aku selalu iri bahwa kamu lebih baik dariku, bisa pergi lebih jauh dariku, dan diperlakukan lebih baik dariku...",
  ui_story_5083_50831302_62_dialog_content = "Kamu selalu melaju ke depan, dengan semua orang mengikutimu dengan sukarela...",
  ui_story_5083_50831302_63_dialog_content = "Dalam dirimu, aku melihat kekuatan untuk menaklukkan kegelapan yang layak bagi seorang elit.",
  ui_story_5083_50831302_64_dialog_content = "Kamu lebih tegas daripada saya, jadi saya akan selalu menjadi yang kedua untukmu.",
  ui_story_5083_50831302_65_dialog_content = "Saya senang mengetahui, meski begitu, bahwa saya telah bekerja keras cukup untuk berada satu tingkat di bawah kamu.",
  ui_story_5083_50831302_66_dialog_content = "Jadi, saya ingin menunda Eclipsites seperti kamu agar kamu bisa sampai di rumah.",
  ui_story_5083_50831302_67_dialog_content = "<color=#e8d9bb>Deru lonceng semakin dekat seiring blaster menjadi semakin tenang. Garis pertahanan mundur untuk memberi jalan bagi mundurnya pasukan.</color>",
  ui_story_5083_50831302_68_dialog_content = "Ini hanya berarti lebih banyak orang yang akan dikorbankan! Aku harus tinggal dan membantu!",
  ui_story_5083_50831302_69_dialog_content = "Semua orang mati kadang-kadang. Bukankah kita semua sudah siap untuk itu saat pertama kali kita mengangkat senjata?",
  ui_story_5083_50831302_70_dialog_content = "Tapi untuk masa depan legiun dan Illumina, ini bukan tempatnya untuk itu, untuk seseorang seperti kamu.",
  ui_story_5083_50831302_71_dialog_content = "Biarkan aku memberimu bantuan terbaik yang pernah kau miliki. Lakukan halmu setelah aku membuat pembukaan.",
  ui_story_5083_50831302_72_dialog_content = "Masa depan Illumina tergantung pada kamu.",
  ui_story_5083_50831302_73_dialog_content = "Berhenti omong kosong itu. Kita masih memiliki tank...",
  ui_story_5083_50831302_74_dialog_content = "Ingat cerita yang pernah saya ceritakan? Pango mengorbankan istrinya dan anaknya demi saya.",
  ui_story_5083_50831302_75_dialog_content = "Saya telah berpikir, siapakah saya hingga pantas mendapatkan kehormatan seperti ini.",
  ui_story_5083_50831302_76_dialog_content = "Aku telah hidup dengan rasa bersalah. Banyak kali, aku merasa mati dalam pikiranku.",
  ui_story_5083_50831302_77_dialog_content = "Dasar idiot! Jika kamu tidak bertahan, lalu siapa yang akan mendorongku dan membuatku berusaha lebih keras?",
  ui_story_5083_50831302_78_dialog_content = "Yah, aku bisa merasakannya saat kamu berbicara padaku tentang mimpi itu. Itu sangat menggugahku.",
  ui_story_5083_50831302_79_dialog_content = "Meski instingku ingin membantah, aku tidak melakukannya karena aku tahu aku rela mati demi tujuan itu.",
  ui_story_5083_50831302_80_dialog_content = "Berikan kami kesempatan, Barton. Kami tidak mati sia-sia, tetapi untuk kemuliaan dan harapan Illumina yang lebih besar.",
  ui_story_5083_50831302_81_dialog_content = "Unit tank telah berhasil menembus lawan!",
  ui_story_5083_50831302_82_dialog_content = "Tapi Eclipsite raksasa itu membuat kita tidak mungkin untuk mundur dengan aman!",
  ui_story_5083_50831302_83_dialog_content = "Sampaikan perintahku agar semua komando tetap di belakang dan melindungi rekan-rekan prajurit kita!",
  ui_story_5083_50831302_84_dialog_content = "Beritahu unit mekanis untuk memberikan mereka sebanyak mungkin amunisi, lalu kita ambil sisanya dan mundur ke Gannon!",
  ui_story_5083_50831302_85_dialog_content = "Barton, kamu adalah saudaraku, musuhku, mimpi burukku, alasan aku menjadi orang kedua.",
  ui_story_5083_50831302_86_dialog_content = "Dan akulah alasan mengapa kau yang terbaik!",
  ui_story_5083_50831302_87_dialog_content = "Ambil ini dan pergi.",
  ui_story_5083_50831302_88_dialog_content = "Kamu tetap hidup sampai aku membawa bala bantuan!",
  ui_story_5083_50831302_89_dialog_content = "Minggir, serangga Illumina yang lemah!",
  ui_story_5083_50831302_90_dialog_content = "Teman-teman, inilah tujuan dibuatnya komando! Mari kita berjuang untuk satu sama lain! <size=45>Maju!</size>",
  ui_story_5083_50831302_91_dialog_content = "<color=#e8d9bb>Dogg meraungkan lagu perang dengan keras dan melangkah maju. Semua komando mengikuti dan menyerang gerombolan.</color>",
  ui_story_5083_50831302_92_dialog_content = "<size=45>Mati saja kau.</size>",
  ui_story_5083_50831302_93_dialog_content = "Terbang keras dan kuat, jangan berhenti sampai mimpi menjadi kenyataan!",
  ui_story_5083_50831302_94_dialog_content = "Pergi, Barton... Terus maju menuju masa depan yang cerah...",
  ui_story_5083_50831400_1_dialog_content = "<color=#e8d9bb>Prajurit pengintai 1st Legion membawa kembali berita bahwa semua komando tewas dalam aksi. Mereka memukul mundur tentara Darkover dengan harga nyawa mereka.</color>",
  ui_story_5083_50831400_2_dialog_content = "<color=#e8d9bb>Alarm berbunyi di seluruh Gannon ketika mobilisasi penuh dideklarasikan. Semua orang beraksi melawan Eclipsites yang mendekat.</color>",
  ui_story_5083_50831400_3_dialog_content = "Sudah terlambat untuk menebus kesalahan. Sebuah batalyon lengkap dikorbankan untuk apa-apa!",
  ui_story_5083_50831400_4_dialog_content = "Ini adalah pertemuan rahasia, Kolonel Barton. Tolong jangan lanjutkan.",
  ui_story_5083_50831400_5_dialog_content = "Grand Marshal masih merumuskan rencana. Berhenti mengganggu atau akan ada konsekuensinya.",
  ui_story_5083_50831400_6_dialog_content = "Tembak, aku menantangmu.",
  ui_story_5083_50831400_7_dialog_content = "Mohon mundur, Kolonel Barton!",
  ui_story_5083_50831400_8_dialog_content = "Jika kamu tidak punya keberanian untuk menarik pelatir, jangan arahkan benda itu padaku.",
  ui_story_5083_50831400_9_dialog_content = "Kenapa kamu berteriak tentang ini kali ini, anak nakal?!",
  ui_story_5083_50831400_10_dialog_content = "Kembali ke sini sebelum kamu mempermalukan diri sendiri di depan Grand Marshal!",
  ui_story_5083_50831400_11_dialog_content = "Anda sudah sadar, Tuan...",
  ui_story_5083_50831400_12_dialog_content = "Salam, Grand Marshal!",
  ui_story_5083_50831400_13_dialog_content = "...",
  ui_story_5083_50831400_14_dialog_content = "Hei, berhenti menahan aku! Aku ingin jawaban darinya!",
  ui_story_5083_50831400_15_dialog_content = "Kenapa kau menolak untuk mengirimkan hanya dua batalyon saja? Kenapa kau tidak mengerahkan unit mekanis sejak awal?",
  ui_story_5083_50831400_16_dialog_content = "Mereka tidak akan terjebak jika mereka memiliki transportasi...",
  ui_story_5083_50831400_17_dialog_content = "Tenanglah!",
  ui_story_5083_50831400_18_dialog_content = "Dogg dan semua orang lainnya, mereka sudah mati. Bagaimana saya bisa tenang!",
  ui_story_5083_50831400_19_dialog_content = "Kamu mempercayai orang yang salah! Orang-orang itu tidak memiliki strategi selain tipu daya untuk dibicarakan, itulah sebabnya Dogg dan yang lainnya mati sia-sia!",
  ui_story_5083_50831400_20_dialog_content = "Mereka menargetkan kita... tapi mengapa mereka tidak langsung menyerangku?",
  ui_story_5083_50831400_21_dialog_content = "Sialan, kenapa mereka tidak menyerangku!",
  ui_story_5083_50831400_22_dialog_content = "Hentikan sebelum kamu malukan 2nd Legion juga. Bagaimana perasaan Dogg tentang ini?",
  ui_story_5083_50831400_23_dialog_content = "Ini adalah kali kedua kamu meninggalkan Gannon dengan unit mekanis! Kamu beruntung Grand Marshal belum menindakmu!",
  ui_story_5083_50831400_24_dialog_content = "Dia bertanggung jawab atas kematian Dogg!",
  ui_story_5083_50831400_25_dialog_content = "Jelas dia adalah pelakunya...",
  ui_story_5083_50831400_26_dialog_content = "Dogg adalah satu-satunya anak laki-laki Grand Marshal.",
  ui_story_5083_50831400_27_dialog_content = "Berhenti menjual kebohongan padaku, pria tua!",
  ui_story_5083_50831400_28_dialog_content = "Ikuti aku.",
  ui_story_5083_50831400_29_dialog_content = "Roog dan aku adalah teman lama perang. Tepat sebelum dia ditunjuk sebagai Grand Marshal, istrinya yang sedang hamil terjebak di kota bawah tanah.",
  ui_story_5083_50831400_30_dialog_content = "Aku memimpin sebuah pasukan penyelamat tetapi sudah terlambat. Undercity jatuh. Dalam catatan, tidak ada yang selamat.",
  ui_story_5083_50831400_31_dialog_content = "Tapi ketika aku menemukan tubuh istrinya, aku melihat Dogg berbaring di pelukan ibunya. Dia diam dan tidak pernah menangis.",
  ui_story_5083_50831400_32_dialog_content = "Saya tidak tahu bagaimana dia bisa melahirkan seorang anak kecil di lingkungan yang begitu buruk dan membantu dia bertahan hidup... Itu adalah keajaiban.",
  ui_story_5083_50831400_33_dialog_content = "Saya masih ingat betapa sedihnya Roog ketika saya membawa Dogg kembali. Dia sangat mencintai istrinya, tetapi harus menjalankan tugasnya sebagai seorang prajurit.",
  ui_story_5083_50831400_34_dialog_content = "Tidak ada yang tahu tentang anak kecil itu, jadi dia mempercayakan anak itu padaku. Ada sesuatu yang mengganjal pikirannya saat itu dan dia ingin fokus pada perang.",
  ui_story_5083_50831400_35_dialog_content = "Mustahil…",
  ui_story_5083_50831400_36_dialog_content = "Itu fakta. Undercity yang saya pertahankan telah diserbu enam tahun lalu. Komite menemukan kisah sebenarnya Dogg ketika mereka melalui prosedur biasa.",
  ui_story_5083_50831400_37_dialog_content = "Aku tidak tahu apakah itu ada hubungannya, tetapi setelah itu Roog menjadi ragu dan menjauh dariku.",
  ui_story_5083_50831400_38_dialog_content = "Sebagai Grand Marshal, meskipun dia semakin kuat, dia bertindak semakin konservatif.",
  ui_story_5083_50831400_39_dialog_content = "Aku tidak mengerti, tapi aku akan bertaruh hidupku bahwa dia memiliki kepentingan terbaik untuk Illumina di hatinya.",
  ui_story_5083_50831400_40_dialog_content = "Meskipun tujuannya mungkin sedikit meleset, dia tidak akan pernah menyakiti anaknya sendiri.",
  ui_story_5083_50831400_41_dialog_content = "Apakah kamu sudah memberitahu si bodoh itu siapa ayahnya?",
  ui_story_5083_50831400_42_dialog_content = "Tentu saja.",
  ui_story_5083_50831400_43_dialog_content = "His sacrificed his wife to evacuate me and the other noncombatants.",
  ui_story_5083_50831400_44_dialog_content = "Saya telah berpikir, siapakah saya untuk pantas mendapatkan kehormatan seperti ini.",
  ui_story_5083_50831400_45_dialog_content = "Bodoh itu telah membawa rasa bersalah tentang siapa dia sebenarnya selama bertahun-tahun ini...",
  ui_story_5083_50831400_46_dialog_content = "Jadi, saya sangat menyesal telah memberitahunya.",
  ui_story_5083_50831400_47_dialog_content = "...",
  ui_story_5083_50831400_48_dialog_content = "Cepat, ambil sebanyak yang kamu bisa dan isi semua karung pasir... Berhenti, kamu di sana. Ini adalah skuad 1st Legion yang menuju ke depan!",
  ui_story_5083_50831400_49_dialog_content = "Reinhardt?",
  ui_story_5083_50831400_50_dialog_content = "Kau sudah dikeluarkan dari rumah sakit, aku mengerti.",
  ui_story_5083_50831400_51_dialog_content = "Itu sudah lama sekali. Apa yang kamu lakukan berkeliling di sini ketika Illumina sedang menghadapi krisis?",
  ui_story_5083_50831400_52_dialog_content = "Kendaraan sudah dimuat, Kolonel Reinhardt. Kami akan berangkat sekarang.",
  ui_story_5083_50831400_53_dialog_content = "Semoga selamat sampai tujuan!",
  ui_story_5083_50831400_54_dialog_content = "Hmm, orangnya tidak cukup. Ini hanya bisa menimbulkan masalah bagi komandan...",
  ui_story_5083_50831400_55_dialog_content = "Kamu terasa sedikit berbeda bagi ku...",
  ui_story_5083_50831400_56_dialog_content = "Aku? Aku sibuk dengan mobilisasi, jadi aku tidak punya waktu untuk berbasa-basi.",
  ui_story_5083_50831400_57_dialog_content = "Hei, tunggu sebentar, Reinhardt...",
  ui_story_5083_50831400_58_dialog_content = "Kamu masih ingat apa yang kita bicarakan sebelumnya?",
  ui_story_5083_50831400_59_dialog_content = "Apa yang telah Committee lakukan padamu?",
  ui_story_5083_50831400_60_dialog_content = "Maksudmu mempromosikan aku menjadi kolonel?",
  ui_story_5083_50831400_61_dialog_content = "Tidak! Kenapa kamu...",
  ui_story_5083_50831400_62_dialog_content = "Saya tahu apa yang ingin kamu katakan. Mengenai Komite, saya harus menahannya untuk sekarang. Perang adalah masalah yang sebenarnya.",
  ui_story_5083_50831400_63_dialog_content = "Saya harus melapor ke komandan. Kamu mungkin sedikit bingung, tapi saya harap kamu bisa semangat. Kau ini pahlawan Illumina, setelah semua.",
  ui_story_5083_50831400_64_dialog_content = "Heh, \"Pahlawan Illumina\"? Lalu, apa gelar yang harus disebutkan untuk Dogg dan yang lainnya yang tidak akan kembali?",
  ui_story_5083_50831400_65_dialog_content = "Komite tidak berhak menentukan siapa yang menjadi pahlawan dan siapa yang tidak!",
  ui_story_5083_50831400_66_dialog_content = "Reinhardt…",
  ui_story_5083_50831400_67_dialog_content = "Beep—Silakan ikuti saya, Barton.",
  ui_story_5083_50831400_68_dialog_content = "Nah, setidaknya kamu belum berubah sama sekali, Navigator-ku.",
  ui_story_5083_50831400_69_dialog_content = "Ayo pergi. Kemana pun kamu membawaku tidak mungkin lebih buruk dari ini.",
  ui_story_5083_50831400_70_dialog_content = "Monumen itu... Apakah nama Dogg telah ditambahkan?",
  ui_story_5083_50831400_71_dialog_content = "Beep—Lihat, Barton.",
  ui_story_5083_50831400_72_dialog_content = "<color=#e8d9bb>Di bawah monumen yang menjulang tinggi, sosok yang membungkuk menatap nama-nama tanpa ekspresi.</color>",
  ui_story_5083_50831400_73_dialog_content = "Itu Grand Marshal.",
  ui_story_5083_50831400_74_dialog_content = "Ayah asli <color=#FFB400>Dogg</color>...",
  ui_story_5083_50831400_75_dialog_content = "<color=#e8d9bb>Barton berhenti sejenak. Dia ingin maju tetapi berubah pikiran dan tetap berdiri di tempatnya.</color>",
  ui_story_5083_50831400_76_dialog_content = "Anji...",
  ui_story_5083_50831400_77_dialog_content = "<color=#e8d9bb>Pria yang tampak lesu di kejauhan meneteskan air mata diam-diam. Dia bukan Grand Marshal, tetapi seorang ayah yang patah hati.</color>",
  ui_story_5083_50831400_78_dialog_content = "<color=#e8d9bb>Akhirnya dia pergi dengan langkah berat untuk memberi jalan kepada Barton.</color>",
  ui_story_5083_50831400_79_dialog_content = "Nama setiap prajurit telah ditambahkan. Ini adalah tempat peristirahatan terakhir untuk semua anak-anak Illumina.",
  ui_story_5083_50831400_80_dialog_content = "Beep—Barton...",
  ui_story_5083_50831400_81_dialog_content = "Siapa lagi yang bisa aku percaya selain kamu sekarang? Setiap orang memiliki rahasia, dengan lapisan yang tak berujung juga...",
  ui_story_5083_50831400_82_dialog_content = "Meskipun Grand Marshal dan yang lainnya tidak bersalah, bagaimana saya bisa mempercayai mereka...?",
  ui_story_5083_50831400_83_dialog_content = "Lihatlah, Barton.",
  ui_story_5083_50831400_84_dialog_content = "Apakah ini foto kita semua bersama?",
  ui_story_5083_50831400_85_dialog_content = "Apakah kamu yang mengambil foto ini untuk kami? Terima kasih.",
  ui_story_5083_50831400_86_dialog_content = "Dogg sudah pergi, Reinhardt tidak sama, dan siapa yang tahu kemana sisanya pergi.",
  ui_story_5083_50831400_87_dialog_content = "Semua orang dalam gambar ini telah berpencar...",
  ui_story_5083_50831400_88_dialog_content = "Tapi, aku harus membawa beban dan mendorong maju, bukan?",
  ui_story_5083_50831400_89_dialog_content = "Meski hanya aku yang tersisa, aku tetap akan mengambil alih kemudi.",
  ui_story_5083_50831500_1_dialog_content = "<color=#e8d9bb>Ketika pertempuran untuk Gannon semakin intens, Komite akhirnya mengalah untuk Barton membawa kembali pasukan yang telah dipasok ulang ke garis depan.</color>",
  ui_story_5083_50831500_2_dialog_content = "<color=#e8d9bb>Namun, situasi tidak membaik dengan ancaman Darkover di perbatasan Gannon. Untuk menghindari pengepungan, Marsekal Besar memerintahkan evakuasi.</color>",
  ui_story_5083_50831500_3_dialog_content = "Komandan Barton, Darkover telah mundur. Apa perintah Anda?",
  ui_story_5083_50831500_4_dialog_content = "Dorong garis pertahanan tapi lakukan secara perlahan. Tidak, abaikan itu. Tidak ada gerakan berisiko. Kita dalam posisi yang lebih baik untuk transportasi logistik sekarang.",
  ui_story_5083_50831500_5_dialog_content = "Unit tank meminta serangan balik, Commander Barton.",
  ui_story_5083_50831500_6_dialog_content = "Tidak, sama sekali tidak! Berhenti memikirkan membunuh musuh saat kita sedang bertempur dalam pertempuran bertahan! Kita hanya perlu mengusir mereka.",
  ui_story_5083_50831500_7_dialog_content = "Tapi 1st Legion masih terlibat dalam pertempuran sengit... Bukankah kita harus membantu?",
  ui_story_5083_50831500_8_dialog_content = "Tidak ada yang bisa kita lakukan tentang itu. Kita bisa mengambil risiko apa pun. Saya tidak bisa membiarkan kamu pergi tanpa persiapan...",
  ui_story_5083_50831500_9_dialog_content = "Apa yang kamu lakukan terjebak di sini seperti kura-kura? Ada banyak Eclipsite di luar sana yang bisa kamu kejar!",
  ui_story_5083_50831500_10_dialog_content = "Tapi ada yang akan mati...",
  ui_story_5083_50831500_11_dialog_content = "Bagaimana kamu bisa berperang tanpa ada yang mati? Yang penting adalah apa yang kamu perjuangkan!",
  ui_story_5083_50831500_12_dialog_content = "Tidak bisakah kamu lebih tahu, anak nakal? Jangan berharap aku bersikap lunak padamu sekarang!",
  ui_story_5083_50831500_13_dialog_content = "Aku tidak melihat cahaya lagi...",
  ui_story_5083_50831500_14_dialog_content = "?!",
  ui_story_5083_50831500_15_dialog_content = "Dengan Central Tower yang terus berkembang di depan, saya telah maju terus untuk Illumina.",
  ui_story_5083_50831500_16_dialog_content = "Aku tumbuh besar mengejarnya, berusaha mencapainya... Tapi aku tidak melihatnya sekarang.",
  ui_story_5083_50831500_17_dialog_content = "Aku tidak bisa menemukan alasan mengapa para prajuritku harus berjuang untukku. Aku tidak ingin mereka mati karena perintahku.",
  ui_story_5083_50831500_18_dialog_content = "Aku tahu aku seharusnya memimpin mereka, tapi aku bahkan tidak bisa menemukan pijakan ku sendiri sekarang...",
  ui_story_5083_50831500_19_dialog_content = "Kapan kau juga menjadi begitu plin-plan, begundal?",
  ui_story_5083_50831500_20_dialog_content = "Kamu membuat keputusan dan memberikan perintah berdasarkan laporan yang kamu dapatkan untuk menyelesaikan tujuan. Bukankah itu sudah cukup?",
  ui_story_5083_50831500_21_dialog_content = "Prajurit Illumina bukanlah orang bodoh. Mereka tahu apa yang mereka perjuangkan!",
  ui_story_5083_50831500_22_dialog_content = "Meskipun mereka tidak bisa menjelaskannya dengan baik, cukup tanya, dan setiap orang di antara mereka akan memberitahu kamu penyebab yang membuat mereka rela mati!",
  ui_story_5083_50831500_23_dialog_content = "Keluar dari markas sekarang dan masuk ke parit pertahanan! Kamu akan melihat arah yang ditunjukkan oleh tekad mereka ke mana kamu harus pergi!",
  ui_story_5083_50831500_24_dialog_content = "Setiap prajurit Illumina kami tumbuh besar di bawah cahaya. Bagaimana bisa kamu lupa tentang itu?",
  ui_story_5083_50831500_25_dialog_content = "Mereka tumbuh besar di bawah cahaya...",
  ui_story_5083_50831500_26_dialog_content = "Buatlah rencana yang lebih baik jika kamu pikir korban akan banyak! Tapi jangan pernah meninggalkan pasukanmu!",
  ui_story_5083_50831500_27_dialog_content = "Mengeluh sendirian tidak menyelesaikan apa-apa! Apakah ini cara kau membalas pengorbanan orang-orang yang telah mati?",
  ui_story_5083_50831500_28_dialog_content = "Apakah para tentara masih akan mengikutimu jika mereka melihatmu seperti ini?",
  ui_story_5083_50831500_29_dialog_content = "Tidakkah kamu masih mendapatkan banyak orang yang mempercayaimu? Kenapa kamu begitu merendahkan dirimu sendiri?!",
  ui_story_5083_50831500_30_dialog_content = "Apa yang membuatmu berpikir bahwa kamu memiliki hak untuk berbicara atas nama semua orang? Kamu bukan satu-satunya pahlawan di sini! Beri mereka kesempatan!",
  ui_story_5083_50831500_31_dialog_content = "Anda benar. Saya lemah dan bingung.",
  ui_story_5083_50831500_32_dialog_content = "Tidak ada masa depan jika kamu diam saja, dan tidak ada hadiah tanpa risiko!",
  ui_story_5083_50831500_33_dialog_content = "Setiap orang ingin melayani cahaya. Karena mereka masih bersamamu, kamu harus memastikan cahaya itu tidak kabur.",
  ui_story_5083_50831500_34_dialog_content = "Kamu mungkin memerintah prajurit, tapi mereka memilihmu untuk memimpin mereka.",
  ui_story_5083_50831500_35_dialog_content = "Ingatlah ini, Barton, kamu akan menemukan apapun itu di balik panggilan tugas di medan perang.",
  ui_story_5083_50831500_36_dialog_content = "Jika kamu tidak tahu siapa yang harus dipercaya, percayalah pada rekan-rekanmu. Tidak masalah jenis pemimpin apa yang kamu jadikan, mereka akan mengikuti.",
  ui_story_5083_50831500_37_dialog_content = "1st Legion bisa bertahan! Eclipsite raksasa merobek pembukaan untuk jenisnya menyerbu Gannon Escalator!",
  ui_story_5083_50831500_38_dialog_content = "Grand Marshal memberikan perintah untuk <color=#FFB400>meninggalkan kota</color>!",
  ui_story_5083_50831500_39_dialog_content = "Apa? Meninggalkan rumah kita?",
  ui_story_5083_50831500_40_dialog_content = "Apakah dia gila? Ini adalah jantung dari Illumina dan rumah kita! Ini seharusnya menjadi mercusuar yang tidak pernah padam!",
  ui_story_5083_50831500_41_dialog_content = "Mohon maaf, tetapi itu adalah perintahnya. Grand Marshal ingin beberapa pasukan tetap tinggal dan menutupi evakuasi warga sipil.",
  ui_story_5083_50831500_42_dialog_content = "Kemudian pasukan lainnya akan kembali, memperkuat, dan mengepung Darkover.",
  ui_story_5083_50831500_43_dialog_content = "Berikan perintahku. Semua personel, mundur! 2nd Legion akan melindungi penarikan!",
  ui_story_5083_50831500_44_dialog_content = "Ayo kita mengajak berkelahi, Tuan!",
  ui_story_5083_50831500_45_dialog_content = "<color=#e8d9bb>2nd Legion berbalik dan berlari menuju Gannon melawan kerumunan yang melarikan diri.</color>",
  ui_story_5083_50831500_46_dialog_content = "<color=#e8d9bb>Apa yang diikuti adalah hari-hari pertempuran tanpa henti. Legiun menderita kerugian besar tetapi mempertahankan eskalator dengan gagah berani.</color>",
  ui_story_5083_50831500_47_dialog_content = "<color=#e8d9bb>Pada akhirnya, bagaimanapun, tak terhitung jumlahnya Eclipsite berhasil menembus fasilitas—</color><color=#FFB400>Gannon telah jatuh, secara resmi.</color>",
  ui_story_5083_50831500_48_dialog_content = "Kelompok personel terakhir telah pergi. Sekarang giliranmu untuk pergi, Barton.",
  ui_story_5083_50831500_49_dialog_content = "Carrier kami telah mengalami kerusakan yang terlalu parah untuk mengevakuasi semua orang.",
  ui_story_5083_50831500_50_dialog_content = "Ini dia lagi, pria tua.",
  ui_story_5083_50831500_51_dialog_content = "Aku akan membawa orang-orang ke sana. Mereka semua adalah veteran, tidak seperti calon prajurit yang kamu miliki.",
  ui_story_5083_50831500_52_dialog_content = "Kamu bicara apa, sih? Ini sudah tidak ada harapan lagi...",
  ui_story_5083_50831500_53_dialog_content = "Saya akan mempertahankan Central Tower tidak peduli apa pun! Mempertahankan pusat kekuatan adalah mempertahankan jantung Gannon!",
  ui_story_5083_50831500_54_dialog_content = "Jika hancur seperti Undercity 13, cahaya akan padam di Gannon dan tidak ada penduduk Illumina yang bisa menemukan tujuan mereka.",
  ui_story_5083_50831500_55_dialog_content = "Tak akan kubiarkan hal itu terjadi pada mereka yang masih berjuang keras!",
  ui_story_5083_50831500_56_dialog_content = "Kalau begitu, bawa aku bersamamu!",
  ui_story_5083_50831500_57_dialog_content = "Saya senang kamu tidak melodramatis seperti Dogg, Barton. Saya tidak akan mengulangi sesuatu yang sentimental dua kali.",
  ui_story_5083_50831500_58_dialog_content = "Aku selalu percaya padamu, elit yang telah aku asah secara pribadi.",
  ui_story_5083_50831500_59_dialog_content = "Jadi ini adalah pelajaran terakhir.",
  ui_story_5083_50831500_60_dialog_content = "Ketika diperlukan, bahkan seorang jenderal harus membuka jalan bagi generasi masa depan!",
  ui_story_5083_50831500_61_dialog_content = "Saya tahu kamu akan menjadi pemimpin terbaik untuk 2nd Legion, Barton. Semuanya ada di tanganmu. Sekarang pergilah dari sini!",
  ui_story_5083_50831500_62_dialog_content = "Kamu tidak bisa membuatku pergi, Komandan Pango. Jangan buat aku harus menjatuhkanmu juga.",
  ui_story_5083_50831500_63_dialog_content = "Pengawal, bawa dia ke pembawa evakuasi... bahkan jika itu berarti mematahkan kakinya!",
  ui_story_5083_50831500_64_dialog_content = "Apa? Lepaskan aku!",
  ui_story_5083_50831500_65_dialog_content = "Kamu tidak bisa melakukan ini padaku, orang tua!",
  ui_story_5083_50831500_66_dialog_content = "Selamat tinggal, anak bermasalahku...",
  ui_story_5083_50831601_1_dialog_content = "Maaf kalian harus tetap tinggal, teman-teman.",
  ui_story_5083_50831601_2_dialog_content = "Mayor, aku ingin pasukanmu membuka jalan menuju sumber daya dengan segala cara. Bisakah kamu melakukannya?",
  ui_story_5083_50831601_3_dialog_content = "Siap, Pak!",
  ui_story_5083_50831601_4_dialog_content = "Berapa perkiraan kerugian untuk kamu?",
  ui_story_5083_50831601_5_dialog_content = "Kita semua akan tewas, Pak!",
  ui_story_5083_50831601_6_dialog_content = "...",
  ui_story_5083_50831601_7_dialog_content = "Tapi kami akan melakukannya, Pak!",
  ui_story_5083_50831601_8_dialog_content = "Baiklah... Saat kita sampai di sana, aku akan mengikuti perintahmu!",
  ui_story_5083_50831601_9_dialog_content = "Halo, Pak!",
  ui_story_5083_50831601_10_dialog_content = "Batalion pertama, bersiaplah untuk menyerang balik!",
  ui_story_5083_50831601_11_dialog_content = "Jangan takut. Kita hanya perlu bertahan sampai siang. Grand Marshal akan kembali untuk kita setelah mereka selesai dengan para Eclipsite mereka.",
  ui_story_5083_50831601_12_dialog_content = "Aku masih punya Lumamber, cukup baik untuk mengirimkan SOS.",
  ui_story_5083_50831601_13_dialog_content = "Sisanya terserah kepada kita, kita hanya perlu bertahan sampai fajar.",
  ui_story_5083_50831601_14_dialog_content = "Jadi ini akhirnya? Dengan kita melarikan diri sementara Gannon terbakar?",
  ui_story_5083_50831601_15_dialog_content = "Beep—Barton...",
  ui_story_5083_50831601_16_dialog_content = "Penyergapan! Penyergapan!",
  ui_story_5083_50831601_17_dialog_content = "Apa? Biarkan aku bertarung...",
  ui_story_5083_50831601_18_dialog_content = "Bangunlah, Barton.",
  ui_story_5083_50831601_19_dialog_content = "Apa yang terjadi...?",
  ui_story_5083_50831601_20_dialog_content = "Konvoi sedang diserang. Bangkit dan berjuang.",
  ui_story_5083_50831601_21_dialog_content = "<size=45>Sialan!</size>",
  ui_story_5083_50831601_22_dialog_content = "Tanganku mungkin terikat, tapi aku sedang kesal jadi jangan buat aku marah!",
  ui_story_5083_50831601_23_dialog_content = "Groar!",
  ui_story_5083_50831601_24_dialog_content = "Memukul rahangku lagi.",
  ui_story_5083_50831601_25_dialog_content = "Kutukan... Seseorang lepaskan borgol ini dariku!",
  ui_story_5083_50831601_26_dialog_content = "Tunggu sebentar... Saya terkena pukulan di rahang dan sama sekali tidak terasa sakit?",
  ui_story_5083_50831601_27_dialog_content = "Jangan hanya berdiri di sana, teruslah berjuang!",
  ui_story_5083_50831601_28_dialog_content = "Langkahi dulu mayatku!",
  ui_story_5083_50831601_29_dialog_content = "Ini pasti mimpi. Saya tidak memiliki rahang besi saat saya masih muda.",
  ui_story_5083_50831601_30_dialog_content = "Aku paham sekarang... Ini adalah mimpi buruk yang aku terjebak di dalamnya.",
  ui_story_5083_50831601_31_dialog_content = "Beep—Akhirnya kamu ingat, Barton?",
  ui_story_5083_50831601_32_dialog_content = "Apa yang membuatmu terjebak?",
  ui_story_5083_50831601_33_dialog_content = "Aku tersesat... Tapi aku selalu percaya bahwa selama aku terus berjuang, cahaya akan bersinar di depanku.",
  ui_story_5083_50831601_34_dialog_content = "Namun kamu masih terjebak di sini.",
  ui_story_5083_50831601_35_dialog_content = "Aku tidak tahu. Aku tidak ingat apa-apa... Aku tidak pikir aku melarikan diri, tapi tidak ingat apa yang aku lakukan setelah itu...",
  ui_story_5083_50831601_36_dialog_content = "Aku hanya ingat komandan dalam pertempuran itu...",
  ui_story_5083_50831601_37_dialog_content = "Kemudian saya berada di pertempuran terakhir, berjuang dengan segala yang saya miliki tetapi terluka parah, dan itulah bagaimana saya dipasangi \"iron jaw\".",
  ui_story_5083_50831601_38_dialog_content = "Banyak tentara yang tidak mengerti itu dan melihatku sebagai pengecut yang meninggalkan komandannya. Aku adalah orang asing bagi mereka.",
  ui_story_5083_50831601_39_dialog_content = "Aku ingin bertarung sampai mati di samping Komandan Pango... Lupakan, aku tidak peduli jika itu hanya mimpi.",
  ui_story_5083_50831601_40_dialog_content = "Mimpi buruk tidak berarti apa-apa bagiku. Selalu ada kesempatan berikutnya! Tidak peduli berapa kali mencoba, aku akan mengubahnya...",
  ui_story_5083_50831601_41_dialog_content = "Terima hasilnya dan tunggu sampai waktu berikutnya.. Apakah ini cara kamu memaafkan diri sendiri, Barton?",
  ui_story_5083_50831601_42_dialog_content = "Jika kamu bisa meninggalkannya, kenapa kamu selalu kembali kemari?",
  ui_story_5083_50831601_43_dialog_content = "Tahukah kamu berapa kali kamu telah melalui ini? Dan berapa banyak \"kali berikutnya\" yang telah kamu miliki?",
  ui_story_5083_50831601_44_dialog_content = "Kenapa kamu...",
  ui_story_5083_50831601_45_dialog_content = "Kapan \"waktu berikutnya\" itu?",
  ui_story_5083_50831601_46_dialog_content = "Siapa kau?",
  ui_story_5083_50831601_47_dialog_content = "Sudah jelas sejak awal. Saya akan selalu menjadi navigator Anda, Barton.",
  ui_story_5083_50831601_48_dialog_content = "Bagiku, yang bisa melihat cahaya tapi tidak menyentuhnya, jalan itu telah ada di bawah kakimu sejak aku mengenalmu.",
  ui_story_5083_50831601_49_dialog_content = "Tunggu, maksudmu kamu adalah...",
  ui_story_5083_50831601_50_dialog_content = "Kita harus pergi, Kolonel Barton.",
  ui_story_5083_50831601_51_dialog_content = "Kemana kita bisa pergi? Undercity 19?",
  ui_story_5083_50831601_52_dialog_content = "Gannon telah jatuh... Akankah kita bisa mendapatkannya kembali?",
  ui_story_5083_50831601_53_dialog_content = "<size=45>Damn it!</size>",
  ui_story_5083_50831601_54_dialog_content = "<color=#e8d9bb>Dengan teriakan, Barton menghancurkan belenggu itu.</color>",
  ui_story_5083_50831601_55_dialog_content = "Benar, aku adalah kambing hitam, \"elit\" yang membangkang!",
  ui_story_5083_50831601_56_dialog_content = "Kenapa harus aku mentolerir ini?",
  ui_story_5083_50831601_57_dialog_content = "Saya memulai revolusi dan sekarang saatnya!",
  ui_story_5083_50831601_58_dialog_content = "Semua dari kamu di 2nd Legion!",
  ui_story_5083_50831601_59_dialog_content = "Kolonel Barton? Misi kami adalah membawa Anda ke tempat yang aman. Tolong jangan membuatnya sulit bagi kami.",
  ui_story_5083_50831601_60_dialog_content = "Tidak, kita tidak memiliki keselamatan untuk dibicarakan!",
  ui_story_5083_50831601_61_dialog_content = "Di Astra yang dilanda Eclipsite, hanya ada satu rumah yang bisa kita kembali.",
  ui_story_5083_50831601_62_dialog_content = "Kalian semua berlatih di sana, jadi seharusnya kalian masih ingat betapa terangnya cahaya itu!",
  ui_story_5083_50831601_63_dialog_content = "Kita tidak lahir untuk berkeliaran! Kemana kita bisa kembali jika kita tidak pergi ke Gannon?",
  ui_story_5083_50831601_64_dialog_content = "Atasan kita sedang berjuang untuk hidupnya dan dia membutuhkan bantuan! Apakah kamu mendengar terompet? Gannon memanggil kita!",
  ui_story_5083_50831601_65_dialog_content = "Jika kita ditakdirkan mati dalam pertempuran, aku ingin mati bersama kalian semua yang berada di bawah komandoku, mati dalam pertempuran untuk Gannon!",
  ui_story_5083_50831601_66_dialog_content = "Aku akan membawamu pulang. Meskipun itu berakhir hanya dengan namamu di sebuah plakat...",
  ui_story_5083_50831601_67_dialog_content = "Selama cahaya beacon masih ada, mereka yang mengikuti kita akan memiliki keinginan untuk melanjutkan!",
  ui_story_5083_50831601_68_dialog_content = "Saya bersedia mengikutimu, Kolonel Barton. Perintah Grand Marshal adalah untuk kita membela Gannon. Kita tidak akan pernah menentangnya.",
  ui_story_5083_50831601_69_dialog_content = "Aku juga! Aku telah mengikuti Barton sejak awal. Aku percaya pada Barton yang sama yang telah berjuang bersama kita.",
  ui_story_5083_50831601_70_dialog_content = "Pemimpin peleton dan rekrutan lainnya mati melindungi saya. Saya tidak keberatan mengorbankan diri saya untuk melindungi Gannon.",
  ui_story_5083_50831601_71_dialog_content = "Hitung saya masuk. Siapa pun yang ingin menemui Kolonel Barton harus melewati kami terlebih dahulu.",
  ui_story_5083_50831601_72_dialog_content = "Kalian...",
  ui_story_5083_50831601_73_dialog_content = "Sudah fajar, Barton.",
  ui_story_5083_50831601_74_dialog_content = "Ya, aku melihat jalannya... Semua lampu kalian menunjukkan jalan untukku.",
  ui_story_5083_50831601_75_dialog_content = "Perusahaan, berbalik! Mari kita akhiri malam ini... Mari kita ambil kembali Gannon!",
  ui_story_5083_50831601_76_dialog_content = "<color=#e8d9bb>Jadi para prajurit berbalik dan berbaris menuju Gannon.</color>",
  ui_story_5083_50831601_77_dialog_content = "<color=#e8d9bb>Mereka semua menyadari bahwa mereka akan mati di sana, tetapi tidak ada yang melambat.</color>",
  ui_story_5083_50831601_78_dialog_content = "<color=#e8d9bb>Tanpa cahaya mereka, tidak akan ada fajar di Astra.</color>",
  ui_story_5083_50831601_79_dialog_content = "<color=#e8d9bb>Krisis Darkover yang telah menyiksa negeri ini selama delapan tahun mungkin sudah berakhir karena para pendahulu yang tangguh. Sebagai penerus mereka, menjadi tugas saya untuk melanjutkan hingga akhir.</color>",
  ui_story_5083_50831601_80_dialog_content = "Pasukanmu telah hancur, Aurorian yang tak berarti. Semua kehidupan akan musnah di hadapanku, <color=#FFB400>Lonceng Kiamat</color>.",
  ui_story_5083_50831601_81_dialog_content = "Meludah!",
  ui_story_5083_50831601_82_dialog_content = "<color=#e8d9bb>Musuh raksasa itu mendekati Menara Sentral. Menutupi kulit batunya yang membara adalah kolase serpihan logam jelek untuk baju besi.</color>",
  ui_story_5083_50831601_83_dialog_content = "<color=#e8d9bb>Siapa pun yang memeriksa stempel pada potongan-potongan itu bisa mengenali bahwa mereka berasal dari undercities yang berbeda. Mereka mewakili kemenangan monster seperti lencana kehormatan.</color>",
  ui_story_5083_50831601_84_dialog_content = "<color=#e8d9bb>Itu menyeramkan dan menjengkelkan pada saat yang sama.</color>",
  ui_story_5083_50831601_85_dialog_content = "<color=#e8d9bb>Saat melangkah maju, serpihan-serpihan itu bertabrakan dengan suara klang yang tumpul seolah-olah membunyikan requiem yang penuh kebencian.</color>",
  ui_story_5083_50831601_86_dialog_content = "Ah, kamu menggigil, Tiny One. Ya, aku bisa mencium ketakutanmu. Bahkan bendera di tanganmu pun bergetar.",
  ui_story_5083_50831601_87_dialog_content = "Semua hama itu sama. Mereka semua takut pada yang kuat. Itu naluri mereka. Berlututlah untukku hancurkan dengan senang hati.",
  ui_story_5083_50831601_88_dialog_content = "Ya, aku gemetar... Aku tidak menyangka aku akan sebegitu takutnya di usiaku ini.",
  ui_story_5083_50831601_89_dialog_content = "Mungkin itu insting, seperti yang kamu katakan.",
  ui_story_5083_50831601_90_dialog_content = "Jadi kamu mengakuinya? Lalu berlutut dan memohon belas kasihan! Ini adalah kebahagiaan terbesarku.",
  ui_story_5083_50831601_91_dialog_content = "Apa kamu bercanda, orang jelek tolol? Apakah kamu berpikir kamu sedang berhadapan dengan sekelompok pengecut?",
  ui_story_5083_50831601_92_dialog_content = "Kamu tidak tahu betapa berbedanya kamu dari kami!",
  ui_story_5083_50831601_93_dialog_content = "Tidak akan ada kebahagiaan untukmu. Yang akan kamu lihat hanyalah betapa tegarnya tulang punggung orang-orang Illumina!",
  ui_story_5083_50831601_94_dialog_content = "Aurorian memiliki rasa takut, tapi begitu juga Eclipsite, dan kamu tidak akan pernah belajar untuk mengatasinya seperti yang kami lakukan.",
  ui_story_5083_50831601_95_dialog_content = "Aku bilang tidak... Tidak ada kesempatan kamu melewati garis kami!",
  ui_story_5083_50831601_96_dialog_content = "Maka akan kubuktikan itu.",
  ui_story_5083_50831601_97_dialog_content = "Maaf, Pak, ini adalah yang terbaik yang bisa kami lakukan... Kenapa bantuan belum datang juga...?",
  ui_story_5083_50831601_98_dialog_content = "Saya lihat sudah saatnya menipu prajuritmu. Silakan, tunjukkan Lumamber dan beritahu mereka bahwa bantuan akan segera datang.",
  ui_story_5083_50831601_99_dialog_content = "Itulah kebohongan yang dilakukan setiap officer di setiap Undercity yang telah kuhancurkan...",
  ui_story_5083_50831601_100_dialog_content = "Tidak ada bantuan yang datang bahkan ketika saya menghembuskan nafas terakhir dari mereka. Itu adalah kepura-puraan yang paling konyol untuk Illumina.",
  ui_story_5083_50831601_101_dialog_content = "Maaf, kawan-kawan. Kamu mempercayakan nyawamu padaku, namun aku tidak bisa menjanjikan apa-apa sebagai balasannya.",
  ui_story_5083_50831601_102_dialog_content = "Tapi tolong percaya padaku saat aku bilang Illumina tidak akan pernah meninggalkan para pembelanya!",
  ui_story_5083_50831601_103_dialog_content = "<color=#e8d9bb>Pango melepaskan Lumamber dan menarik tuas dalam doa. Cahaya melengkung melintasi kegelapan di atas Gannon yang terjatuh dan menuju langit.</color>",
  ui_story_5083_50831601_104_dialog_content = "<color=#e8d9bb>Prajurit yang berjuang keras di Gannon menatap kilatan cahaya secara serentak, dengan pantulan </color><color=#FFB400>harapan</color><color=#e8d9bb> yang bersinar di mata mereka.</color>",
  ui_story_5083_50831601_105_dialog_content = "Anda sendirian, tetapi Anda masih berbohong pada diri sendiri dan menyebutnya iman. Nah, menghancurkan pejuang yang penuh iman jauh lebih menyenangkan daripada menghancurkan hama biasa!",
  ui_story_5083_50831601_106_dialog_content = "Sialan kamu, Eclipsite, inilah mengapa kamu tak akan pernah mendapatkannya... Kami, prajurit Illumina, disebut \"Pembela Astra\" dengan alasan!",
  ui_story_5083_50831601_107_dialog_content = "Aku adalah Syurton. Ingatlah nama ini, nama penghancurmu!",
  ui_story_5083_50831601_108_dialog_content = "Bunuh mereka semua. Hancurkan Central Tower. Saya ingin Gannon dihancurkan sampai tak tersisa.",
  ui_story_5083_50831601_109_dialog_content = "2nd Legion tidak pernah mundur!",
  ui_story_5083_50831601_110_dialog_content = "<color=#e8d9bb>Sinyal di langit meredup dan akhirnya jatuh. Semua harapan tampaknya hilang dalam kegelapan.</color>",
  ui_story_5083_50831601_111_dialog_content = "2nd Legion? Aku mendengar itu beberapa hari yang lalu. Dia bahkan memotongku di kepala dan punggung.",
  ui_story_5083_50831601_112_dialog_content = "Sayang sekali dia dan para prajuritnya begitu menyedihkan. Aku menyimpan pedangnya, meski begitu. Lihat ini? Bukan kenang-kenangan yang buruk.",
  ui_story_5083_50831601_113_dialog_content = "Anjing! Maafkan aku...",
  ui_story_5083_50831601_114_dialog_content = "<color=#e8d9bb>Penuh dengan putus asa, para veteran mencengkeram senjata mereka dan bersiap untuk menyerang entitas raksasa tersebut.</color>",
  ui_story_5083_50831601_115_dialog_content = "<color=#e8d9bb>Namun, bintang selalu bersinar terang di malam yang paling gelap.</color>",
  ui_story_5083_50831601_116_dialog_content = "<size=45>Itu sudah cukup jauh!</size>",
  ui_story_5083_50831601_117_dialog_content = "<size=45>Coba ukuran ini!</size>",
  ui_story_5083_50831601_118_dialog_content = "Kamu yang menggali kuburanmu sendiri, dasar orang tolol besar!",
  ui_story_5083_50831601_119_dialog_content = "<color=#e8d9bb>Kendaraan lapis baja turun dan menabrak punggung Eclipsite raksasa, dengan meriam menimbulkan kerusakan maksimal pada jarak yang sangat dekat.</color>",
  ui_story_5083_50831601_120_dialog_content = "Ahhhh!",
  ui_story_5083_50831601_121_dialog_content = "Aku menangkapmu... Aduh!",
  ui_story_5083_50831601_122_dialog_content = "Terima kasih, teman!",
  ui_story_5083_50831601_123_dialog_content = "Ini absurd, meledakkan kendaraan! Dan kamu hampir...",
  ui_story_5083_50831601_124_dialog_content = "Ini bukan aku tanpa yang gila, 'kan?",
  ui_story_5083_50831601_125_dialog_content = "Inilah aku yang sebenarnya, kamu tahu!",
  ui_story_5083_50831601_126_dialog_content = "Apa yang kau lakukan kembali di sini, kau bodoh?!",
  ui_story_5083_50831601_127_dialog_content = "Bukankah kamu yang mengirim sinyal SOS? Apakah aku tidak dianggap sebagai bala bantuan yang sah?",
  ui_story_5083_50831601_128_dialog_content = "Keuntungan telah jatuh. Saya datang dengan kendaraan dan sekarang tidak punya jalan kembali meskipun kamu tidak menginginkan saya di sini.",
  ui_story_5083_50831601_129_dialog_content = "Apa-apaan kau…!",
  ui_story_5083_50831601_130_dialog_content = "Ini sudah kali ketiga! Jangan terus suruh saya pergi, pria tua!",
  ui_story_5083_50831601_131_dialog_content = "Saya mendapat pesan untuk para Eclipsite: Bahkan di bawah tanah di mana kamu tidak melihat matahari, mereka masih tidak memiliki tempat ini!",
  ui_story_5083_50831601_132_dialog_content = "Gannon pasti akan cerah lagi, pasti!",
  ui_story_5083_50831601_133_dialog_content = "Bodoh, kita mungkin sudah mati sebelum bantuan datang!",
  ui_story_5083_50831601_134_dialog_content = "Dalam hal itu, saya harap cahaya dari beacon akan menyinari tubuh kita.",
  ui_story_5083_50831601_135_dialog_content = "Ledakan itu hampir membuatku jatuh dari tepi, sialan.",
  ui_story_5083_50831601_136_dialog_content = "Apa? Masih hidup dalam dua bagian?",
  ui_story_5083_50831601_137_dialog_content = "Kamu pikir aku bisa dibunuh oleh ledakan semata setelah menghancurkan begitu banyak undercity? Aku adalah <color=#FFB400>nemesis dari semua yang hidup</color>!",
  ui_story_5083_50831601_138_dialog_content = "Lucu, menyebut dirimu sendiri sebagai nemesis dari semua yang hidup, hanya untuk ternyata telah hidup sepanjang waktu.",
  ui_story_5083_50831601_139_dialog_content = "Diam dan mari kita lakukan ini!",
  ui_story_5083_50831601_140_dialog_content = "Tunggu saja sampai aku dan teman-teman mengirimmu ke neraka!",
  ui_story_5083_50831602_1_dialog_content = "Kamu tidak bisa membunuhku!",
  ui_story_5083_50831602_2_dialog_content = "Heh, semua omongan tentang tulang punggung yang tak bisa dipatahkan... Aku tidak melihatmu bangun.",
  ui_story_5083_50831602_3_dialog_content = "Kurang ajar! Mati saja kau!",
  ui_story_5083_50831602_4_dialog_content = "Kamu juga bisa pergi ke sana dengannya!",
  ui_story_5083_50831602_5_dialog_content = "<color=#e8d9bb>Barton menghindari pukulan tinju dan berlari di lengan makhluk itu.</color>",
  ui_story_5083_50831602_6_dialog_content = "<color=#e8d9bb>Sebelum Syurton bisa bereaksi, dia mencabut piala—pisau Dogg—itu.</color>",
  ui_story_5083_50831602_7_dialog_content = "<color=#e8d9bb>Dua pedang itu menyatu menjadi satu di genggaman Barton dan menjadi miliknya. Dia menghindar dan menyerang Syurton tanpa henti.</color>",
  ui_story_5083_50831602_8_dialog_content = "<color=#e8d9bb>Dalam sekejap, leher Syurton teriris, menyebabkan dia mengibaskan dan melontarkan api.</color>",
  ui_story_5083_50831602_9_dialog_content = "<color=#e8d9bb>Tapi Barton hanya terus melanjutkan serangan sambil api menyembur. Serangan yang sempurna ini adalah hasil dari </color><color=#FFB400> latihan </color><color=#e8d9bb> yang tak terhitung jumlahnya di basis.</color>",
  ui_story_5083_50831602_10_dialog_content = "<color=#e8d9bb>Dan yang lebih mengerikan adalah tatapan membunuh di mata Barton.</color>",
  ui_story_5083_50831602_11_dialog_content = "<color=#e8d9bb>Dia melompat melalui api, membelah kegelapan dan menusukkan pedangnya dalam-dalam ke leher Syurton.</color>",
  ui_story_5083_50831602_12_dialog_content = "Lepaskan aku!",
  ui_story_5083_50831602_13_dialog_content = "Jangan berpikir untuk melukai Kolonel Barton! Bidik matanya!",
  ui_story_5083_50831602_14_dialog_content = "Ini adalah akhirnya... Dan beginilah cara saya menggunakan pistol, pak!",
  ui_story_5083_50831602_15_dialog_content = "<color=#e8d9bb>Barton menggambar dan menembakkan pistol. Peluru itu menghantam pedang berbilah ganda dan menancapkannya sepenuhnya ke dalam Syurton.</color>",
  ui_story_5083_50831602_16_dialog_content = "<color=#e8d9bb>Kemudian dia menekan remote untuk menandai bahan peledak yang dia tanam di dalam pedangnya.</color>",
  ui_story_5083_50831602_17_dialog_content = "<color=#e8d9bb>Tidak ada yang bisa menebak Barton akan mengorbankan senjata miliknya dan teman dekatnya demi kemenangan.</color>",
  ui_story_5083_50831602_18_dialog_content = "Tidak! <color=#FFB400>Ibu</color>...",
  ui_story_5083_50831602_19_dialog_content = "Nikmati penghinaanmu di jurang, goblog sia.",
  ui_story_5083_50831602_20_dialog_content = "Kamu yakin ini baik-baik saja?",
  ui_story_5083_50831602_21_dialog_content = "Dogg akan selamanya ada di hati kita dan di peringatan.",
  ui_story_5083_50831602_22_dialog_content = "Kehendaknya sudah cukup untuk membawa kita maju. Tidak ada yang lain yang diperlukan.",
  ui_story_5083_50831602_23_dialog_content = "Oh, apakah kamu baik-baik saja, Commander Pango?",
  ui_story_5083_50831602_24_dialog_content = "Jangan sentuh dia. Pukulan itu telah mematahkan tulang belakangnya.",
  ui_story_5083_50831602_25_dialog_content = "Awas, Kolonel Barton, Eclipsite yang lebih kecil masih bergerak!",
  ui_story_5083_50831602_26_dialog_content = "Jaga baik-baik... bendera 2nd Legion... Kamu adalah komandannya sekarang, Barton... Pimpin para prajurit... dan bertarunglah hingga napas terakhir...",
  ui_story_5083_50831602_27_dialog_content = "Percaya... rekan-rekanmu di Illumina... bantuan akan datang...",
  ui_story_5083_50831602_28_dialog_content = "Dia keluar!",
  ui_story_5083_50831602_29_dialog_content = "Kurang ajar, kurang ajar!",
  ui_story_5083_50831602_30_dialog_content = "2nd Legion tidak akan pernah berkompromi!",
  ui_story_5083_50831602_31_dialog_content = "The 2nd Legion will never compromise!",
  ui_story_5083_50831602_32_dialog_content = "<color=#e8d9bb>Eclipsite raksasa itu sudah mati, tetapi pertempuran masih berlanjut. Lebih banyak Eclipsite kecil menyerbu satu-satunya jalan masuk dan melawan para soldiers.</color>",
  ui_story_5083_50831602_33_dialog_content = "<color=#e8d9bb>Dengan panji di tangan, Barton bertarung bersama para pejuang sampai mereka berada di belakang stasiun listrik.</color>",
  ui_story_5083_50831602_34_dialog_content = "<color=#e8d9bb>Ketika dia melihat sekeliling, sangat sedikit pria yang tersisa.</color>",
  ui_story_5083_50831602_35_dialog_content = "Ini sudah cukup jauh!",
  ui_story_5083_50831602_36_dialog_content = "Meskipun hanya kita yang tersisa, kita tidak akan pernah berkompromi... tidak akan pernah berkompromi...",
  ui_story_5083_50831602_37_dialog_content = "Aku akan bertarung bersamamu sampai momen terakhir, Barton.",
  ui_story_5083_50831602_38_dialog_content = "Kami akan mengikuti Kolonel Barton sampai nafas terakhir kami.",
  ui_story_5083_50831602_39_dialog_content = "Kita akan mati mempertahankan jalan ini!",
  ui_story_5083_50831602_40_dialog_content = "Apa yang sedang aku lakukan? Bodoh sekali aku! Kenapa baru sekarang aku memikirkannya?",
  ui_story_5083_50831602_41_dialog_content = "Aku sudah tahu bagaimana ini akan berakhir.",
  ui_story_5083_50831602_42_dialog_content = "Dulu, kita terpaksa mundur setelah hampir mengalahkan si bodoh besar itu, tetapi Pango tetap bertahan dan bertarung.",
  ui_story_5083_50831602_43_dialog_content = "Setiap orang bersamanya meninggal, dan dia jatuh koma akibat luka selama lebih dari satu dekade.",
  ui_story_5083_50831602_44_dialog_content = "...",
  ui_story_5083_50831602_45_dialog_content = "Saya tidak memiliki mata seperti milikmu, PlayerName, jadi saya iri bagaimana kamu selalu bisa melihat cahaya.",
  ui_story_5083_50831602_46_dialog_content = "Tapi aku tidak tersesat, karena aku benar-benar percaya akan ada cahaya jika kita berjuang sampai akhir.",
  ui_story_5083_50831602_47_dialog_content = "Ketika pertama kali bertemu denganmu, memang kamu sedang berada di jalan harapan.",
  ui_story_5083_50831602_48_dialog_content = "Saya merasa terhormat mengenalmu. Kaulah yang telah menyelamatkan kita berdua berkali-kali.",
  ui_story_5083_50831602_49_dialog_content = "Kamu adalah seorang pahlawan, namun diganggu oleh mimpi buruk... Aku ingin membimbingmu...",
  ui_story_5083_50831602_50_dialog_content = "Aku tidak takut tersesat selama ada kamu di sisiku, dan mimpi buruk bukanlah apa-apa bagiku.",
  ui_story_5083_50831602_51_dialog_content = "Tapi aku hanya tidak bisa melepaskannya...",
  ui_story_5083_50831602_52_dialog_content = "Apakah bala bantuan pernah datang untuk Komandan Pango?",
  ui_story_5083_50831602_53_dialog_content = "Benar, kok bisa aku lupa, ya...?",
  ui_story_5083_50831602_54_dialog_content = "Komandan Pango, dia adalah \"mimpi buruk\" yang sebenarnya bagi saya...",
  ui_story_5083_50831602_55_dialog_content = "Masa depan Illumina penuh dengan harapan, tetapi apakah kita benar-benar meninggalkan para veteran di masa lalu?",
  ui_story_5083_50831602_56_dialog_content = "Aku merasa gugup hanya dengan memikirkannya. Aku tidak ingin mereka mati dengan penyesalan dan putus asa.",
  ui_story_5083_50831602_57_dialog_content = "Tidak, Barton, Illumina tidak akan pernah meninggalkan para pembelanya.",
  ui_story_5083_50831602_58_dialog_content = "Untungnya, akhirnya kamu datang juga. Tolong lihat.",
  ui_story_5083_50831602_59_dialog_content = "Ikutlah bersamaku, garda depan. Cepat dan jangan biarkan para veteran menunggu!",
  ui_story_5083_50831602_60_dialog_content = "Para non-kombatan sudah aman. Sekarang mari kita rebut kembali Gannon!",
  ui_story_5083_50831602_61_dialog_content = "<color=#e8d9bb>Reinhardt muncul, mengayunkan tombak berapi dan menembus garis pertahanan Eclipsite. Kobaran api menerangi kota seperti matahari pagi.</color>",
  ui_story_5083_50831602_62_dialog_content = "Saya melihat cahaya...",
  ui_story_5083_50831602_63_dialog_content = "Lihat, Komandan Pango, cahaya! Bantuan di sini! Mereka kembali!",
  ui_story_5083_50831602_64_dialog_content = "Kami tidak ditinggalkan. Bangun dan lihat!",
  ui_story_5083_50831602_65_dialog_content = "<color=#e8d9bb>Lonceng berdentang di Gannon, mengumumkan kedatangan bala bantuan, menandakan kembalinya penghuni sah kota ini.</color>",
  ui_story_5083_50831602_66_dialog_content = "<size=45>Komandan Pango...!</size>",
  ui_story_5083_50831602_67_dialog_content = "Berhenti menangis, kamu anak nakal... Aku belum mati...",
  ui_story_5083_50831602_68_dialog_content = "Aku bukan tuli... Tentu saja aku mendengar...",
  ui_story_5083_50831602_69_dialog_content = "Mereka datang tepat pada waktunya... Aku pikir aku tidak akan pernah melihat mereka...",
  ui_story_5083_50831602_70_dialog_content = "Ini keren... Sungguh, sangat keren...",
  ui_story_5083_50831602_71_dialog_content = "Masa depan legion dan Illumina kini ada di tanganmu, nak... Jaga sikapmu dan jadilah lebih serius...",
  ui_story_5083_50831602_72_dialog_content = "Aku akan, Komandan Pango. Aku tak akan mengecewakanmu.",
  ui_story_5083_50831602_73_dialog_content = "Biarkan mereka merawat komandan, Barton. Kita harus pergi sekarang.",
  ui_story_5083_50831602_74_dialog_content = "Ikuti cahaya itu di dalam hatimu... Itu adalah imanmu.",
  ui_story_5083_50831602_75_dialog_content = "Ini adalah <color=#FFB400>perjalanan</color> terakhir. Saatnya meninggalkan mimpi buruk di belakang.",
  ui_story_5083_50831602_76_dialog_content = "Oh, tentu saja. Tak ada yang bisa menahanku lagi!",
  ui_story_5083_50831602_77_dialog_content = "Selamat tinggal, Komandan Pango.",
  ui_story_5083_50831602_78_dialog_content = "?!",
  ui_story_5083_50831602_79_dialog_content = "Mimpi itu berubah kembali menjadi kenyataan... Apakah itu ingatanmu?",
  ui_story_5083_50831602_80_dialog_content = "Komandan Pango dan para veteran tidak pernah menyerah dan bahkan tidak membiarkan panji jatuh.",
  ui_story_5083_50831602_81_dialog_content = "Mereka memegang Gannon dan mempertahankan cahaya kita.",
  ui_story_5083_50831602_82_dialog_content = "Tidur, Barton... Ini hari baru, dan beristirahat mudah bagimu ketika kamu di rumah.",
  ui_story_5083_50831602_83_dialog_content = "Komandan Pango... PlayerName... Setiap orang... Terima kasih semua... karena telah membiarkan kita menempuh jalan tanpa keraguan...",
  ui_story_5083_50831602_84_dialog_content = "<color=#e8d9bb>Saya menjadi saksi betapa tangguhnya bintang-bintang, bangkit dan menerangi langit malam.</color>",
  ui_story_5083_50831602_85_dialog_content = "<color=#e8d9bb>Serta keberanian para Aurorian, yang memancarkan kilauan kehidupan bahkan di hadapan kematian.</color>",
  ui_story_5083_50831602_86_dialog_content = "<color=#e8d9bb>Pahlawan-pahlawan mempertahankan bara yang membangun menjadi kobaran api, membakar Darkover untuk menyambut fajar.</color>",
  ui_story_5083_50831602_87_dialog_content = "<color=#e8d9bb>Bahkan ketika sebuah bintang kehilangan cahayanya dan jatuh, mereka yang disinari tetap teguh di jalur itu, terus mencari jalan mereka hingga fajar tiba.</color>",
  ui_story_5083_50831602_88_dialog_content = "<color=#e8d9bb>Dan itu sudah cukup...</color>",
  ui_story_5083_50831602_89_dialog_content = "<color=#e8d9bb>Terima kasih, semua, bintang lama.</color>"
}
return config
